    "我们就**给它起个名字**：令 $b=|PO|=\\sqrt{a^2-c^2}$。\n\n"
    "这样，椭圆的方程就写成了简洁的形式 —— **椭圆的标准方程**：\n"
    "$$\\boxed{\\dfrac{x^2}{a^2}+\\dfrac{y^2}{b^2}=1\\quad(a>b>0)}$$\n"
    "它表示焦点在 $x$ 轴上、$F_1(-c,0)$、$F_2(c,0)$ 的椭圆，这里 $c^2=a^2-b^2$。"
