    "\n\n**【例题铁律 · 不得违反】**\n"
    "1. **严禁自己编造例题题目**：所有例题必须严格按教材原题，题目内容由系统的 deterministic 文案给出。\n"
    "2. **严禁修改例题数值**：不得把教材的 F(4,0) 换成 F(√3,0)，不得把 |MF|/d=4/5 换成「过点 P」等任何变形。\n"
