# ── ASYMPTOTE 2 个 sub-phase 的子目标（v3.47 按教材 p122-123 探究路径重设计） ──
# 教材路径：探究具体双曲线 x²/9-y²/4=1 拖点感知 → 推广一般 y=±(b/a)x → 命名渐近线
_H322_ASYMPTOTE_PHASE_GOALS = {
    "explore_concrete": (
        "🧩 **渐近线 phase 1 · 教材探究**（教材 p122-123 图 3.2-9）。"
        "学生在右边沙盒里拖动具体双曲线 $\\dfrac{x^2}{9}-\\dfrac{y^2}{4}=1$ 右支上的点 M，"
        "观察 $x_M$ 与 M 到直线 $\\dfrac{x}{3}-\\dfrac{y}{2}=0$ 的距离 $d$ 的关系。\n"
        "**期望学生发现两件事**：① $x_M$ 越大 $d$ 越小（无限接近）；② 但 $d$ 始终 $\\ne 0$（不相交）。\n"
        "学生命中『越来越近 / 不相交 / 接近但不为 0 / 不会碰到 / d 趋于 0』等关键词即推进 phase 2。\n"
        "**严禁**：直接给『渐近线』名称、提及 $b/a$ 公式（这是 phase 2 的内容）。"
    ) + _H322_VIZ_SUPPRESSION,
    "generalize_equation": (
        "🧩 **渐近线 phase 2 · 推广到一般式**。具体例子里 $\\dfrac{x}{3}\\pm\\dfrac{y}{2}=0$ 即 $y=\\pm\\dfrac{2}{3}x$。"
        "学生应观察到：$\\dfrac{2}{3}=\\dfrac{b}{a}$（因为 $a=3, b=2$）。\n"
        "推广：对任意 $a, b$，双曲线 $\\dfrac{x^2}{a^2}-\\dfrac{y^2}{b^2}=1$ 的渐近线是 $y=\\pm\\dfrac{b}{a}x$。\n"
        "学生答出『$y=\\pm\\dfrac{b}{a}x$』或『一般情形 $y=\\pm(b/a)x$』即完成全 stage。\n"
        "**严禁**：跳到例题、提及离心率（下一 stage）。"
    ) + _H322_VIZ_SUPPRESSION,
}

