        "引导推导：$e^2=\\dfrac{c^2}{a^2}=\\dfrac{a^2+b^2}{a^2}=1+\\dfrac{b^2}{a^2}$，所以 $\\dfrac{b}{a}=\\sqrt{e^2-1}$。\n"
        "学生答出『$b/a=\\sqrt{e^2-1}$』或『e 越大，渐近线斜率越大』即完成全 stage。\n"
