_EXAMPLE_CONTEXT_MAP_H321 = {
    1: ("**例 1（教材 p120 例 1）**\n题目：双曲线焦点 F₁(-5,0), F₂(5,0)，双曲线上一点 P 到 F₁、F₂ 的距离差的绝对值=6，求标准方程。\n"
        "标准答案：a=3 (2a=6), c=5 (2c=10), b²=c²-a²=16；标准方程 x²/9 - y²/16 = 1。"),
    2: ("**例 2（教材 p120 例 2）**\n题目：A、B 两地相距 800 m，A 地听到炮弹声响比 B 地**晚** 2 s（不是早！），声速 340 m/s，求炮弹爆炸点 P 的轨迹方程。\n"
        "建系：A、B 在 x 轴上，原点为 AB 中点。|PA|-|PB|=340×2=680（P 离 A 远）。\n"
        "标准答案：a=340 (2a=680), c=400 (2c=800), b²=c²-a²=44400；P 在双曲线**右支**，x≥340；方程 x²/115600 - y²/44400 = 1 (x≥340)。"),
    "exploration": ("**探究（教材 p121）—— 与 3.1.1 例 3 对比**\n题目：点 A、B 坐标分别为 (-5,0), (5,0)，直线 AM、BM 相交于点 M，斜率之积是 **4/9**（不是 -4/9！），求 M 的轨迹方程。\n"
        "斜率：k_AM=y/(x+5), k_BM=y/(x-5)。代入 k_AM·k_BM=4/9 → 9y²=4(x²-25) → x²/25 - y²/(100/9) = 1 (x≠±5)。\n"
        "结论：M 的轨迹是双曲线（除去 (±5,0) 两点）。"),
}

