    def _stage_aware_viz_request(self, student_text: str) -> tuple:
        """学生显式要求动画时，返回 (生成请求, 标题)。
        - ellipse_311 课：用阶段预设的安全请求（防剧透、防跑题）
        - 其它课：退化为学生原话（保持旧行为）
        """
        if self.course_type == "ellipse_311":
            req, title = self._E311_STAGE_VIZ_REQUEST.get(
                self.stage,
                ("根据当前教学阶段画一个帮助理解的几何示意图，不要泄露学生还没发现的结论。",
                 "辅助理解动画"),
            )
            return req, title
        # 非结构化课程：沿用旧逻辑（学生原话）
        return student_text, (student_text[:40] + "…" if len(student_text) > 40 else student_text)

    def _llm_generate_viz(self, student_text: str) -> Optional[str]:
        """调 LLM 生成可视化 JS 代码。返回代码字符串，失败返回 None。"""
        llm = self._get_llm()
        if llm is None:
            return None
        kg_context = self._build_kg_context(student_text)
        # VIZ 去重上下文
        if self.viz_history:
            viz_dedup = (
                "## ⚠️ 已生成的可视化（不要重复）\n"
                "以下可视化已经在画布上展示过，请生成**不同角度或不同知识点**的可视化：\n"
                + "\n".join(f"- {desc}" for desc in self.viz_history[-5:])
                + "\n如果学生的请求与已有可视化高度相似，请从新角度切入（如换参数、换视角、增加对比）。\n"
            )
        else:
            viz_dedup = ""
        system = self._VIZ_SYSTEM_PROMPT.format(kg_context=kg_context, viz_dedup=viz_dedup)
        # 阶段约束：DISCOVER_E 之前不能在可视化中出现离心率、参数 b、结论性文字
        stage_constraint = ""
        if self.stage not in self.course_config["eccentricity_stages"]:
            stage_constraint = (
                "\n\n## ⚠️ 当前阶段约束（必须遵守）\n"
                "当前课程还没有引入以下概念，可视化中**严格禁止**出现：\n"
                "- 离心率、eccentricity、e = c/a、e 值\n"
                "- 标准方程 x²/a² + y²/b² = 1\n"
                "- 短半轴 b（不要在代码注释、变量名或标注中出现 b 这个参数名）\n"
                "只能展示焦点、焦距 2c、长轴 2a（绳长）、形状变化等直观内容。\n\n"
                "## ⚠️ 结论性文字禁令\n"
                "这是**探究阶段**，学生应自己发现规律。可视化的 text 标注中：\n"
                "- **禁止**写「X 越大/越小，Y 越什么」的因果结论\n"
                "- **禁止**写「绳长越长，椭圆越扁/越圆」等总结性文字\n"
                "- **允许**写操作提示（如「拖动滑轨观察变化」）和当前参数数值\n"
                "- **允许**写参数标签（如 '2c = 3.0'、'2a = 6.0'）"
            )
        try:
            code = llm.complete(
                system + stage_constraint, f"学生请求：{student_text}",
                max_tokens=1500, temperature=0.3,
            )
            # 清理可能的 markdown 代码块标记
            if code.startswith("```"):
                code = code.split("\n", 1)[1] if "\n" in code else code[3:]
            if code.endswith("```"):
                code = code[:-3].rstrip()
            return code if code else None
        except Exception as e:
            print(f"[LLM generate_viz] 全部 provider 失败：{type(e).__name__}: {e}")
            return None

    @staticmethod
    def _parse_viz_marker(text: str):
        """解析 LLM 回复中的 [VIZ: 描述] 标记。

        返回 (clean_message, viz_description) 元组。
        如果没有标记，viz_description 为 None。

        v3.55（2026-05-28 pilot 前修补）：
          · 原实现只匹配末尾的 [VIZ:...]（`\\s*$` 结尾），
            真实数据里 LLM 经常把 VIZ 放在回复**中间**（后面跟续写文本），
            导致前端字面显示 [VIZ: ...]，1334 轮中 38 例（2.8%）泄露。
          · 现在匹配任意位置；多个 VIZ 取第一个描述，全部从 message 剥离。
          · ABCD 4 档共享修补，与 agent 消融实验无关。
        """
        matches = list(re.finditer(r'\[VIZ:\s*(.+?)\]', text, re.DOTALL))
        if not matches:
            return text, None
        viz_desc = matches[0].group(1).strip()
        # 剥离所有 [VIZ:...] 标记
        clean_msg = re.sub(r'\[VIZ:\s*.+?\]', '', text, flags=re.DOTALL).strip()
        # 清理可能残留的多余空行
        clean_msg = re.sub(r'\n{3,}', '\n\n', clean_msg)
        return clean_msg, viz_desc

