    def start(self) -> LessonStep:
        """开始课程（根据 course_type 加载对应的开场白和初始阶段）"""
        intro_msg = self._INTRO_MESSAGES[self.course_type]
        # v2.1: 椭圆 3.1.1 课只发开场问题（圆的定义回忆），不立即激活画布
        if self.course_type == "ellipse_311":
            step = LessonStep(
                stage=LessonStage.E311_INTRO.value,
                message=intro_msg,
                canvas_action={"action": "clear"},
            )
            self.stage = LessonStage.E311_RECALL_CIRCLE  # 等学生回答圆的定义
            self._log("tutor", step.message)
            return step
        # v3.23: 椭圆 3.1.2 课开场（回顾 abc 几何含义），随后 INTRO handler 推进到 RANGE
        if self.course_type == "ellipse_312":
            step = LessonStep(
                stage=LessonStage.E312_INTRO.value,
                message=intro_msg,
                canvas_action=_STAGE_MANDATORY_VIZ.get(LessonStage.E312_INTRO),
            )
            self.stage = LessonStage.E312_INTRO  # INTRO handler 在学生回答 abc 后推进
            self._log("tutor", step.message)
            return step
        # v3.37: 双曲线 3.2.1 课开场（回忆椭圆 → "差等于常数"自然提问），不立即激活画布
        if self.course_type == "hyperbola_321":
            step = LessonStep(
                stage=LessonStage.H321_INTRO.value,
                message=intro_msg,
                canvas_action={"action": "clear"},
            )
            self.stage = LessonStage.H321_INTRO  # _handle_h321_intro 处理学生第一句回答
            self._log("tutor", step.message)
            return step
        # v3.46: 双曲线 3.2.2 课开场（回忆 e312 几何性质 5 维），不立即激活画布
        if self.course_type == "hyperbola_322":
            step = LessonStep(
                stage=LessonStage.H322_INTRO.value,
                message=intro_msg,
                canvas_action={"action": "clear"},
            )
            self.stage = LessonStage.H322_INTRO  # _handle_h322_intro 处理学生第一句回答
            self._log("tutor", step.message)
            return step
        # v3.x: 抛物线 3.3.1 课开场（承接 3.2.2 离心率 e，引出 k=1），不立即激活画布
        if self.course_type == "parabola_331":
            step = LessonStep(
                stage=LessonStage.P331_INTRO.value,
                message=intro_msg,
                canvas_action={"action": "clear"},
            )
            self.stage = LessonStage.P331_INTRO  # _handle_p331_intro 处理学生第一句回答
            self._log("tutor", step.message)
            return step
        # v3.x: 抛物线 3.3.2 课开场（承接 3.3.1，由方程研究几何性质），不立即激活画布
        if self.course_type == "parabola_332":
            step = LessonStep(
                stage=LessonStage.P332_INTRO.value,
                message=intro_msg,
                canvas_action={"action": "clear"},
            )
            self.stage = LessonStage.P332_INTRO  # _handle_p332_intro 处理学生第一句回答
            self._log("tutor", step.message)
            return step

        step = LessonStep(
            stage=self.course_config["first_stage"].value,
            message=intro_msg,
            canvas_action={"action": "clear"},
        )
        self.stage = self.course_config["start_stage"]
        self._log("tutor", step.message)
        return step

    def on_student_message(self, text: str) -> LessonStep:
        """处理学生文本输入

        架构：LLM 主导 + 知识图谱 + 状态机护栏 + LLM 自主可视化

        流程：
        1. 状态机按阶段分发到对应 handler（含关键词推进 + LLM 回复）
        2. 解析 LLM 回复中的 [VIZ: 描述] 标记
        3. 如有标记 → 调 _llm_generate_viz 生成 JS 代码 → 附加到 canvas_action
        4. 如学生显式请求动画但 LLM 没给标记 → 兜底触发

        可视化触发完全由 LLM 决定：学生主动请求、连续答不出、需要视觉辅助等，
        LLM 在系统提示词指导下自行判断。对双曲线/抛物线/立体几何课程通用。
        """
        self._log("student", text)
        text = text.strip()
        # 2026-05-28：每轮开始重置 internal_actions 埋点 dict（默认全 False/None，
        # 沿途的 anti-spoiler / D-1 / D-2 / TA 决策路径会按需写入）
        self._last_internal_actions = {
            "anti_spoiler_blocked": False,
            "anti_spoiler_hit_keywords": [],
            "anti_spoiler_raw_text": None,
            "d1_proposed": False,
            "d1_proposed_to_stage": None,
            "d1_fsm_accepted": None,
            "d1_reject_reason": None,
            "d2_peer_proposed": False,
            "d2_softgate_pass": None,
            "ta_self_review_triggered": False,
            "ta_diagnosis": None,
            "ta_correction_injected": False,
        }

        # ---- 多 agent pilot：费曼侧路进行中 → 走侧路 handler，主线 FSM 不动 ----
        # off 模式下 self._feynman_state 永远是 None（_maybe_enter_feynman 短路）
        if getattr(self, "_feynman_state", None) is not None:
            return self._handle_feynman_turn(text)

        # ---- D-2（仅 D 档）：LLM 启发式提议同学出场（软门控审核）----
        # 启发式预筛触发后通过软门控 → 召唤同学（不动 stage），学生答完同学退回主线
        if _ma_d2_peer_enabled():
            self._d2_turn_counter = getattr(self, "_d2_turn_counter", 0) + 1
            _d2_peer_q = self._maybe_d2_propose_peer(text)
            if _d2_peer_q:
                self._last_agent = "peer"
                # event_type 已在 _maybe_d2_propose_peer 内设置 "llm_propose_peer"
                return LessonStep(
                    stage=self.stage.value,
                    message=f"🧑‍🎓 **同学**：{_d2_peer_q}",
                    canvas_action=None,
                )

        # v3.x: 3.3.1 跨 stage 跳级支持 —— 学生在任何 parabola_331 stage 说"看例 N"/"看天线"即跳
        if (self.course_type == "parabola_331"
                and self.stage not in (LessonStage.P331_EXAMPLE_1, LessonStage.P331_EXAMPLE_2,
                                        LessonStage.P331_SUMMARY)):
            skip_n = _looks_like_skip_to_example_331(text)
            if skip_n is not None:
                target_stage, target_intro = {
                    1: (LessonStage.P331_EXAMPLE_1, P331_EXAMPLE_1_INTRO),
                    2: (LessonStage.P331_EXAMPLE_2, P331_EXAMPLE_2_INTRO),
                }[skip_n]
                self.stage = target_stage
                # 新题独立 subflags（避免上题状态污染）
                if not hasattr(self, "_p331_example_subflags"):
                    self._p331_example_subflags = {1: set(), 2: set()}
                    self._p331_example_phase_idx = {1: 0, 2: 0}
                self._p331_example_subflags[skip_n] = set()
                self._p331_example_phase_idx[skip_n] = 0
                self._p331_example_done_awaiting_next = None
                viz = _STAGE_MANDATORY_VIZ.get(target_stage)
                step = LessonStep(
                    stage=self.stage.value,
                    message=f"好的，切到例 {skip_n}（教材 3.3.1 节原题）：\n\n" + target_intro,
                    canvas_action=viz,
                )
                self._log("tutor", step.message)
                return step

        # v3.x: 3.3.2 跨 stage 跳级支持 —— 学生在性质阶段说"看例题/思考"即跳（例题/思考 stage 内部自处理 skip）
        if (self.course_type == "parabola_332"
                and self.stage not in (LessonStage.P332_EXAMPLE_1, LessonStage.P332_THINK,
                                        LessonStage.P332_EXAMPLE_2, LessonStage.P332_SUMMARY)):
            skip_n = _looks_like_skip_to_example_332(text)
            if skip_n is not None:
                step = self._jump_to_p332_example(skip_n)
                self._log("tutor", step.message)
                return step

        # v3.46: 3.2.2 跨 stage 跳级支持 —— 学生在任何 hyperbola_322 stage 说"直接看例 N"即跳
        if self.course_type == "hyperbola_322" and self.stage != LessonStage.H322_SUMMARY:
            skip_n = _looks_like_skip_to_example_322(text)
            if skip_n is not None:
                target_stage, target_intro = {
                    1: (LessonStage.H322_EXAMPLE_1, H322_EXAMPLE_1_INTRO),
                    2: (LessonStage.H322_EXAMPLE_2, H322_EXAMPLE_2_INTRO),
                    3: (LessonStage.H322_EXAMPLE_3, H322_EXAMPLE_3_INTRO),
                }[skip_n]
                self.stage = target_stage
                # 新题独立 subflags（避免上题状态污染）
                self._h322_example_subflags = set()
                self._h322_example_active = skip_n
                self._h322_example_done_awaiting_next = None
                viz = _STAGE_MANDATORY_VIZ.get(target_stage)
                step = LessonStep(
                    stage=self.stage.value,
                    message=(f"好的，我们直接看例 {skip_n}（教材 3.2.2 节原题；"
                             f"几何性质的探究可以例题后再回来 📒）：\n\n" + target_intro),
                    canvas_action=viz,
                )
                self._log("tutor", step.message)
                return step

        # v3.35/v3.36: 3.1.2 跨 stage 跳级支持 —— 学生在任何 ellipse_312 stage（含 EXAMPLE_*）
        # 说"直接看例 N"即可切到对应 E312_EXAMPLE_N，发 hard-coded 教材原题
        # 例外：SUMMARY 不允许跳（已结课）
        if self.course_type == "ellipse_312" and self.stage != LessonStage.E312_SUMMARY:
            skip_n = _looks_like_skip_to_example_312(text)
            if skip_n is not None:
                target_stage, target_intro = {
                    1: (LessonStage.E312_EXAMPLE_1, E312_EXAMPLE_1_INTRO),
                    2: (LessonStage.E312_EXAMPLE_2, E312_EXAMPLE_2_INTRO),
                    3: (LessonStage.E312_EXAMPLE_3, E312_EXAMPLE_3_INTRO),
                }[skip_n]
                self.stage = target_stage
                viz = _STAGE_MANDATORY_VIZ.get(target_stage)
                step = LessonStep(
                    stage=self.stage.value,
                    message=(f"好的，我们直接看例 {skip_n}（教材 3.1.2 节原题；"
                             f"几何性质的探究可以例题后再回来 📒）：\n\n" + target_intro),
                    canvas_action=viz,
                )
                self._log("tutor", step.message)
                return step

        # ---- 第一步：阶段分发，获得 LLM 回复 ----
        # 椭圆课
        if self.stage == LessonStage.AWAIT_CIRCLE:
            step = self._handle_await_circle(text)
        elif self.stage == LessonStage.EXPLORE_TWO_FOCI:
            reply = self._llm_respond(text, fallback=NUDGE_TO_CANVAS_MSG)
            step = LessonStep(stage=self.stage.value, message=reply)
        elif self.stage == LessonStage.AWAIT_SHAPE_NAME:
            step = self._handle_await_name(text)
        elif self.stage == LessonStage.EXPLORE_C:
            step = self._handle_explore_c(text)
        elif self.stage == LessonStage.TRANSITION_TO_A:
            step = self._handle_transition_to_a(text)
        elif self.stage == LessonStage.EXPLORE_A:
            step = self._handle_explore_a(text)
        elif self.stage == LessonStage.DISCOVER_E:
            step = self._handle_discover_e(text)
        elif self.stage == LessonStage.SUMMARY:
            step = self._handle_summary(text)
        # 双曲线课
        elif self.stage == LessonStage.HYP_RECALL_ELLIPSE:
            step = self._handle_hyp_recall_ellipse(text)
        elif self.stage == LessonStage.HYP_EXPLORE_TWO_FOCI:
            reply = self._llm_respond(text, fallback="先去右边画布拖动点 P，画出轨迹吧～")
            step = LessonStep(stage=self.stage.value, message=reply)
        elif self.stage == LessonStage.HYP_AWAIT_SHAPE_NAME:
            step = self._handle_hyp_await_name(text)
        elif self.stage == LessonStage.HYP_EXPLORE_C_AND_A:
            step = self._handle_hyp_explore_c_and_a(text)
        elif self.stage == LessonStage.HYP_DISCOVER_E:
            step = self._handle_hyp_discover_e(text)
        elif self.stage == LessonStage.HYP_SUMMARY:
            step = self._handle_summary(text)  # 复用通用结课逻辑
        # 抛物线课
        elif self.stage == LessonStage.PAR_RECALL_CONIC:
            step = self._handle_par_recall_conic(text)
        elif self.stage == LessonStage.PAR_EXPLORE_FOCUS_DIRECTRIX:
            reply = self._llm_respond(text, fallback="先去右边画布拖动点 P，画出轨迹吧～")
            step = LessonStep(stage=self.stage.value, message=reply)
        elif self.stage == LessonStage.PAR_AWAIT_SHAPE_NAME:
            step = self._handle_par_await_name(text)
        elif self.stage == LessonStage.PAR_EXPLORE_P:
            step = self._handle_par_explore_p(text)
        elif self.stage == LessonStage.PAR_DISCOVER_E:
            step = self._handle_par_discover_e(text)
        elif self.stage == LessonStage.PAR_SUMMARY:
            step = self._handle_summary(text)  # 复用通用结课逻辑
        # ---- v4.0: 6 门教材对齐课走 _STAGE_DISPATCH 注册表 ----
        # E311/E312/H321/H322/P331/P332 共 66 个阶段，
        # 全部通过注册表查 (method_name, kwargs) 进行分发，取代原 ~190 行 if/elif。
        elif self.stage in _STAGE_DISPATCH:
            method_name, kwargs = _STAGE_DISPATCH[self.stage]
            step = getattr(self, method_name)(text, **kwargs)

        else:
            # v3.14：路由失败保护——self.stage 不在任何 elif 分支里。
            # 触发原因（按可能性高→低）：
            #   1. LessonStage 加了新值但忘记加 dispatcher 分支
            #   2. 某处代码错把 stage 设成了 enum 之外的字符串
            # 加日志方便定位；测试 test_dispatcher_coverage 会在加新 stage
            # 没挂分支时立刻挂掉，避免静默退化为"我们继续……"。
            try:
                stage_repr = self.stage.value if hasattr(self.stage, "value") else repr(self.stage)
            except Exception:
                stage_repr = repr(self.stage)
            print(f"[路由失败] ⚠️ on_student_message 没匹配到 stage = {stage_repr}（course_type={self.course_type}）"
                  f"——回退到通用提示。请检查 dispatcher 是否漏了 elif。")
            step = LessonStep(stage=stage_repr,
                              message="（系统提示）当前阶段没有对应的处理器。请刷新或重新选课。")

        # ---- 第二步：可视化处理 ----
        # v3.37: 双曲线 3.2.1 课——与 311/312 同策略（路径 2 协议硬约束），
        #   剥掉 LLM 可能误输出的 [VIZ:] 标记，**完全不走** _llm_generate_viz 路径
        #   （后端 stage 入口已有 mandatory viz，足够覆盖 H321 全课程教学需求）
        #   修复 issue：H321 学生在 EXPLORE_LOCUS 等阶段收到的 LLM 自由 ack 含 [VIZ:..]
        #   被前端解析为 run_generated_viz 后 code 不完整 → Unexpected EOF 红错。
        # v3.46: 双曲线 3.2.2 课沿用同策略
        # v3.53: 抛物线 3.3.1 课沿用同策略——所有动画由确定性 viz 提供，
        #   剥掉 LLM 误输出的 [VIZ:] 标记，**完全不走** _llm_generate_viz（防野生动画）
        if self.course_type in ("hyperbola_321", "hyperbola_322", "parabola_331", "parabola_332"):
            clean_msg, viz_desc = self._parse_viz_marker(step.message)
            if viz_desc:
                step.message = clean_msg
            self._log("tutor", step.message)
            return step

        # v2.4.1: ellipse_311 是固定结构化课程 —— 学生要动画时**一定给确定性动画**，
        #   完全不走会失败的 LLM 生成路径（没 API key / API 挂 / LLM 生成的代码有 bug
        #   都会导致"承诺了动画却不出现"）。每个阶段对应哪个确定性动画见
        #   _E311_STAGE_VIZ_ON_REQUEST。其它课程仍走原来的 LLM 生成路径。
        if self.course_type in ("ellipse_311", "ellipse_312"):
            # 先剥掉 LLM 可能误输出的 [VIZ:] 标记（这两门课不用 LLM 生成动画）
            clean_msg, viz_desc = self._parse_viz_marker(step.message)
            if viz_desc:
                step.message = clean_msg
            # 学生明确要动画 → 查表给当前阶段的确定性动画
            # v3.21：REFLECT_GEOM_YAXIS yaxis phase 也接受"对比/y 轴"等隐式 viz 词
            if self._e311_is_viz_intent(text):
                # v3.15 方案 A：先按关键词做 stage 内细分路由；命中不到再走默认表
                if self.course_type == "ellipse_311":
                    det_viz = self._e311_resolve_request_viz(self.stage, text)
                else:
                    det_viz = _E312_STAGE_VIZ_ON_REQUEST.get(self.stage)
                if det_viz:
                    # 消息里若没提到"动画/可视化"，补一句确认（fallback 模式下尤其需要）
                    if not any(kw in step.message for kw in ["动画", "可视化", "看图", "右边", "右侧"]):
                        step.message = "好的，我们来看一个动画 👇\n\n" + step.message
                    # 合并 canvas_action
                    if step.canvas_action:
                        existing = step.canvas_action if isinstance(step.canvas_action, list) else [step.canvas_action]
                        existing.append(det_viz)
                        step.canvas_action = existing
                    else:
                        step.canvas_action = det_viz
        else:
            # ---- 其它课程：保留原 LLM 生成动画路径 ----
            clean_msg, viz_desc = self._parse_viz_marker(step.message)
            if viz_desc:
                viz_code = self._llm_generate_viz(viz_desc)
                step.message = clean_msg
                if viz_code:
                    self.viz_history.append(viz_desc)
                    viz_action = {"action": "run_generated_viz", "code": viz_code,
                                  "title": "🎨 " + (viz_desc[:40] + "…" if len(viz_desc) > 40 else viz_desc)}
                    if step.canvas_action:
                        existing = step.canvas_action if isinstance(step.canvas_action, list) else [step.canvas_action]
                        existing.append(viz_action)
                        step.canvas_action = existing
                    else:
                        step.canvas_action = viz_action
            elif self._wants_viz(text):
                viz_request, viz_title = self._stage_aware_viz_request(text)
                viz_code = self._llm_generate_viz(viz_request)
                if viz_code:
                    self.viz_history.append(viz_title)
                    viz_action = {"action": "run_generated_viz", "code": viz_code, "title": "🎨 " + viz_title}
                    if step.canvas_action:
                        existing = step.canvas_action if isinstance(step.canvas_action, list) else [step.canvas_action]
                        existing.append(viz_action)
                        step.canvas_action = existing
                    else:
                        step.canvas_action = viz_action

        self._log("tutor", step.message)
        return step

    def on_canvas_event(self, event_type: str, payload: Optional[dict] = None) -> Optional[LessonStep]:
        """处理画布交互事件，返回 None 表示无需回应。

        通用设计：前端在 payload 中附带 trail_count（已固化的历史曲线数），
        用于衡量探索充分性。对椭圆/双曲线/抛物线通用。
        """
        payload = payload or {}
        MIN_TRAILS_BEFORE_NUDGE = 2

        # ---- 轨迹完成事件 ----
        if event_type == "trail_completed":
            if self.stage == LessonStage.EXPLORE_TWO_FOCI:
                self.trail_completed = True
                self.stage = LessonStage.AWAIT_SHAPE_NAME
                step = LessonStep(stage=self.stage.value, message=AWAIT_NAME_MSG)
                self._log("tutor", step.message)
                return step
            elif self.stage == LessonStage.HYP_EXPLORE_TWO_FOCI:
                self.trail_completed = True
                self.stage = LessonStage.HYP_AWAIT_SHAPE_NAME
                msg = (
                    "你画出了两条对称的开放曲线！\n\n"
                    "**你觉得这是什么图形？** 和椭圆有什么不同？"
                )
                step = LessonStep(stage=self.stage.value, message=msg)
                self._log("tutor", step.message)
                return step
            elif self.stage == LessonStage.PAR_EXPLORE_FOCUS_DIRECTRIX:
                self.trail_completed = True
                self.stage = LessonStage.PAR_AWAIT_SHAPE_NAME
                msg = (
                    "你画出了一条开放的U形曲线！\n\n"
                    "**你觉得这是什么图形？** 试着说出它的名字。"
                )
                step = LessonStep(stage=self.stage.value, message=msg)
                self._log("tutor", step.message)
                return step
            # ---- v2.1: 椭圆 3.1.1 课的探究阶段 ----
            elif self.stage == LessonStage.E311_EXPLORE_STRING:
                self.trail_completed = True
                self.stage = LessonStage.E311_AWAIT_SHAPE_NAME
                step = LessonStep(stage=self.stage.value, message=E311_AWAIT_SHAPE_NAME_MSG)
                self._log("tutor", step.message)
                return step
            # ---- v3.37: 双曲线 3.2.1 课的探究阶段 ----
            elif self.stage == LessonStage.H321_EXPLORE_LOCUS:
                self.trail_completed = True
                self.stage = LessonStage.H321_AWAIT_SHAPE_NAME
                step = LessonStep(stage=self.stage.value, message=H321_AWAIT_SHAPE_NAME_MSG)
                self._log("tutor", step.message)
                return step
            # ---- v3.x: 抛物线 3.3.1 课的探究 1（拖 H 画 trail）----
            elif self.stage == LessonStage.P331_EXPLORE_LOCUS:
                self.trail_completed = True
                self.stage = LessonStage.P331_AWAIT_SHAPE_NAME
                step = LessonStep(
                    stage=self.stage.value,
                    message=P331_AWAIT_SHAPE_NAME_MSG,
                    canvas_action={"action": "show_p331_locus_solved"},
                )
                self._log("tutor", step.message)
                return step

        # ---- v3.x: P331 别名（前端可能直接发 p331_trail_completed）----
        if event_type == "p331_trail_completed":
            if self.stage == LessonStage.P331_EXPLORE_LOCUS:
                self.trail_completed = True
                self.stage = LessonStage.P331_AWAIT_SHAPE_NAME
                step = LessonStep(
                    stage=self.stage.value,
                    message=P331_AWAIT_SHAPE_NAME_MSG,
                    canvas_action={"action": "show_p331_locus_solved"},
                )
                self._log("tutor", step.message)
                return step


        # ---- v3.17 #2：思考2 find_segments 阶段的点击作答事件 ----
        # 学生在画布上点对了所有 3 条线段 → 切到 yaxis phase + 发 solved viz
        if event_type == "find_segments_completed":
            if (self.stage == LessonStage.E311_REFLECT_GEOM_YAXIS
                    and getattr(self, "_e311_geom_phase", "find_segments") == "find_segments"):
                self._e311_geom_phase = "yaxis"
                msg = (
                    "🎯 三条线段都点对了！\n"
                    + E311_DEFINE_B_MSG + "\n\n" + E311_REFLECT_YAXIS_MSG
                )
                step = LessonStep(
                    stage=self.stage.value,
                    message=msg,
                    canvas_action={"action": "show_e311_abc_triangle_solved"},
                )
                self._log("tutor", step.message)
                return step
            return None

        # ---- v3.24: 椭圆 3.1.2 INTRO 阶段的 abc 复习点线段事件 ----
        # 学生点对 a/b/c 三条线段 → 切到 RANGE 并发 range_setup viz
        if event_type == "e312_abc_quiz_completed":
            if self.stage == LessonStage.E312_INTRO:
                self.stage = LessonStage.E312_RANGE
                self._e312_range_phase = "predict"
                ack = "🎯 三条线段都点对了！a 是长半轴、b 是短半轴、c 是半焦距。"
                step = LessonStep(
                    stage=self.stage.value,
                    message=ack + "\n\n" + E312_RANGE_PREDICT_MSG,
                    canvas_action=_STAGE_MANDATORY_VIZ.get(LessonStage.E312_RANGE),
                )
                self._log("tutor", step.message)
                return step
            return None

        # ---- v3.23: 椭圆 3.1.2 VERTICES 阶段的点击作答事件 ----
        # 学生在沙盒 8 候选点中点击 → 累积命中；点对 4 个顶点 → 切到 name phase 并发 solved viz
        if event_type == "e312_vertex_clicked":
            if (self.stage == LessonStage.E312_VERTICES
                    and getattr(self, "_e312_vertices_phase", "compute") == "compute"):
                if not hasattr(self, "_e312_vertices_correct_hits"):
                    self._e312_vertices_correct_hits = set()
                pt = (payload or {}).get("point")   # 期待 [x, y]
                if pt and len(pt) == 2:
                    key = (int(pt[0]), int(pt[1]))
                    # 顶点候选：(±a, 0) 和 (0, ±b)，相对单位用 a=2, b=1（前端沙盒坐标系约定）
                    canonical_vertices = {(-2, 0), (2, 0), (0, -1), (0, 1)}
                    if key in canonical_vertices:
                        self._e312_vertices_correct_hits.add(key)
                if self._e312_vertices_correct_hits == {(-2, 0), (2, 0), (0, -1), (0, 1)}:
                    self._e312_vertices_phase = "name"
                    step = LessonStep(
                        stage=self.stage.value,
                        message=E312_VERTICES_NAME_MSG,
                        canvas_action={"action": "show_e312_vertices_solved"},
                    )
                    self._log("tutor", step.message)
                    return step
            return None

        # v3.46 双曲线 3.2.2 顶点点击事件（前端沙盒坐标 a=2, b=1.4 约定）
        if event_type == "h322_vertex_clicked":
            if (self.stage == LessonStage.H322_VERTICES_AXES
                    and getattr(self, "_h322_vertices_phase", "vertex_compute") == "vertex_compute"):
                if not hasattr(self, "_h322_vertices_correct_hits"):
                    self._h322_vertices_correct_hits = set()
                pt = (payload or {}).get("point")
                if pt and len(pt) == 2:
                    key = (int(pt[0]), int(pt[1]))
                    # 双曲线只有 2 个真顶点：A₁(-a, 0), A₂(a, 0)（前端用 a=2）
                    canonical_vertices = {(-2, 0), (2, 0)}
                    if key in canonical_vertices:
                        self._h322_vertices_correct_hits.add(key)
                # 两个真顶点都点中 → 进入 axes_name phase，引导实/虚轴术语
                if self._h322_vertices_correct_hits == {(-2, 0), (2, 0)}:
                    self._h322_vertices_phase = "axes_name"
                    step = LessonStep(
                        stage=self.stage.value,
                        message=(
                            "✅ 没错！双曲线的顶点**只有 2 个**：$A_1(-a, 0), A_2(a, 0)$。\n\n"
                            "（因为令 $x=0$ 代入方程得到 $y^2=-b^2$ 没有实数解 —— 双曲线**与 y 轴不相交**。）\n\n"
                            "**下一步 · 术语**：教材把线段 $A_1A_2$ 叫做双曲线的**实轴**（长 $=2a$），"
                            "把 $B_1(0,-b), B_2(0,b)$ 连成的线段叫做**虚轴**（长 $=2b$）。\n\n"
                            "请你用自己的话**复述**一下：双曲线**只有 2 个顶点**，线段 $A_1A_2$ 叫什么？$B_1B_2$ 又叫什么？"
                        ),
                        canvas_action={"action": "show_h322_vertices_solved_with_rect"},
                    )
                    self._log("tutor", step.message)
                    return step
                # 还没点全 → 给个简短鼓励（first hit）
                elif len(self._h322_vertices_correct_hits) == 1:
                    step = LessonStep(
                        stage=self.stage.value,
                        message=(
                            "✅ 你点中了 1 个顶点（绿色）。再找找看，**还有一个真顶点**在哪里？\n\n"
                            "（提示：让 $y=0$ 代入方程，$x$ 取哪些值？）"
                        ),
                    )
                    self._log("tutor", step.message)
                    return step
            return None

        # v3.x: 抛物线 3.3.2 顶点点击（唯一顶点=原点；前端点击主路径 + 文字兜底）
        if event_type == "p332_vertex_clicked":
            if self.stage == LessonStage.P332_VERTEX:
                pt = (payload or {}).get("point")
                if pt and len(pt) == 2 and int(pt[0]) == 0 and int(pt[1]) == 0:
                    self._p332_clear_stuck("vertex")
                    self.stage = LessonStage.P332_ECCENTRICITY
                    step = LessonStep(
                        stage=self.stage.value,
                        message=P332_VERTEX_DONE_MSG,
                        canvas_action=[{"action": "show_p332_vertex_solved"},
                                       {"action": "show_p332_ecc_setup"}],
                    )
                    self._log("tutor", step.message)
                    return step
            return None

        # 学生连续 3 次点错 → 转 LLM 兜底，鼓励用文字回答
        if event_type == "find_segments_stuck":
            if (self.stage == LessonStage.E311_REFLECT_GEOM_YAXIS
                    and getattr(self, "_e311_geom_phase", "find_segments") == "find_segments"):
                expected = (payload or {}).get("expected", "")
                hint_map = {
                    "a":         "正确答案：$|PF_1|$ 和 $|PF_2|$ 都等于 $a$（椭圆定义 $|PF_1|+|PF_2|=2a$，P 是短轴端点，对称性使两段相等）。",
                    "c":         "正确答案：$|OF_1| = |OF_2| = c$（$F_1$、$F_2$ 关于原点对称，距离都是焦距的一半）。",
                    "sqrt_diff": "正确答案：$|OP| = \\sqrt{a^2 - c^2}$（直角三角形 $OPF_1$ 中，斜边 $|PF_1|=a$，一直角边 $|OF_1|=c$，另一直角边就是 $|OP|=\\sqrt{a^2-c^2}$）。",
                }
                hint = hint_map.get(expected, "")
                msg = ("看起来这道有点卡住——没关系，我直接告诉你：\n\n"
                       + hint + "\n\n你也可以在左边对话框里描述（比如『|OP|=√(a²-c²)』），"
                       "我们继续。")
                step = LessonStep(stage=self.stage.value, message=msg)
                self._log("tutor", step.message)
                return step
            return None

        # ---- 椭圆课滑轨事件 ----
        if event_type == "focus_slider_changed" and self.stage == LessonStage.EXPLORE_C:
            self.c_slider_changes += 1
            trail_count = payload.get("trail_count", 0)
            if trail_count == MIN_TRAILS_BEFORE_NUDGE and not self._c_nudge_sent:
                self._c_nudge_sent = True
                step = LessonStep(
                    stage=self.stage.value,
                    message=(
                        "画布上已经有几条不同颜色的椭圆了 🎨\n\n"
                        "仔细比较它们的形状，**你观察到了什么规律？**\n"
                        "试着用自己的话描述一下，然后在左边输入框告诉我。"
                    ),
                )
                self._log("tutor", step.message)
                return step
            return None

        if event_type == "sum_slider_changed" and self.stage == LessonStage.EXPLORE_A:
            self.a_slider_changes += 1
            trail_count = payload.get("trail_count", 0)
            if trail_count == MIN_TRAILS_BEFORE_NUDGE and not self._a_nudge_sent:
                self._a_nudge_sent = True
                step = LessonStep(
                    stage=self.stage.value,
                    message=(
                        "你已经试了几种不同的 2a 值，画布上有几条椭圆了。\n\n"
                        "**和刚才改变 2c 的时候相比，你发现了什么不同？**\n"
                        "把你的观察告诉我。"
                    ),
                )
                self._log("tutor", step.message)
                return step
            return None

        # ---- 双曲线课滑轨事件 ----
        if event_type == "hyp_slider_changed" and self.stage == LessonStage.HYP_EXPLORE_C_AND_A:
            self.slider_changes["hyp"] = self.slider_changes.get("hyp", 0) + 1
            trail_count = payload.get("trail_count", 0)
            if trail_count == MIN_TRAILS_BEFORE_NUDGE and not self._nudge_sent.get("hyp"):
                self._nudge_sent["hyp"] = True
                step = LessonStep(
                    stage=self.stage.value,
                    message=(
                        "画布上已经有几条不同参数的双曲线了。\n\n"
                        "和椭圆相比，**你注意到什么不同？**\n"
                        "特别关注渐近线（虚线）的变化，把观察告诉我。"
                    ),
                )
                self._log("tutor", step.message)
                return step
            return None

        # ---- 抛物线课滑轨事件 ----
        if event_type == "par_slider_changed" and self.stage == LessonStage.PAR_EXPLORE_P:
            self.slider_changes["par"] = self.slider_changes.get("par", 0) + 1
            trail_count = payload.get("trail_count", 0)
            if trail_count == MIN_TRAILS_BEFORE_NUDGE and not self._nudge_sent.get("par"):
                self._nudge_sent["par"] = True
                step = LessonStep(
                    stage=self.stage.value,
                    message=(
                        "画布上已经有几条不同 p 值的抛物线了。\n\n"
                        "**p 变大/变小时，抛物线的形状有什么变化？**\n"
                        "把你的观察告诉我。"
                    ),
                )
                self._log("tutor", step.message)
                return step
            return None

        return None

    def state(self) -> dict:
        return {
            "course_type": self.course_type,
            "stage": self.stage.value,
            "trail_completed": self.trail_completed,
            "c_slider_changes": self.c_slider_changes,
            "a_slider_changes": self.a_slider_changes,
            "slider_changes": self.slider_changes,
            "history_len": len(self.history),
        }

    # ----- 内部处理 -----

    def _handle_await_circle(self, text: str) -> LessonStep:
        if _looks_like_circle_def(text):
            self.stage = LessonStage.EXPLORE_TWO_FOCI
            return LessonStep(
                stage=self.stage.value,
                message=EXPLORE_TWO_FOCI_MSG,
                canvas_action={
                    "action": "init_two_foci_locus",
                    "config": {
                        "F1": [-2, 0],
                        "F2": [2, 0],
                        "sum_dist": 6,
                        "tolerance": 0.15,
                    },
                },
                expect_event="trail_completed",
            )
        # 没命中关键词 → LLM 根据知识图谱 + 当前阶段上下文引导
        reply = self._llm_respond(text, fallback=HINT_CIRCLE_MSG)
        return LessonStep(stage=self.stage.value, message=reply)

    def _handle_await_name(self, text: str) -> LessonStep:
        if _looks_like_ellipse_name(text):
            self.stage = LessonStage.EXPLORE_C
            # 进入「2a 定，2c 动」比较阶段：先清掉发现阶段的探索轨迹，
            # 让学生在干净的画布上对比不同 2c 对应的椭圆。
            # 附加教材节点引用（GraphRAG 检索增强）：
            #   - 椭圆定义：人教版 A 版选修 2-1 第二章 §1
            #   - 轨迹概念（前置）
            message = DEFINE_ELLIPSE_MSG + self._kg_footer([
                "ellipse_definition",
                "foundation_locus",
            ])
            return LessonStep(
                stage=self.stage.value,
                message=message,
                canvas_action=[
                    {"action": "clear_all_trails"},
                    {
                        "action": "add_focus_slider",
                        "config": {"range": [0.3, 2.8], "initial": 2.0},
                    },
                ],
                expect_event="focus_slider_changed",
            )
        reply = self._llm_respond(text, fallback=HINT_NAME_MSG)
        return LessonStep(stage=self.stage.value, message=reply)

    def _handle_explore_c(self, text: str) -> LessonStep:
        """2a 定 2c 动阶段 —— LLM 回应 + 关键词推进判定"""
        has_insight = any(
            kw in text for kw in ["扁", "圆", "近", "远", "大", "小", "长", "细", "变化"]
        )
        if has_insight and self.c_slider_changes >= 2:
            # 学生有了观察 → 推进到 TRANSITION_TO_A
            self.stage = LessonStage.TRANSITION_TO_A
            reply = self._llm_respond(text, fallback=TRANSITION_TO_A_MSG)
            return LessonStep(stage=self.stage.value, message=reply)

        # 还没有关键观察 → LLM 引导（如果学生问别的问题，LLM 也能回答）
        reply = self._llm_respond(text, fallback=NUDGE_SLIDER_MSG)
        return LessonStep(stage=self.stage.value, message=reply)

    def _handle_transition_to_a(self, text: str) -> LessonStep:
        """过渡：学生给出猜想后，LLM 肯定并打开 2a 滑轨验证。"""
        fallback = (
            "好的猜想！让我们来验证一下 👇\n\n"
            "画布上的**焦距 2c 已锁定**，下方新增了 **2a 滑轨**。\n"
            "拖动它，观察椭圆怎么变化，看看和你的猜想是否一致。"
        )
        self.stage = LessonStage.EXPLORE_A
        reply = self._llm_respond(text, fallback=fallback)
        return LessonStep(
            stage=self.stage.value,
            message=reply,
            canvas_action=[
                {"action": "clear_all_trails"},
                {
                    "action": "add_sum_slider",
                    "config": {
                        "range": [2.5, 5.0],
                        "initial": 3.5,
                        "fixed_c": 2.0,
                    },
                },
            ],
            expect_event="sum_slider_changed",
        )

    def _handle_explore_a(self, text: str) -> LessonStep:
        """2c 定 2a 动阶段 —— LLM 回应 + 关键词推进到 DISCOVER_E

        推进到 DISCOVER_E 时，**确定性**展示 e-slider 交互工具（mandatory VIZ）。

        推进条件（满足任一即推进）：
        1. 形状观察 + 滑轨操作：学生描述了 2a 对形状的影响 且 操作过滑轨
        2. 超前发现：学生主动提到了「比值」「c/a」等 DISCOVER_E 概念
           （说明学生已经超前理解，不必强制在 EXPLORE_A 停留）
        """
        # 条件 1：形状观察
        has_shape_insight = any(
            kw in text for kw in ["扁", "圆", "大", "小", "长", "短", "接近"]
        )
        # 条件 2：超前发现（学生主动提到比值/c与a的关系）
        has_ratio_insight = any(
            kw in text for kw in ["比值", "比", "c/a", "a/c", "c÷a", "除"]
        )

        should_advance = (
            (has_shape_insight and self.a_slider_changes >= 2)
            or has_ratio_insight  # 学生超前 → 直接推进，不需要滑轨操作
        )

        if should_advance:
            self.stage = LessonStage.DISCOVER_E
            if has_ratio_insight:
                # 学生已经想到了比值 → 肯定并直接展示 e-slider
                fallback = (
                    "非常好！你已经想到了用比值来描述！👏\n\n"
                    "右边画布上有一个交互工具 👉 滑轨控制的就是 c/a 这个比值。\n"
                    "请拖动滑轨，观察不同比值对应的椭圆形状，\n"
                    "你能描述一下比值从小到大变化时，椭圆发生了什么吗？"
                )
            else:
                fallback = (
                    "观察得很仔细！你发现了 2a 也会影响椭圆的形状。\n\n"
                    "现在我们已经知道 2c 和 2a 都会影响椭圆的扁平程度。\n"
                    "那我问你：**到底是什么决定了椭圆有多扁？**\n\n"
                    "右边画布上有一个新的交互工具 👉 拖动滑轨，仔细观察椭圆形状的变化，"
                    "看看你能不能发现规律。"
                )
            reply = self._llm_respond(text, fallback=fallback)
            # ★ 确定性 VIZ：进入 DISCOVER_E 时一定展示 e-slider
            mandatory_viz = _STAGE_MANDATORY_VIZ.get(LessonStage.DISCOVER_E)
            return LessonStep(
                stage=self.stage.value,
                message=reply,
                canvas_action=mandatory_viz,
            )

        # 还没有关键观察 → LLM 引导
        reply = self._llm_respond(text, fallback=NUDGE_A_MSG)
        return LessonStep(stage=self.stage.value, message=reply)

    def _handle_discover_e(self, text: str) -> LessonStep:
        """发现离心率阶段 —— e-slider 已在入口确定性展示。

        前提：进入此阶段时，_handle_explore_a 已通过 _STAGE_MANDATORY_VIZ
        确定性展示了 e-slider（show_summary_viz），学生可以拖动滑轨观察
        不同 e = c/a 值对应的椭圆形状。

        本 handler 的任务：
        1. 引导学生拖动 e-slider 并描述观察到的规律
        2. 学生描述出 e 与形状的关系 → 正式告知「离心率」名称，推进到 SUMMARY
        3. 超过 5 轮仍无有效观察 → 给提示后推进
        """
        if not hasattr(self, '_discover_e_turns'):
            self._discover_e_turns = 0
        self._discover_e_turns += 1

        # 检测学生的观察质量
        has_ratio_insight = any(
            kw in text for kw in ["比值", "比", "除", "c/a", "c÷a", "商"]
        )
        has_eccentricity = any(
            kw in text.lower() for kw in ["离心率", "eccentricity", "e="]
        )
        has_e_shape_observation = any(
            kw in text for kw in ["接近0", "接近1", "越大越", "越小越",
                                   "扁", "圆", "0的时候", "1的时候"]
        )

        if has_eccentricity or has_e_shape_observation or has_ratio_insight:
            # 学生给出了有效观察 → 正式定义离心率并推进到 SUMMARY
            self.stage = LessonStage.SUMMARY
            fallback = (
                "太棒了！🎉 你通过自己的探索发现了规律！\n\n"
                "这个比值 **e = c/a** 在数学上叫做**离心率**（eccentricity）。\n"
                "正如你刚才观察到的：\n"
                "- 当 e 接近 0 时，c 远小于 a，椭圆接近圆形 ⭕\n"
                "- 当 e 接近 1 时，c 接近 a，椭圆非常扁 ⬭\n"
                "- 椭圆的离心率范围：**0 < e < 1**\n\n"
                "现在我们知道了 a、c 和 e 的关系。"
                "那如果把椭圆放在坐标系里，你觉得能不能写出它的方程呢？"
            )
            reply = self._llm_respond(text, fallback=fallback)
            reply += self._kg_footer(
                ["ellipse_definition", "ellipse_parameter_triangle", "ellipse_eccentricity"],
                heading="\n📚 本节对应教材知识点",
            )
            return LessonStep(stage=self.stage.value, message=reply)

        if self._discover_e_turns >= 5:
            # 引导了 5 轮仍无观察 → 给提示并推进
            self.stage = LessonStage.SUMMARY
            fallback = (
                "让我来帮你总结一下 😊\n\n"
                "右边画布上的滑轨控制的就是 **e = c/a** 这个比值。\n"
                "当 e 接近 0 时椭圆接近圆形，e 接近 1 时椭圆非常扁。\n\n"
                "这个比值在数学上叫做**离心率**（eccentricity），"
                "它决定了椭圆的扁平程度：**0 < e < 1**。"
            )
            reply = self._llm_respond(text, fallback=fallback)
            reply += self._kg_footer(
                ["ellipse_definition", "ellipse_parameter_triangle", "ellipse_eccentricity"],
                heading="\n📚 本节对应教材知识点",
            )
            return LessonStep(stage=self.stage.value, message=reply)

        # 正常引导 —— 引导学生观察 e-slider
        fallback = (
            "右边画布上有一个滑轨，拖动它观察椭圆的形状变化。\n\n"
            "试试看：把滑轨拖到最左边和最右边，椭圆分别像什么形状？"
        )
        reply = self._llm_respond(text, fallback=fallback)
        return LessonStep(stage=self.stage.value, message=reply)

    # SUMMARY 阶段已探讨话题的关键词集合（用于重复检测）
    _SUMMARY_TOPIC_KEYWORDS = {
        "定义": "ellipse_definition",
        "离心率": "ellipse_eccentricity",
        "焦点": "ellipse_definition",
        "长轴": "ellipse_parameter_triangle",
        "短轴": "ellipse_parameter_triangle",
        "半长轴": "ellipse_parameter_triangle",
        "半短轴": "ellipse_parameter_triangle",
        "焦距": "ellipse_definition",
        "方程": "ellipse_standard_equation_x",
        "标准方程": "ellipse_standard_equation_x",
        "扁": "ellipse_eccentricity",
        "圆": "ellipse_eccentricity",
        "比值": "ellipse_eccentricity",
        "e": "ellipse_eccentricity",
    }

    def _detect_summary_topics(self, text: str) -> List[str]:
        """检测学生提问中涉及的知识点 ID（去重）。"""
        topics = []
        for kw, topic_id in self._SUMMARY_TOPIC_KEYWORDS.items():
            if kw in text and topic_id not in topics:
                topics.append(topic_id)
        return topics

    def _is_repeating(self, text: str) -> bool:
        """判断学生是否在重复之前已探讨的话题。"""
        current_topics = self._detect_summary_topics(text)
        if not current_topics:
            return False
        # 如果当前提问的所有话题都已在之前的 summary_topics 中出现过
        return all(t in self.summary_topics for t in current_topics)

    def _handle_summary(self, text: str) -> LessonStep:
        """总结阶段 —— 学生继续提问 + 重复检测 + 自动结课。

        结课触发条件（满足任一即可）：
        1. 学生明确表示没问题了（如"没了"、"好的"、"谢谢"、"结束"）
        2. 学生连续提问已探讨过的话题（重复 ≥ 2 次）
        3. SUMMARY 阶段对话超过 8 轮且有重复迹象
        """
        self.summary_turns += 1

        # 检测本次涉及的话题
        current_topics = self._detect_summary_topics(text)
        is_repeating = self._is_repeating(text)
        # 更新已探讨话题
        for t in current_topics:
            if t not in self.summary_topics:
                self.summary_topics.append(t)

        # 检测学生是否主动结束
        end_signals = ["没了", "没有了", "没问题", "好的", "谢谢", "结束", "再见", "拜拜", "OK", "ok"]
        student_wants_end = any(sig in text for sig in end_signals) and len(text) < 20

        # 判断是否触发结课
        should_end = False
        if self.lesson_ended:
            # 已经结课了，继续用 LLM 简短回应
            reply = self._llm_respond(text, fallback="谢谢你的参与！下节课我们继续探索双曲线～")
            return LessonStep(stage=self.stage.value, message=reply)

        if student_wants_end:
            should_end = True
        elif is_repeating and self.summary_turns >= 3:
            should_end = True
        elif self.summary_turns >= 8 and is_repeating:
            should_end = True

        if should_end:
            return self._generate_lesson_ending(text)

        # 正常 LLM 回答
        fallback = (
            "这节课你通过自己的操作和观察，从圆出发一步步发现了椭圆的奥秘，非常棒！\n\n"
            "右边的可视化工具展示了离心率 e 对椭圆形状的影响，可以拖动滑块体验一下。\n"
            "有任何问题都可以继续问我～"
        )
        reply = self._llm_respond(text, fallback=fallback)

        # 解析 LLM 是否自己决定结课（[LESSON_END] 标记）
        if "[LESSON_END]" in reply:
            reply = reply.replace("[LESSON_END]", "").strip()
            self.lesson_ended = True
            # 附加结课知识点引用
            reply += self._kg_footer(
                self.course_config["summary_kg_nodes"],
                heading="\n📚 本节核心知识点",
            )
            return LessonStep(
                stage=self.stage.value,
                message=reply,
                canvas_action={"action": "show_lesson_end"},
            )

        return LessonStep(stage=self.stage.value, message=reply)

    def _generate_lesson_ending(self, text: str) -> LessonStep:
        """生成结课总结。"""
        self.lesson_ended = True
        fallback = (
            "🎉 恭喜你完成了本节探究课！\n\n"
            "让我们回顾一下你的探索路径：\n"
            "1️⃣ 从**圆的定义**（到定点距离等于定长）出发\n"
            "2️⃣ 把一个焦点变成两个焦点，发现了**椭圆**\n"
            "3️⃣ 探究了焦距 2c 和长轴 2a 对椭圆形状的影响\n"
            "4️⃣ 发现决定椭圆「扁平程度」的是**离心率 e = c/a**\n\n"
            "📐 **椭圆定义**：平面上到两个定点 F₁、F₂ 的距离之和等于常数 2a（2a > |F₁F₂|）的点的轨迹\n"
            "📏 **离心率**：e = c/a，0 < e < 1，e 越大椭圆越扁\n\n"
            "下节课我们将探索**双曲线** —— 如果把「距离之和」改成「距离之差」，会怎么样呢？🤔"
        )
        reply = self._llm_respond(text, fallback=fallback)
        # 清除可能的 [LESSON_END] 标记
        reply = reply.replace("[LESSON_END]", "").strip()
        reply += self._kg_footer(
            self.course_config["summary_kg_nodes"],
            heading="\n📚 本节核心知识点",
        )
        return LessonStep(
            stage=self.stage.value,
            message=reply,
            canvas_action={"action": "show_lesson_end"},
        )

