    def _handle_hyp_recall_ellipse(self, text: str) -> LessonStep:
        """双曲线课：回忆椭圆定义 → 提出"距离之差"转折"""
        if _looks_like_ellipse_def_recall(text):
            self.stage = LessonStage.HYP_EXPLORE_TWO_FOCI
            fallback = (
                "很好！椭圆是到两个焦点的距离之**和**等于常数。\n\n"
                "那如果我们换一下条件：到两焦点的**距离之差的绝对值**等于常数，"
                "轨迹会是什么样呢？🤔\n\n"
                "右边画布上有两个焦点 F₁ 和 F₂，请拖动点 P 画出轨迹！\n"
                "注意：这次可能需要在**两侧**都画出来哦～"
            )
            reply = self._llm_respond(text, fallback=fallback)
            return LessonStep(
                stage=self.stage.value,
                message=reply,
                canvas_action={
                    "action": "init_hyperbola_locus",
                    "config": {
                        "F1": [-2, 0], "F2": [2, 0],
                        "diff_dist": 2,  # ||PF1|-|PF2|| = 2a = 2
                    },
                },
                expect_event="trail_completed",
            )
        reply = self._llm_respond(text, fallback="再想想，椭圆上任意一点到两个焦点的距离有什么特点？关键词：「距离之和」。")
        return LessonStep(stage=self.stage.value, message=reply)

    def _handle_hyp_await_name(self, text: str) -> LessonStep:
        """双曲线课：等学生说出"双曲线" """
        if _looks_like_hyperbola_name(text):
            self.stage = LessonStage.HYP_EXPLORE_C_AND_A
            fallback = (
                "没错，这就是**双曲线**！🎉\n\n"
                "📐 **双曲线的定义**：平面内到两个定点 F₁、F₂ 的距离之差的绝对值"
                "等于常数（小于 |F₁F₂|）的动点轨迹。\n"
                "- 注意：这里「常数 2a」必须**小于**焦距 2c，否则不存在这样的点\n"
                "- 参数关系：c² = a² + b²（和椭圆的 a² = b² + c² 正好反过来！）\n\n"
                "画布下方有 2a 和 2c 的滑轨，请拖动它们观察双曲线的形状变化。"
            )
            reply = self._llm_respond(text, fallback=fallback)
            return LessonStep(
                stage=self.stage.value,
                message=reply + self._kg_footer(["hyperbola_definition", "foundation_locus"]),
                canvas_action=[
                    {"action": "clear_all_trails"},
                    {
                        "action": "add_hyperbola_sliders",
                        "config": {"a_range": [0.5, 3.0], "c_range": [1.0, 4.0],
                                   "initial_a": 1.0, "initial_c": 2.0},
                    },
                ],
                expect_event="hyp_slider_changed",
            )
        reply = self._llm_respond(text, fallback="这两条对称的开放曲线，在数学里叫做「双」字开头的名字，你再想想？")
        return LessonStep(stage=self.stage.value, message=reply)

    def _handle_hyp_explore_c_and_a(self, text: str) -> LessonStep:
        """双曲线课：2a/2c 滑轨探究 → 推进到 DISCOVER_E + 确定性展示 e-slider"""
        has_insight = any(kw in text for kw in ["宽", "窄", "大", "小", "开口", "渐近", "变化", "远", "近"])
        slider_count = self.slider_changes.get("hyp", 0)
        if has_insight and slider_count >= 2:
            self.stage = LessonStage.HYP_DISCOVER_E
            fallback = (
                "观察得很仔细！你发现双曲线的形状和 a、c 的关系了。\n\n"
                "还记得椭圆的离心率 e = c/a 吗？双曲线中 c > a，那 e 会是多少？\n\n"
                "右边画布上有一个新的交互工具 👉 拖动 e 值滑轨，"
                "观察不同 e 值对应的双曲线形状。"
            )
            reply = self._llm_respond(text, fallback=fallback)
            # ★ 确定性 VIZ：进入 HYP_DISCOVER_E 时一定展示 e-slider
            mandatory_viz = _STAGE_MANDATORY_VIZ.get(LessonStage.HYP_DISCOVER_E)
            return LessonStep(
                stage=self.stage.value,
                message=reply,
                canvas_action=mandatory_viz,
            )
        reply = self._llm_respond(text, fallback="试着多拖几次滑轨，观察双曲线的两支是怎么变化的？渐近线（虚线）有什么变化？")
        return LessonStep(stage=self.stage.value, message=reply)

    def _handle_hyp_discover_e(self, text: str) -> LessonStep:
        """双曲线课：发现 e = c/a > 1。e-slider 已在入口确定性展示。"""
        if not hasattr(self, '_hyp_discover_e_turns'):
            self._hyp_discover_e_turns = 0
        self._hyp_discover_e_turns += 1

        has_insight = any(kw in text for kw in ["大于1", ">1", "比值", "离心率", "e=", "c/a"])
        has_shape_obs = any(kw in text for kw in ["窄", "宽", "渐近线", "夹角", "开口", "扁"])

        if has_shape_obs or has_insight:
            self.stage = LessonStage.HYP_SUMMARY
            fallback = (
                "太棒了！🎉 你观察得很准确！\n\n"
                "双曲线的离心率 **e = c/a > 1**（因为 c > a）。\n"
                "正如你刚才看到的：\n"
                "- e 越接近 1 → 两支越窄（渐近线夹角越小）\n"
                "- e 越大 → 两支越宽（渐近线夹角越大）\n\n"
                "对比一下：\n"
                "| | 椭圆 | 双曲线 |\n"
                "|---|---|---|\n"
                "| 定义 | 距离之和 = 2a | 距离之差 = 2a |\n"
                "| 参数 | a > c | c > a |\n"
                "| 离心率 | 0 < e < 1 | e > 1 |\n\n"
                "对比一下：\n"
                "| | 椭圆 | 双曲线 |\n"
                "|---|---|---|\n"
                "| 定义 | 距离之和 = 2a | 距离之差 = 2a |\n"
                "| 参数 | a > c | c > a |\n"
                "| 离心率 | 0 < e < 1 | e > 1 |\n\n"
                "现在我们知道了双曲线的定义和离心率。"
                "那如果把双曲线放在坐标系里，你觉得能不能写出它的方程呢？"
            )
            reply = self._llm_respond(text, fallback=fallback)
            reply += self._kg_footer(
                self.course_config["summary_kg_nodes"],
                heading="\n📚 本节对应教材知识点",
            )
            return LessonStep(stage=self.stage.value, message=reply)

        if self._hyp_discover_e_turns >= 5:
            self.stage = LessonStage.HYP_SUMMARY
            fallback = (
                "提示一下：双曲线中 c > a，所以 e = c/a 一定**大于 1**！\n\n"
                "你刚才在画布上也能看到：e 越接近 1 两支越窄，e 越大两支越宽。\n"
                "这就是双曲线的**离心率**——始终 e > 1。\n\n"
                "那如果把双曲线放在坐标系里，你觉得能写出它的方程吗？"
            )
            reply = self._llm_respond(text, fallback=fallback)
            reply += self._kg_footer(
                self.course_config["summary_kg_nodes"],
                heading="\n📚 本节对应教材知识点",
            )
            return LessonStep(stage=self.stage.value, message=reply)

        fallback = (
            "右边画布上有 e 值滑轨，拖动看看：\n"
            "e 接近 1 和 e 很大时，双曲线的两支形状有什么不同？"
        )
        reply = self._llm_respond(text, fallback=fallback)
        return LessonStep(stage=self.stage.value, message=reply)

