    def _llm_h322_example_protocol(self, student_text: str, example_key, current_phase: str) -> Optional[dict]:
        """H322 例题路径 2 协议（角色 2）。"""
        llm = self._get_llm()
        if llm is None:
            return None
        ex_ctx = _EXAMPLE_CONTEXT_MAP_H322.get(example_key, "（无上下文）")
        ph_ctx = _EXAMPLE_PHASE_QUESTION_MAP_H322.get((example_key, current_phase), f"phase={current_phase}")
        system_prompt = (_H322_EXAMPLE_PROTOCOL_SYSTEM_PROMPT
                        .replace("{example_context}", ex_ctx)
                        .replace("{phase_context}", ph_ctx))
        try:
            raw = llm.complete(system_prompt, student_text, max_tokens=800, temperature=0.0)
        except Exception as e:
            print(f"[H322Protocol] ❌ ex{example_key}/{current_phase}: provider 全挂 ({type(e).__name__})")
            return None
        parsed = self._parse_protocol_json(raw)
        if parsed is None:
            print(f"[H322Protocol] ⚠️ ex{example_key}/{current_phase}: JSON parse 失败 raw={raw[:120]!r}")
            return None
        if "diagnosis" not in parsed or "advance" not in parsed:
            return None
        print(f"[H322Protocol] ✅ ex{example_key}/{current_phase}: diagnosis={parsed.get('diagnosis')}, advance={parsed.get('advance')}, hit_goal={parsed.get('hit_goal')}")
        return parsed

    # ---- H322 例题 311-style generic handler（v3.46 新增）----
    def _h322_find_next_unanswered_phase(self, example_key, subflags: set) -> Optional[str]:
        """按 phase 顺序找第一个未答完的 phase。返回 phase 名或 None（全答完）。"""
        from .example_canonicals_322 import EXAMPLE_CONFIGS_322
        if example_key not in EXAMPLE_CONFIGS_322:
            return None
        phases = EXAMPLE_CONFIGS_322[example_key]["phases"]
        for phase in phases:
            required = _H322_PHASE_REQUIRED_FLAGS.get((example_key, phase), set())
            if not required.issubset(subflags):
                return phase
        return None

    def _h322_advance_example(self, example_key) -> LessonStep:
        """例题完整通关，切下一题或 SUMMARY；写 awaiting_next 标志位等学生确认。

        v3.48：仿 _advance_e312_example / _advance_h321_example，例 2 / 例 3 完成后
        追加 explore viz（拖 M 看比值 / 拖倾斜角看 |AB|）。前端 applyCanvasAction 已支持 list 链式。
        """
        # 标 awaiting_next，等学生确认后再切
        self._h322_example_done_awaiting_next = example_key
        next_label = {1: "例 2", 2: "例 3", 3: "总结"}.get(example_key, "下一节")
        # 起手 solved
        actions = [{"action": f"show_h322_example_{example_key}_solved"}]
        # 例 2 |MF|/d 拖 M 互动；例 3 倾斜角滑块互动（例 1 没有 explore viz）
        explore_hint = ""
        if example_key in (2, 3):
            actions.append({"action": f"show_h322_example_{example_key}_explore"})
            if example_key == 2:
                explore_hint = "右图切到了**拖 $M$ 感受 $|MF|/d=4/3$** 互动 —— 拖动看看比值是不是恒等于 $4/3$。\n\n"
            elif example_key == 3:
                explore_hint = "右图切到了**拖倾斜角滑块**互动 —— 看不同角度下 $|AB|$ 怎么变。\n\n"
        return LessonStep(
            stage=self.stage.value,
            message=(
                f"🎉 例 {example_key} 完成！整道题已通关。\n\n"
                + explore_hint
                + f"如果都明白了，回复「**继续**」/「**没问题**」进入 **{next_label}**；"
                f"如果还想看下哪一步的解析，可以再问我。"
            ),
            canvas_action=actions if len(actions) > 1 else actions[0],
        )

    def _continue_to_next_h322_example(self) -> LessonStep:
        """学生确认 awaiting_next 后，切到下一例题或 SUMMARY。"""
        prev = getattr(self, "_h322_example_done_awaiting_next", None)
        self._h322_example_done_awaiting_next = None
        # 重置 subflags（下一题独立）
        if hasattr(self, "_h322_example_subflags"):
            self._h322_example_subflags = set()
        # v3.50.2：跨例切换时清理累积字典
        self._h322_example_conclude_hits = {}
        self._h322_example_partial_pts = {}
        if prev == 1:
            self.stage = LessonStage.H322_EXAMPLE_2
            viz = _STAGE_MANDATORY_VIZ.get(LessonStage.H322_EXAMPLE_2)
            return LessonStep(stage=self.stage.value, message=H322_EXAMPLE_2_INTRO, canvas_action=viz)
        if prev == 2:
            self.stage = LessonStage.H322_EXAMPLE_3
            viz = _STAGE_MANDATORY_VIZ.get(LessonStage.H322_EXAMPLE_3)
            return LessonStep(stage=self.stage.value, message=H322_EXAMPLE_3_INTRO, canvas_action=viz)
        if prev == 3:
            self.stage = LessonStage.H322_SUMMARY
            return LessonStep(stage=self.stage.value, message=H322_SUMMARY_MSG)
        # fallback
        return LessonStep(stage=self.stage.value, message="（系统提示）已是最后一题，输入「结束」结课。")

    def _handle_h322_example_generic(self, text: str, example_key) -> LessonStep:
        """v3.46 311-style 例题 generic handler（仿 _handle_h321_example_generic）。

        三层防御：
          Layer 1: example_diagnostician_322（全 goal 扫描，无 phase 参数）
          Layer 2: 路径 2 协议 LLM 兜底（角色 2）
          Layer 3: deterministic phase prompt

        架构：
          · 诊断器命中 → 累积 implied_flags 到 subflags
          · done_fn(subflags) 满足 → _h322_advance_example 收尾（awaiting_next）
          · 部分命中 → 按 _H322_PHASE_REQUIRED_FLAGS 找下一未完成 phase + 精准追问
        """
        from .example_canonicals_322 import EXAMPLE_CONFIGS_322
        from .example_diagnostician_322 import diagnose_example_322

        # 0. awaiting_next 状态检查（前次例题完成等学生确认）
        if getattr(self, "_h322_example_done_awaiting_next", None) is not None:
            t = text.replace(" ", "")
            if any(kw in t for kw in ["继续", "没问题", "好的", "好", "可以", "下一题", "下一", "ok", "OK"]):
                return self._continue_to_next_h322_example()
            # 学生没确认 → 提示
            return LessonStep(
                stage=self.stage.value,
                message="如果都明白了，回复「**继续**」进入下一题；或者你可以问我刚才哪一步还想再讲。",
            )

        # 1. 跨例跳级（学生说"看例 N"）
        skip_n = _looks_like_skip_to_example_322(text)
        if skip_n is not None and skip_n != example_key:
            target_stage, target_intro = {
                1: (LessonStage.H322_EXAMPLE_1, H322_EXAMPLE_1_INTRO),
                2: (LessonStage.H322_EXAMPLE_2, H322_EXAMPLE_2_INTRO),
                3: (LessonStage.H322_EXAMPLE_3, H322_EXAMPLE_3_INTRO),
            }[skip_n]
            self.stage = target_stage
            self._h322_example_subflags = set()  # 新题独立 subflags
            # v3.50.2：跨例跳级时清理跨轮累积字典（防止上一题状态污染）
            self._h322_example_conclude_hits = {}
            self._h322_example_partial_pts = {}
            viz = _STAGE_MANDATORY_VIZ.get(target_stage)
            return LessonStep(
                stage=self.stage.value,
                message=f"好的，跳到例 {skip_n}：\n\n" + target_intro,
                canvas_action=viz,
            )

        # 2. 初始化 subflags（每题独立）
        if not hasattr(self, "_h322_example_subflags") or getattr(self, "_h322_example_active", None) != example_key:
            self._h322_example_subflags = set()
            self._h322_example_active = example_key
        subflags: set = self._h322_example_subflags

        config = EXAMPLE_CONFIGS_322[example_key]
        done_fn = config["done_fn"]

        # v3.52 调试日志：每条输入打印 raw + 归一后 + 当前 subflags，便于用户截图排错
        try:
            _normed_dbg = self._h322_normalize_text(text)
        except Exception:
            _normed_dbg = "<norm-fail>"
        print(f"[H322 EX{example_key}] raw={text!r} normed={_normed_dbg!r} "
              f"subflags={sorted(subflags)}")

        # 3. Layer 1: 诊断器全 goal 扫描
        dx = diagnose_example_322(text, example_key)

        # v3.50.2 例 1 ask_focus 焦点点跨轮累积（仿 312 例 4 partial_hit_point_set）
        # 学生分两次答 (0, 5) → (0, -5) 时也要累积，不能只接受一次性答全
        if example_key == 1 and "focus_done" not in subflags:
            from .example_diagnostician_322 import _extract_point_tuples
            canonical_pts = set(config["canonical"]["focus_set"])
            student_pts = _extract_point_tuples(text)
            if not hasattr(self, "_h322_example_partial_pts"):
                self._h322_example_partial_pts = {}
            cache_key = (1, "ask_focus")
            accumulated = self._h322_example_partial_pts.get(cache_key, set())
            new_hits = student_pts & canonical_pts
            if new_hits:
                accumulated |= new_hits
                self._h322_example_partial_pts[cache_key] = accumulated
                if accumulated == canonical_pts:
                    # 累积满 → 命中 focus_set
                    implies = config["implies"].get("focus_set", set())
                    subflags |= implies
                    self._h322_example_subflags = subflags
                    if done_fn(subflags):
                        return self._h322_advance_example(example_key)
                    # 推进到下一 phase 由后续流程处理
                else:
                    # 苏格拉底引导：不直接给坐标，提示"对称性"——双曲线焦点关于原点对称
                    got_str = "、".join(f"$({p[0]}, {p[1]})$" for p in sorted(new_hits))
                    return LessonStep(
                        stage=self.stage.value,
                        message=(
                            f"✅ 答出 {got_str}。\n\n"
                            "**双曲线焦点关于原点对称**——已经答出一个，**对称那个**是？"
                        ),
                    )

        # v3.50.2 例 3 ask_intersect x_set 跨轮累积（同模式）
        # 学生分两次答 x₁=-3 → x₂=9/5 时也要累积
        if example_key == 3 and "intersect_done" not in subflags:
            from .example_diagnostician_322 import _extract_x_values
            canonical_x = set(config["canonical"]["x_set"])
            student_x = _extract_x_values(text)
            if not hasattr(self, "_h322_example_partial_pts"):
                self._h322_example_partial_pts = {}
            cache_key = (3, "ask_intersect")
            accumulated = self._h322_example_partial_pts.get(cache_key, set())
            new_hits = student_x & canonical_x
            if new_hits:
                accumulated |= new_hits
                self._h322_example_partial_pts[cache_key] = accumulated
                if accumulated == canonical_x:
                    implies = config["implies"].get("x_set", set())
                    subflags |= implies
                    self._h322_example_subflags = subflags
                    if done_fn(subflags):
                        return self._h322_advance_example(example_key)
                else:
                    # 苏格拉底引导：不直接给另一个根，提示"二次方程两根"
                    got_str = "、".join(f"$x={v}$" for v in sorted(new_hits, key=lambda r: float(r)))
                    return LessonStep(
                        stage=self.stage.value,
                        message=(
                            f"✅ 答出 {got_str}。\n\n"
                            "**二次方程 $5x^2+6x-27=0$ 有两个根** —— 用求根公式 / 因式分解再求一个？"
                        ),
                    )

        # v3.50 例 2 ask_conclude 跨轮关键词维度累积（仿 312 例 5 _e312_example_conclude_hits）
        # 学生可能分多轮答："焦点在 x 轴" + "2a=6, 2b=2√7" + "实轴长 6, 虚轴长 2√7"
        # 三维度（x_axis / real_axis_6 / imag_axis_2sqrt7）各自累积，齐了才标 conclude_done
        if example_key == 2 and "conclude_done" not in subflags:
            if not hasattr(self, "_h322_example_conclude_hits"):
                self._h322_example_conclude_hits = {}
            raw = text
            t_norm = self._h322_normalize_text(text)  # 已去空格 + × → * + ÷ → / 等
            t_lower = t_norm.lower()
            hits = self._h322_example_conclude_hits.get(2,
                       {"x_axis": False, "real_6": False, "imag_2sqrt7": False})
            # 维度 1：焦点在 x 轴
            if any(kw in t_norm for kw in ["焦点在x轴", "焦点在x", "x轴上", "焦点x轴"]) \
               or ("x轴" in t_norm and "焦点" in t_norm) \
               or ("轨迹是双曲线" in t_norm and "x" in t_norm and "轴" in t_norm):
                hits["x_axis"] = True
            # 维度 2：实轴长 6 / 2a=6
            if "2a=6" in t_norm or ("实轴" in t_norm and "6" in t_norm) \
               or "实轴长6" in t_norm or "实轴长为6" in t_norm:
                hits["real_6"] = True
            # 维度 3：虚轴长 2√7 / 2b=2√7（v3.51 修：用 t_norm 兜空格，加 × → * 变体）
            #   t_norm 已经把 × 归一为 *，所以 "2 × √7" → "2*√7"
            has_imag = (
                "2√7" in t_norm                       # 2√7（学生紧凑写）
                or "2*√7" in t_norm                  # 2 × √7（× 已归一 *）
                or "2sqrt(7)" in t_lower             # 2sqrt(7)
                or "2sqrt7" in t_lower               # 2sqrt7
                or "2*sqrt(7)" in t_lower            # 2 × sqrt(7)
                or "2*sqrt7" in t_lower              # 2 × sqrt7
                # v3.51 同源修复：中文写法也用 t_norm 兜空格
                or "2根号7" in t_norm or "二根号7" in t_norm or "2倍根号7" in t_norm
                or "2b=2√7" in t_norm or "2b=2*√7" in t_norm
                or "2b=2sqrt(7)" in t_lower or "2b=2*sqrt(7)" in t_lower
            )
            if has_imag:
                hits["imag_2sqrt7"] = True
            self._h322_example_conclude_hits[2] = hits

            if all(hits.values()):
                # 三维度齐 → 标 conclude_done（即使 LLM/诊断器都没命中）
                subflags |= {"conclude_done"}
                self._h322_example_subflags = subflags
                # 整道题完成 → advance
                if done_fn(subflags):
                    return self._h322_advance_example(example_key)

        if dx is not None:
            subflags |= dx.implied_flags
            self._h322_example_subflags = subflags
            # 整道题完成 → advance
            if done_fn(subflags):
                return self._h322_advance_example(example_key)
            # 部分命中 → 找下一未答完 phase
            next_phase = self._h322_find_next_unanswered_phase(example_key, subflags)
            if next_phase is None:
                # 边界：所有 phase required 都满足但 done_fn 还未触发（不太可能，但保险）
                return self._h322_advance_example(example_key)
            ack = "✅ " + "、".join(dx.hit_goals) + " 收到。"
            # 精准追问（missing-aware）
            required = _H322_PHASE_REQUIRED_FLAGS.get((example_key, next_phase), set())
            missing = required - subflags
            specific_prompt = None
            if len(missing) == 1:
                missing_flag = next(iter(missing))
                specific_prompt = _H322_PHASE_PROMPT_BY_MISSING.get((example_key, next_phase, missing_flag))
            phase_prompt = specific_prompt or self._h322_example_phase_prompt(example_key, next_phase)
            return LessonStep(
                stage=self.stage.value,
                message=ack + "\n\n" + phase_prompt,
            )

        # v3.50：例 2 ask_conclude 跨轮累积部分命中 → 苏格拉底式追问（不剧透数值）
        if example_key == 2 and "conclude_done" not in subflags:
            hits = getattr(self, "_h322_example_conclude_hits", {}).get(2, {})
            if any(hits.values()) and not all(hits.values()):
                # 已答的维度（不剧透答案，只点名）
                got_label = {"x_axis": "焦点在 x 轴", "real_6": "实轴长", "imag_2sqrt7": "虚轴长"}
                # 还差维度的"苏格拉底提示"（**不给数值**，只引导从方程读出）
                hint_label = {
                    "x_axis":      "**焦点在哪个轴**？（看你刚化简的方程 $\\dfrac{x^2}{?}-\\dfrac{y^2}{?}=1$ 哪一项符号是正的，焦点就在那个轴上）",
                    "real_6":      "**实轴长 $2a$**？（从方程读出 $a^2$ 再开方，乘 2）",
                    "imag_2sqrt7": "**虚轴长 $2b$**？（从方程读出 $b^2$ 再开方，乘 2）",
                }
                got_parts = [got_label[k] for k, v in hits.items() if v]
                miss_hints = [hint_label[k] for k, v in hits.items() if not v]
                got_txt = "、".join(got_parts) if got_parts else ""
                return LessonStep(
                    stage=self.stage.value,
                    message=(
                        (f"✅ 已答出：**{got_txt}**。\n\n" if got_txt else "")
                        + "还差：\n" + "\n".join(f"  · {h}" for h in miss_hints)
                    ),
                )

        # 4. Layer 2: 路径 2 协议（LLM 兜底）
        next_phase = self._h322_find_next_unanswered_phase(example_key, subflags) or config["phases"][0]
        protocol = self._llm_h322_example_protocol(text, example_key, next_phase)
        if protocol is not None:
            # skip_request 处理
            skip_to = protocol.get("skip_to_example")
            if skip_to in (1, 2, 3) and skip_to != example_key:
                target_stage = {1: LessonStage.H322_EXAMPLE_1, 2: LessonStage.H322_EXAMPLE_2, 3: LessonStage.H322_EXAMPLE_3}[skip_to]
                target_intro = {1: H322_EXAMPLE_1_INTRO, 2: H322_EXAMPLE_2_INTRO, 3: H322_EXAMPLE_3_INTRO}[skip_to]
                self.stage = target_stage
                self._h322_example_subflags = set()
                viz = _STAGE_MANDATORY_VIZ.get(target_stage)
                return LessonStep(stage=self.stage.value,
                                  message=f"好的，跳到例 {skip_to}：\n\n" + target_intro,
                                  canvas_action=viz)
            ack = (protocol.get("ack_text") or "")[:200]
            if not ack:
                ack = "（继续作答）"
            if protocol.get("diagnosis") == "correct" and protocol.get("advance"):
                # 协议判 advance 但诊断器没命中 → 标 phase required flag 防卡循环
                hit = protocol.get("hit_goal")
                if hit:
                    implies = config["implies"].get(hit, set())
                    subflags |= implies
                    self._h322_example_subflags = subflags
                    if done_fn(subflags):
                        return self._h322_advance_example(example_key)
                    # v3.49：subflags 更新后**必须重算 next_phase**，否则 ack 后又问已答的 phase
                    new_next = self._h322_find_next_unanswered_phase(example_key, subflags)
                    if new_next is not None:
                        next_phase = new_next
            # 用协议 ack + 下一 phase 提问（next_phase 已是更新后的值）
            phase_prompt = self._h322_example_phase_prompt(example_key, next_phase)
            return LessonStep(stage=self.stage.value, message=ack + "\n\n" + phase_prompt)

        # 5. Layer 3: deterministic
        return LessonStep(
            stage=self.stage.value,
            message=self._h322_example_phase_prompt(example_key, next_phase),
        )

    def _h322_example_phase_prompt(self, example_key, phase: str) -> str:
        """例题每 phase 的 hard-coded 提问文案。"""
        prompts = {
            (1, "ask_form"):        "**第 1 步**：把方程 $9y^2-16x^2=144$ 化为标准方程，判断焦点在哪个轴？",
            (1, "ask_ab"):          "**第 2 步**：从标准方程读出**实半轴长 $a$** 和**虚半轴长 $b$**。",
            (1, "ask_focus"):       "**第 3 步**：由 $c^2=a^2+b^2$ 求 $c$，写出**焦点坐标**。",
            (1, "ask_eccentricity"):"**第 4 步**：写出**离心率** $e=\\dfrac{c}{a}=?$",
            (1, "ask_asymptote"):   "**第 5 步**：写出**渐近线方程**。注意焦点在 y 轴时，渐近线是 $y=\\pm\\dfrac{a}{b}x$（不是 b/a！）",
            (2, "ask_relation"):    "**第 1 步**：根据题意，把「$M$ 到 $F$ 的距离」与「$M$ 到直线 $l$ 的距离」的**比值**写成等式。",
            (2, "ask_simplify"):    "**第 2 步**：把比值等式**两边平方并化简**，得到关于 $x, y$ 的方程。",
            (2, "ask_conclude"):    "**第 3 步**：把方程写成标准型，**结论**：M 的轨迹是什么图形？焦点在哪个轴？实轴长 / 虚轴长 是多少？",
            (3, "ask_line"):        "**第 1 步**：先求双曲线的**焦点坐标**（$c^2=a^2+b^2$），再用倾斜角 30° 和 $F_2$ 写出**直线方程**。",
            (3, "ask_intersect"):   "**第 2 步**：把直线方程代入双曲线方程，**消去 y**，得到 x 的二次方程；再解出 $x_1, x_2$。",
            (3, "ask_points"):      "**第 3 步**：把 $x_1, x_2$ 代回直线方程，求出 $A, B$ 两点的坐标。",
            (3, "ask_length"):      "**第 4 步**：用距离公式 $|AB|=\\sqrt{(x_1-x_2)^2+(y_1-y_2)^2}$ 算出 $|AB|$。",
        }
        return prompts.get((example_key, phase), "请继续。")

    # ---- 跨 stage 跳级 ----

    def _jump_to_h321_example(self, target_key) -> LessonStep:
        """从任何 stage 跳到例 1 / 例 2 / 探究。"""
        stage_map = {
            1: (LessonStage.H321_EXAMPLE_1, H321_EXAMPLE_1_INTRO),
            2: (LessonStage.H321_EXAMPLE_2, H321_EXAMPLE_2_INTRO),
            "exploration": (LessonStage.H321_EXPLORATION, H321_EXPLORATION_INTRO),
        }
        if target_key not in stage_map:
            return LessonStep(stage=self.stage.value, message="抱歉，没找到对应的例题/探究。")
        target_stage, intro = stage_map[target_key]
        self.stage = target_stage
        viz = _STAGE_MANDATORY_VIZ.get(target_stage)
        label = "探究" if target_key == "exploration" else f"例 {target_key}"
        return LessonStep(
            stage=self.stage.value,
            message=f"好的，切到{label}（教材 3.2.1 节原题）：\n\n" + intro,
            canvas_action=viz,
        )

    # ---- 例题/探究通用推进（仿 _advance_e312_example）----

    def _advance_h321_example(self, example_key, ack: str = "") -> LessonStep:
        """例题/探究通关 → 发 solved viz + awaiting_next。学生确认后才切下一题。"""
        solved_name = "exploration" if example_key == "exploration" else f"example_{example_key}"
        solved_action = {"action": f"show_h321_{solved_name}_solved"}
        actions: List[Dict[str, Any]] = [solved_action]
        # 例 2 / 探究 通关后还有 explore 交互（拖点感受恒等式）
        if example_key in (2, "exploration"):
            actions.append({"action": f"show_h321_{solved_name}_explore"})

        self._h321_example_done_awaiting_next = example_key
        label = "探究" if example_key == "exploration" else f"例 {example_key}"
        head = ack + "\n\n" if ack else ""
        if example_key == "exploration":
            tail = f"🎉 {label} 完成！\n\n本节内容（例 1 / 例 2 / 探究）全部做完。准备好了回个「好」/「继续」我们看本课总结 📒。"
        elif example_key == 2:
            tail = f"🎉 {label} 完成！右边是完整答案图，拖动 P 看 |PA|-|PB|=680 恒成立。回个「好」/「继续」我们看下一题（探究）。"
        else:
            tail = f"🎉 {label} 完成！右边是完整答案图。回个「好」/「继续」我们看下一题。"

        return LessonStep(
            stage=self.stage.value,
            message=head + tail,
            canvas_action=actions if len(actions) > 1 else actions[0],
        )

    def _continue_to_next_h321_example(self, completed_key) -> LessonStep:
        """学生确认后真正切到下一例 / 探究 / SUMMARY。"""
        if completed_key == 1:
            self.stage = LessonStage.H321_EXAMPLE_2
            next_msg = H321_EXAMPLE_2_INTRO
            viz = _STAGE_MANDATORY_VIZ.get(LessonStage.H321_EXAMPLE_2)
        elif completed_key == 2:
            self.stage = LessonStage.H321_EXPLORATION
            next_msg = H321_EXPLORATION_INTRO
            viz = _STAGE_MANDATORY_VIZ.get(LessonStage.H321_EXPLORATION)
        else:  # exploration → SUMMARY
            self.stage = LessonStage.H321_SUMMARY
            next_msg = H321_SUMMARY_MSG
            viz = {"action": "show_h321_summary"}
        return LessonStep(stage=self.stage.value, message=next_msg, canvas_action=viz)

    # ---- 例题/探究通用 handler（仿 _handle_e312_example）----

    def _handle_h321_example_generic(self, text: str, example_key) -> LessonStep:
        """v3.45 重构：例 1 / 例 2 / 探究 共用 handler。

        架构（仿 311 example handler）：
          · 诊断器**扫描所有 canonical goal**，命中 → 累积 implied_flags 到 subflags
          · done_fn(subflags) 满足 → 整道题完成，advance_h321_example 收尾
          · 部分命中 → ack 已答 + 用 phases 提问还没答的部分（教学节奏）

        三层判断：
          Layer 1: example_diagnostician_321（全 goal 扫描）—— 解决"跳级答题"问题
          Layer 2: 路径 2 协议（LLM 输出 JSON）—— 兜底处理诊断器没识别的写法
          Layer 3: deterministic 提示
        """
        from .example_canonicals_321 import EXAMPLE_CONFIGS_321
        from .example_diagnostician_321 import diagnose_example_321

        if not hasattr(self, "_h321_example_phase_idx"):
            self._h321_example_phase_idx = {1: 0, 2: 0, "exploration": 0}
            self._h321_example_subflags = {1: set(), 2: set(), "exploration": set()}

        # awaiting_next 检查 —— 例题通关后等学生确认才切下一题
        awaiting_key = getattr(self, "_h321_example_done_awaiting_next", None)
        if awaiting_key is not None:
            if _looks_like_ready_to_continue(text):
                delattr(self, "_h321_example_done_awaiting_next")
                return self._continue_to_next_h321_example(awaiting_key)
            label = "探究" if awaiting_key == "exploration" else f"例 {awaiting_key}"
            return LessonStep(
                stage=self.stage.value,
                message=f"{label} 已经完成 🎉 看完右边的图后回个「好」/「继续」就切到下一题；想再看图随便拖。",
            )

        # 跨 stage 跳级（跳到其它例题/探究）
        skip = _looks_like_skip_to_example_321(text)
        if skip and skip != example_key:
            return self._jump_to_h321_example(skip)

        config = EXAMPLE_CONFIGS_321[example_key]
        phases = config["phases"]
        idx = self._h321_example_phase_idx[example_key]
        current_phase = phases[idx] if idx < len(phases) else phases[-1]

        # Layer 1: 诊断器扫描所有 goal（v3.45 不再传 phase 参数）
        dx = diagnose_example_321(text, example_key)

        # Layer 2: 协议兜底（诊断器不命中时）
        if dx is None:
            protocol = self._llm_h321_example_protocol(text, example_key, current_phase)
            if protocol is not None:
                diag = protocol.get("diagnosis", "off_topic")
                ack_text = protocol.get("ack_text", "请继续。")[:300]
                skip_n = protocol.get("skip_to_example")

                # (a) skip_request → 跳例
                if diag == "skip_request" and skip_n in (1, 2, "exploration"):
                    return self._jump_to_h321_example(skip_n)

                # (b) correct + advance → 模拟诊断器命中（查 implies_map）
                if diag == "correct" and protocol.get("advance") is True:
                    from .example_diagnostician_321 import ExampleDiagnosis321
                    goal_name = protocol.get("hit_goal") or "equation"  # 默认推进力最强的 goal
                    flags = set(config["implies"].get(goal_name, set()))
                    if not flags:
                        flags = {f"{goal_name}_done"}
                    dx = ExampleDiagnosis321(
                        hit_goal=goal_name, hit_goals=[goal_name],
                        implied_flags=flags,
                        label="完全正确（协议）", via="protocol"
                    )
                    # fall through 到正常推进逻辑

                # (c) partial / wrong / off_topic → ack 但不推进
                elif diag in ("partial", "wrong", "off_topic"):
                    return LessonStep(stage=self.stage.value, message=ack_text)

        # Layer 3: 仍 None → deterministic 提示
        if dx is None:
            return LessonStep(
                stage=self.stage.value,
                message="再想想？或者把你的答案写完整些（比如方程请写成 x²/a² - y²/b² = 1 这样的形式）。",
            )

        # ── v3.45 命中：累积 subflags，按 done_fn 判定收尾或继续教学节奏 ──
        self._h321_example_subflags[example_key] |= dx.implied_flags
        subflags = self._h321_example_subflags[example_key]

        # 整道题完成？（done_fn 满足 → 直接收尾，跳过剩余 phase）
        done_fn = config["done_fn"]
        if done_fn(subflags):
            # 推 phase_idx 到末尾标记"全部完成"
            self._h321_example_phase_idx[example_key] = len(phases)
            return self._advance_h321_example(example_key, ack="✅ 完全正确！")

        # 部分命中：找出下一个还没 done 的 phase 来问（按教学节奏顺序）
        next_phase = None
        next_missing = set()
        for ph in phases:
            required = self._H321_PHASE_REQUIRED_FLAGS.get((example_key, ph), set())
            missing = required - subflags
            if missing:
                next_phase = ph
                next_missing = missing
                break
        if next_phase is None:
            # 所有 phase 都 done 但 done_fn 没满足（理论上不会，保险）
            return self._advance_h321_example(example_key, ack="✅ 完全正确！")

        # 推 phase_idx 到 next_phase 的位置
        self._h321_example_phase_idx[example_key] = phases.index(next_phase)

        # v3.45.1/v3.45.2 missing-aware prompt：只对"多-flag phase 内部部分命中"才用
        # （single-flag phase 没"部分命中"概念，直接用默认 phase prompt 即可）
        next_prompt = None
        next_required = self._H321_PHASE_REQUIRED_FLAGS.get((example_key, next_phase), set())
        if len(next_missing) == 1 and len(next_required) >= 2:
            single_missing = next(iter(next_missing))
            next_prompt = self._H321_PHASE_PROMPT_BY_MISSING.get(
                (example_key, next_phase, single_missing)
            )
        if next_prompt is None:
            # 没注册 missing-aware 文案 / 多个 missing / 单-flag phase → fallback 到默认 phase prompt
            next_prompt = self._h321_example_phase_prompt(example_key, next_phase)

        # ack 已答内容（基于 hit_goals + dx 信息）
        ack = "✅ " + (", ".join(dx.hit_goals[:3]) if dx.hit_goals else "答对了") + " 收到。"
        return LessonStep(stage=self.stage.value, message=ack + "\n\n" + next_prompt)

    # v3.45 phase → required flags 映射（用于"找下一个未答完的 phase"教学节奏）
    _H321_PHASE_REQUIRED_FLAGS = {
        (1, "ask_form"):     {"form_done"},
        (1, "ask_ab"):       {"a_done", "b_done"},
        (1, "ask_equation"): {"equation_done"},
        (2, "ask_setup"):    {"setup_done"},
        (2, "ask_ab"):       {"a_done", "b_done"},
        (2, "ask_equation_with_branch"): {"equation_done", "branch_done"},
        # v3.45.2 探究 ask_slopes 拆 2 个 sub-flag（修分两次答 k_AM/k_BM 死循环）
        ("exploration", "ask_slopes"):    {"slope_am_done", "slope_bm_done"},
        ("exploration", "ask_simplify"):  {"equation_done"},
        ("exploration", "ask_constraint"):{"constraint_done"},
    }

    # v3.45.1 missing-aware prompt：当 phase 部分命中时，按"缺哪个 flag"给精准提示，
    # 避免学生反复看到同一份 phase prompt（如已答分支还被追问完整方程+分支）
    _H321_PHASE_PROMPT_BY_MISSING = {
        # ───── 例 1 ─────
        (1, "ask_ab", "a_done"):
            "还差 $a$：由 $|MF_1|-|MF_2|=\\pm 6$ 推出 $2a=?$ 故 $a=?$",
        (1, "ask_ab", "b_done"):
            "还差 $b$（或 $b^2$）：由 $b^2=c^2-a^2$ 推出 $b^2=?$ 故 $b=?$",
        # ───── 例 2 ─────
        (2, "ask_ab", "a_done"):
            "还差 $a$：由 $2a=680$ 推出 $a=?$",
        (2, "ask_ab", "b_done"):
            "还差 $b^2$：由 $b^2=c^2-a^2=400^2-340^2$ 算出 $b^2=?$",
        (2, "ask_equation_with_branch", "equation_done"):
            "✅ 分支约束你已经答对了。\n\n还差**轨迹方程**：以 $a^2=115600,\\ b^2=44400$ 代入 "
            "$\\dfrac{x^2}{a^2}-\\dfrac{y^2}{b^2}=1$ 形式写出方程。",
        (2, "ask_equation_with_branch", "branch_done"):
            "✅ 方程对了。\n\n还差**分支约束**：$|PA|-|PB|>0$ 意味着 $P$ 离 $A$ 远还是近？$x$ 的范围是？",
        # ───── 探究 ─────
        ("exploration", "ask_slopes", "slope_am_done"):
            "✅ $k_{BM}$ 对了。还差 $k_{AM}$ —— $A(-5, 0)$ 到 $M(x, y)$ 的斜率怎么写？",
        ("exploration", "ask_slopes", "slope_bm_done"):
            "✅ $k_{AM}$ 对了。还差 $k_{BM}$ —— $B(5, 0)$ 到 $M(x, y)$ 的斜率怎么写？",
        ("exploration", "ask_simplify", "equation_done"):
            "✅ 约束对了。\n\n还差**化简方程**：把 $k_{AM}\\cdot k_{BM}=\\dfrac{4}{9}$ 代入展开并化简，"
            "得到的方程是？",
        ("exploration", "ask_constraint", "constraint_done"):
            "✅ 方程对了。\n\n还差**约束**：$k_{AM}, k_{BM}$ 的分母不为零意味着 $x\\ne ?$",
    }

    def _h321_example_phase_prompt(self, example_key, phase: str) -> str:
        """例题/探究 每 phase 的提问文案（hard-coded，不让 LLM 编）。"""
        prompts = {
            (1, "ask_ab"):       "**很好，下一步**：由 $|MF_1|-|MF_2|=\\pm 6$ 得 $2a=?$ 故 $a=?$；又 $c=?$（由焦点距离）；所以 $b^2=c^2-a^2=?$",
            (1, "ask_equation"): "**最后**：把 $a^2, b^2$ 代回标准方程，**双曲线的标准方程**是？",
            (2, "ask_ab"):       "**好**，下一步建立坐标系（A、B 在 $x$ 轴上，原点为 AB 中点）。由 $2a=680$ 得 $a=?$；由 $|AB|=800$ 得 $c=?$；所以 $b^2=?$",
            (2, "ask_equation_with_branch"): "**最后**：写出 P 的轨迹方程，并**注明分支约束**（提示：$|PA|-|PB|>0$ 意味着 P 在哪一支？$x$ 的范围是？）",
            ("exploration", "ask_simplify"):   "**很好**，下一步把 $k_{AM}\\cdot k_{BM}=\\dfrac{4}{9}$ 代入并化简（提示：乘开后再整理成标准形式），得到的方程是？",
            ("exploration", "ask_constraint"): "**最后**：要不要排除某些点？（提示：$k_{AM}, k_{BM}$ 的分母不为零）",
        }
        return prompts.get((example_key, phase), "请继续。")

    # ---- 13 个 stage handler ----

    def _handle_h321_intro(self, text: str) -> LessonStep:
        """1. 开场。学生回应任意内容后推进 RECALL_ELLIPSE。"""
        # 跳例
        skip = _looks_like_skip_to_example_321(text)
        if skip:
            return self._jump_to_h321_example(skip)
        # 学生已经答出椭圆相关 → 直接进 PROBE_DIFFERENCE
        if _looks_like_ellipse_def_recall_321(text):
            self.stage = LessonStage.H321_PROBE_DIFFERENCE
            return LessonStep(stage=self.stage.value, message=H321_PROBE_DIFFERENCE_MSG)
        # 否则推进到 RECALL_ELLIPSE 让学生答
        # v3.43: deterministic 返回，不走 _llm_respond 自由 ack（防 LLM 推偏 stage）
        self.stage = LessonStage.H321_RECALL_ELLIPSE
        return LessonStep(
            stage=self.stage.value,
            message="想想：椭圆是「距离之**和**」的轨迹，请用你自己的话回忆一下定义。",
        )

    def _handle_h321_recall_ellipse(self, text: str) -> LessonStep:
        """2. 回忆椭圆定义。"""
        skip = _looks_like_skip_to_example_321(text)
        if skip:
            return self._jump_to_h321_example(skip)
        if _looks_like_ellipse_def_recall_321(text):
            self.stage = LessonStage.H321_PROBE_DIFFERENCE
            return LessonStep(stage=self.stage.value, message=H321_PROBE_DIFFERENCE_MSG)
        # v3.43 deterministic
        return LessonStep(
            stage=self.stage.value,
            message="提示：椭圆是「到两个焦点的距离之**和**为定值」的轨迹。再说一遍试试。",
        )

    def _handle_h321_probe_difference(self, text: str) -> LessonStep:
        """3. 学生预测后推进 EXPLORE_LOCUS（无论答什么）。
        v3.39 进入 EXPLORE_LOCUS 时主动初始化 _h321_explore_phase = 'ellipse_recap'。"""
        skip = _looks_like_skip_to_example_321(text)
        if skip:
            return self._jump_to_h321_example(skip)
        self.stage = LessonStage.H321_EXPLORE_LOCUS
        # v3.39: 显式初始化 explore phase（不靠 lazy init，让 state 在 stage 切换时就明确）
        self._h321_explore_phase = "ellipse_recap"
        viz = _STAGE_MANDATORY_VIZ.get(LessonStage.H321_EXPLORE_LOCUS)
        # 三类应答的 ack 选择
        if any(kw in text for kw in ["不知道", "不清楚", "没想法"]):
            ack = "没关系，动手画一画就清楚了。\n\n"
        elif any(kw in text for kw in ["双曲线", "两条", "两支", "曲线", "形状"]):
            ack = "不错的猜想！我们去画布验证一下。\n\n"
        else:
            ack = "好，我们去画布上看看。\n\n"
        return LessonStep(
            stage=self.stage.value,
            message=ack + H321_EXPLORE_LOCUS_MSG,
            canvas_action=viz,
            expect_event="trail_completed",
        )

    def _handle_h321_explore_locus(self, text: str) -> LessonStep:
        """4. 教材 p118 双圆模型探究。v3.39 拆 2 phase：

        · phase=ellipse_recap（入口）：发椭圆模型 viz（|F1F2|<|AB|，P 限 AB 内）。
            - 学生答"椭圆"等 → 切到 hyperbola_explore phase，发双曲线模型 viz
            - 学生答错（说"两条" / "双曲线"）→ 提示"先看图回忆椭圆"
        · phase=hyperbola_explore：切到双曲线模型 viz（|F1F2|>|AB|，P 在直线 l 上自由）。
            - 学生答"两条/两支/双曲线" → 推进 AWAIT_SHAPE_NAME / AWAIT_DEFINITION

        deterministic 路径（不调 _llm_respond，杜绝 [VIZ:] 注入）。
        """
        skip = _looks_like_skip_to_example_321(text)
        if skip:
            return self._jump_to_h321_example(skip)

        if not hasattr(self, "_h321_explore_phase"):
            self._h321_explore_phase = "ellipse_recap"
        phase = self._h321_explore_phase

        # ===== Phase 1: 椭圆铺垫 =====
        if phase == "ellipse_recap":
            # 学生答出"椭圆" → 切到 hyperbola_explore phase
            t = text.replace(" ", "")
            saw_ellipse = ("椭圆" in t) or ("ellipse" in t.lower())
            if saw_ellipse:
                self._h321_explore_phase = "hyperbola_explore"
                viz_hyp = {
                    "action": "init_h321_two_circles_hyperbola",
                    "config": {"F1": [-3, 0], "F2": [3, 0], "A": [-1, 4], "B": [1, 4], "line_y": 4},
                }
                return LessonStep(
                    stage=self.stage.value,
                    message=H321_EXPLORE_HYP_PHASE_MSG,
                    canvas_action=viz_hyp,
                )
            # 学生提前说"双曲线" / "两条" → 拉回观察椭圆铺垫
            if _looks_like_hyperbola_name(text) or any(kw in t for kw in [
                "两条", "两支", "两个", "2条", "2支",
            ]):
                return LessonStep(
                    stage=self.stage.value,
                    message="先别急 🙂 现在画布上的 $|F_1F_2|<|AB|$，$P$ 在 $A, B$ 内滑动时，"
                            "$M$ 满足的条件是 $|MF_1|+|MF_2|=|AB|$ —— 这是哪种图形？"
                            "（提示：是我们上节课学过的）",
                )
            # 不知道
            if any(kw in text for kw in ["不知道", "不会", "看不出", "没看到"]):
                return LessonStep(
                    stage=self.stage.value,
                    message="提示：观察右边画布上 $M, M'$ 累积出来的形状——是封闭曲线吗？"
                            "想想 $|MF_1|+|MF_2|=|AB|$ 是什么图形的定义？",
                )
            # 其它
            return LessonStep(
                stage=self.stage.value,
                message="试着先在直线 $l$ 上拖动 $P$（限制在 $A, B$ 之间）"
                        "把 $M, M'$ 的轨迹画完整，再告诉我它是什么图形？",
            )

        # ===== Phase 2: 双曲线探究 =====
        if phase == "hyperbola_explore":
            # 学生直接说"双曲线" → 跳过 SHAPE_NAME，直接进 AWAIT_DEFINITION
            if _looks_like_hyperbola_name(text):
                self.trail_completed = True
                delattr(self, "_h321_explore_phase")
                self.stage = LessonStage.H321_AWAIT_DEFINITION
                return LessonStep(stage=self.stage.value, message=H321_AWAIT_DEFINITION_MSG)
            # 学生答"两条 / 两支" → 推进 AWAIT_SHAPE_NAME
            t = text.replace(" ", "")
            saw_two = any(kw in t for kw in [
                "两条", "两支", "两个", "两根", "2条", "2支", "2个",
                "分开", "分两边", "分支", "对称的两", "两段",
            ])
            if saw_two:
                self.trail_completed = True
                delattr(self, "_h321_explore_phase")
                self.stage = LessonStage.H321_AWAIT_SHAPE_NAME
                return LessonStep(stage=self.stage.value, message=H321_AWAIT_SHAPE_NAME_MSG)
            # 不知道
            if any(kw in text for kw in ["不知道", "不会", "看不出", "没看到"]):
                return LessonStep(
                    stage=self.stage.value,
                    message="试着把 $P$ 拖到 $B$ **右边**远一点的地方（比如 $P.x=5$），"
                            "再拖到 $A$ **左边**远一点（$P.x=-5$），观察 $M, M'$ 画出几条曲线？",
                )
            # 其它
            return LessonStep(
                stage=self.stage.value,
                message="再回画布上拖一下 $P$（特别是 $A, B$ **之外**），数数 $M, M'$ 累积出几条曲线？",
            )

        return LessonStep(stage=self.stage.value, message="（探究阶段已完成。）")

    def _handle_h321_await_shape_name(self, text: str) -> LessonStep:
        """5. 等学生说"双曲线"。"""
        skip = _looks_like_skip_to_example_321(text)
        if skip:
            return self._jump_to_h321_example(skip)
        if _looks_like_hyperbola_name(text):
            self.stage = LessonStage.H321_AWAIT_DEFINITION
            return LessonStep(stage=self.stage.value, message=H321_AWAIT_DEFINITION_MSG)
        # v3.43 deterministic
        return LessonStep(
            stage=self.stage.value,
            message="提示：这个图形有**两支**，在数学里以「双」字开头。",
        )

    def _handle_h321_await_definition(self, text: str) -> LessonStep:
        """6. 学生归纳定义。v3.38 拆 2 phase：

        · phase=await_abs：要求学生定义含「**绝对值**」。
            - 学生答"差是定值"但缺绝对值 → 苏格拉底追问（H321_AWAIT_DEF_ABS_NUDGE_MSG）
            - 学生补上绝对值 → 推进到 await_constraint phase
        · phase=await_constraint：要求学生答出 2a < 2c。
            - 学生答出 → 推进到 H321_REFLECT_COORD
            - 学生答边界情形（=会射线/>无轨迹）→ 温和追问"那 2a 该满足什么不等关系？"

        deterministic 路径为主（不让 LLM 自由 ack）。
        """
        skip = _looks_like_skip_to_example_321(text)
        if skip:
            return self._jump_to_h321_example(skip)

        if not hasattr(self, "_h321_await_def_phase"):
            self._h321_await_def_phase = "await_abs"
        phase = self._h321_await_def_phase

        # ===== Phase 1: 追问绝对值 =====
        if phase == "await_abs":
            if _looks_like_hyperbola_def_with_abs(text):
                self._h321_await_def_phase = "await_constraint"
                return LessonStep(stage=self.stage.value, message=H321_AWAIT_DEF_CONSTRAINT_MSG)
            # 学生答了"差 + 距离"但缺绝对值 → 苏格拉底追问
            if _looks_like_hyperbola_def_diff_only(text):
                return LessonStep(stage=self.stage.value, message=H321_AWAIT_DEF_ABS_NUDGE_MSG)
            # 完全不沾边 → 协议兜底（off_topic / partial）
            protocol = self._llm_h321_protocol(
                text,
                "AWAIT_DEFINITION phase=await_abs：让学生类比椭圆「距离之和」答出「距离之差的绝对值为常数」。"
                "若学生答了「差+常数」但缺「绝对值」，给提示让学生注意两支的对称性。"
            )
            if protocol is not None:
                ack = (protocol.get("ack_text") or "")[:200]
                if ack:
                    return LessonStep(stage=self.stage.value, message=ack)
            return LessonStep(
                stage=self.stage.value,
                message="提示：椭圆是「距离之**和**为定值」，双曲线类比是「距离之**？？**为定值」。"
                        "试着把椭圆定义里的『和』换掉。",
            )

        # ===== Phase 2: 追问约束 2a < 2c =====
        if phase == "await_constraint":
            if _looks_like_constraint_2a_lt_2c(text):
                # 退栈、推进 stage
                delattr(self, "_h321_await_def_phase")
                self.stage = LessonStage.H321_REFLECT_COORD
                return LessonStep(stage=self.stage.value, message=H321_REFLECT_COORD_MSG)
            # 学生提到边界情形 → 温和引导回不等关系
            if _looks_like_constraint_boundary_insight(text):
                return LessonStep(
                    stage=self.stage.value,
                    message="✅ 你想到了**边界情形**！\n\n"
                            "把这些综合起来：$2a$ 和 $2c$ 应该满足什么**不等关系**？"
                            "（写成 $2a \\;?\\; 2c$ 的形式）",
                )
            # 协议兜底
            protocol = self._llm_h321_protocol(
                text,
                "AWAIT_DEFINITION phase=await_constraint：让学生答出 2a<2c 的不等约束。"
                "学生提到边界情形（=会射线/>无轨迹）时，温和引导回不等关系。"
            )
            if protocol is not None:
                ack = (protocol.get("ack_text") or "")[:200]
                if ack:
                    return LessonStep(stage=self.stage.value, message=ack)
            return LessonStep(
                stage=self.stage.value,
                message="提示：动手想想——若 $2a = 2c$，两圆交点的轨迹会变成什么？"
                        "若 $2a > 2c$ 呢？由此推出 $2a$ 和 $2c$ 的**不等关系**。",
            )

        return LessonStep(stage=self.stage.value, message="（定义阶段已完成。）")

    def _handle_h321_reflect_coord(self, text: str) -> LessonStep:
        """7. 思考 1：建系。"""
        skip = _looks_like_skip_to_example_321(text)
        if skip:
            return self._jump_to_h321_example(skip)
        if _looks_like_coord_choice(text):
            self.stage = LessonStage.H321_DERIVE_AND_RESULT
            if not hasattr(self, "_h321_derive_phase"):
                self._h321_derive_phase = "collect_radii"
            viz = _STAGE_MANDATORY_VIZ.get(LessonStage.H321_DERIVE_AND_RESULT)
            return LessonStep(
                stage=self.stage.value,
                message=H321_DERIVE_INTRO_MSG,
                canvas_action=viz,
            )
        # v3.43 deterministic
        return LessonStep(
            stage=self.stage.value,
            message="提示：类比椭圆，把 $F_1F_2$ 所在的直线作 $x$ 轴，$F_1F_2$ 的中垂线作 $y$ 轴。",
        )

    def _handle_h321_derive_and_result(self, text: str) -> LessonStep:
        """8. 推导阶段。3 phase 状态机 + 路径 2 协议。"""
        skip = _looks_like_skip_to_example_321(text)
        if skip:
            return self._jump_to_h321_example(skip)

        if not hasattr(self, "_h321_derive_phase"):
            self._h321_derive_phase = "collect_radii"

        phase = self._h321_derive_phase

        # 关键词识别学生是否已写出最终方程
        t_norm = text.replace(" ", "").lower()
        final_eq_patterns = [
            "x²/a²-y²/(c²-a²)=1", "x^2/a^2-y^2/(c^2-a^2)=1",
            "x²/a²-y²/c²-a²=1",
        ]
        wrote_final_eq = any(p in t_norm for p in final_eq_patterns)

        # 距离公式关键词
        has_mf1 = any(p in t_norm for p in ["(x+c)²+y²", "(x+c)^2+y^2"])
        has_mf2 = any(p in t_norm for p in ["(x-c)²+y²", "(x-c)^2+y^2"])

        if phase == "collect_radii":
            # v3.42: 跨轮累积命中状态（修死循环 —— 学生分两次答 MF1/MF2 也能识别）
            if not hasattr(self, "_h321_derive_radii_hits"):
                self._h321_derive_radii_hits = {"mf1": False, "mf2": False}
            hits = self._h321_derive_radii_hits
            if has_mf1:
                hits["mf1"] = True
            if has_mf2:
                hits["mf2"] = True

            # 两个都命中 → 推进 challenge phase
            if hits["mf1"] and hits["mf2"]:
                self._h321_derive_phase = "challenge"
                delattr(self, "_h321_derive_radii_hits")
                return LessonStep(
                    stage=self.stage.value,
                    message="✅ 两个距离公式都写对了。\n\n**第二步**：你能直接由 $\\bigl||MF_1|-|MF_2|\\bigr|=2a$ 推出最终方程吗？\n试试看（提示：终点形如 $\\dfrac{x^2}{a^2}-\\dfrac{y^2}{?}=1$）。",
                )
            # 本轮命中了某个新公式 → 提示写剩下那个
            if has_mf1 or has_mf2:
                missing = "$|MF_2|$" if hits["mf1"] and not hits["mf2"] else "$|MF_1|$"
                return LessonStep(
                    stage=self.stage.value,
                    message=f"✅ 一个对了。再写另一个距离公式 {missing}。",
                )
            # 本轮没命中任何公式 → v3.44 方案 B 协议兜底（角色 3，socratic_text 2-4 句）
            protocol = self._llm_h321_derive_action_protocol(
                text,
                context_note=(
                    "phase=collect_radii。学生应该写出 $|MF_1|=\\sqrt{(x+c)^2+y^2}$ 和 $|MF_2|=\\sqrt{(x-c)^2+y^2}$。"
                    "若学生答非所问，给苏格拉底提示让他回到距离公式上来。"
                )
            )
            if protocol is not None:
                socratic = (protocol.get("socratic_text") or "")[:500]
                if self._h321_proto_b_advance(protocol):
                    # 协议确认推进 → 切 challenge phase
                    self._h321_derive_phase = "challenge"
                    if hasattr(self, "_h321_derive_radii_hits"):
                        delattr(self, "_h321_derive_radii_hits")
                    challenge_prompt = ("\n\n**第二步**：你能直接由 $\\bigl||MF_1|-|MF_2|\\bigr|=2a$ "
                                        "推出最终方程吗？试试看（提示：终点形如 $\\dfrac{x^2}{a^2}-\\dfrac{y^2}{?}=1$）。")
                    return LessonStep(
                        stage=self.stage.value,
                        message=(socratic or "✅ 好的，进入下一步。") + challenge_prompt,
                    )
                if socratic:
                    return LessonStep(stage=self.stage.value, message=socratic)
            # v3.44 deterministic fallback
            return LessonStep(
                stage=self.stage.value,
                message="提示：用距离公式 $|MF_1|=\\sqrt{(x-(-c))^2+(y-0)^2}$ "
                        "和 $|MF_2|=\\sqrt{(x-c)^2+y^2}$ 写出两个焦半径。",
            )

        if phase == "challenge":
            if wrote_final_eq:
                self._h321_derive_phase = "done"
                self.stage = LessonStage.H321_INTRODUCE_B
                self._h321_introduce_b_phase = "define_b"
                viz = _STAGE_MANDATORY_VIZ.get(LessonStage.H321_INTRODUCE_B)
                return LessonStep(
                    stage=self.stage.value,
                    message="✅ 漂亮！你直接推出来了。\n\n" + H321_INTRODUCE_B_DEFINE_MSG,
                    canvas_action=viz,
                )
            # 学生说不会 → 转入引导路径
            if any(kw in text for kw in ["不会", "不知道", "卡住", "求引导", "提示", "帮我"]):
                self._h321_derive_phase = "guided_simplify"
                return LessonStep(
                    stage=self.stage.value,
                    message="没关系，我们一步步来。\n\n**步骤 1**：由定义 $\\bigl||MF_1|-|MF_2|\\bigr|=2a$，写出含正负号的方程：$\\sqrt{(x+c)^2+y^2}-\\sqrt{(x-c)^2+y^2}=\\pm 2a$。\n移项让一个根号单独留在一边，你能写出来吗？",
                )
            # v3.44 方案 B 协议（角色 3）—— 关键修复：响应 advance=true 推进 stage
            protocol = self._llm_h321_derive_action_protocol(
                text,
                context_note=(
                    "phase=challenge。学生应直接写出最终方程 $\\dfrac{x^2}{a^2}-\\dfrac{y^2}{c^2-a^2}=1$。"
                    "若学生答出此式（或等价形式如 $x^2/a^2-y^2/(c^2-a^2)=1$），diagnosis=完全正确, advance=true。"
                    "若学生答非所问、推不动，给苏格拉底引导让他尝试推或承认不会。"
                )
            )
            if protocol is not None:
                socratic = (protocol.get("socratic_text") or "")[:500]
                if self._h321_proto_b_advance(protocol):
                    # 学生写出最终方程 → 切到 INTRODUCE_B stage
                    self._h321_derive_phase = "done"
                    self.stage = LessonStage.H321_INTRODUCE_B
                    self._h321_introduce_b_phase = "define_b"
                    viz = _STAGE_MANDATORY_VIZ.get(LessonStage.H321_INTRODUCE_B)
                    return LessonStep(
                        stage=self.stage.value,
                        message=(socratic or "✅ 漂亮！你直接推出来了。") + "\n\n" + H321_INTRODUCE_B_DEFINE_MSG,
                        canvas_action=viz,
                    )
                if socratic:
                    return LessonStep(stage=self.stage.value, message=socratic)
            # v3.44 deterministic fallback
            return LessonStep(
                stage=self.stage.value,
                message="试试看：终点是 $\\dfrac{x^2}{a^2}-\\dfrac{y^2}{c^2-a^2}=1$（**不要引入字母 b**）。\n\n"
                        "卡住可以说『不会』我会一步一步帮你。",
            )

        if phase == "guided_simplify":
            if wrote_final_eq:
                self._h321_derive_phase = "done"
                self.stage = LessonStage.H321_INTRODUCE_B
                self._h321_introduce_b_phase = "define_b"
                viz = _STAGE_MANDATORY_VIZ.get(LessonStage.H321_INTRODUCE_B)
                return LessonStep(
                    stage=self.stage.value,
                    message="✅ 推导完成！\n\n" + H321_INTRODUCE_B_DEFINE_MSG,
                    canvas_action=viz,
                )
            # v3.44 方案 B 协议（角色 3）—— 苏格拉底逐步引导 + 响应 advance
            protocol = self._llm_h321_derive_action_protocol(
                text,
                context_note=(
                    "phase=guided_simplify。你正在**逐步引导**学生从距离公式推到最终方程：\n"
                    "  (1) 移项 → $\\sqrt{(x+c)^2+y^2}=\\sqrt{(x-c)^2+y^2}\\pm 2a$\n"
                    "  (2) 第一次平方 + 整理 → $cx-a^2=\\pm a\\sqrt{(x-c)^2+y^2}$\n"
                    "  (3) 第二次平方 + 整理 → $(c^2-a^2)x^2-a^2y^2=a^2(c^2-a^2)$\n"
                    "  (4) 两边除以 $a^2(c^2-a^2)$ → $\\dfrac{x^2}{a^2}-\\dfrac{y^2}{c^2-a^2}=1$\n"
                    "诊断学生当前在哪一步、有什么错；用 socratic_text 给下一步提示（不要替学生写完）。"
                    "学生写出最终方程时 advance=true。"
                )
            )
            if protocol is not None:
                socratic = (protocol.get("socratic_text") or "")[:500]
                if self._h321_proto_b_advance(protocol):
                    self._h321_derive_phase = "done"
                    self.stage = LessonStage.H321_INTRODUCE_B
                    self._h321_introduce_b_phase = "define_b"
                    viz = _STAGE_MANDATORY_VIZ.get(LessonStage.H321_INTRODUCE_B)
                    return LessonStep(
                        stage=self.stage.value,
                        message=(socratic or "✅ 推导完成！") + "\n\n" + H321_INTRODUCE_B_DEFINE_MSG,
                        canvas_action=viz,
                    )
                if socratic:
                    return LessonStep(stage=self.stage.value, message=socratic)
            # v3.44 deterministic fallback
            return LessonStep(
                stage=self.stage.value,
                message="提示：把一个根号留在等号一边，两次平方就能消掉根号。最后两边除以 $a^2(c^2-a^2)$ 即可。\n\n"
                        "目标式：$\\dfrac{x^2}{a^2}-\\dfrac{y^2}{c^2-a^2}=1$。",
            )

        return LessonStep(stage=self.stage.value, message="（推导阶段已完成。）")

    def _handle_h321_introduce_b(self, text: str) -> LessonStep:
        """9. 引入 b + y 轴形式。2 phase。"""
        skip = _looks_like_skip_to_example_321(text)
        if skip:
            return self._jump_to_h321_example(skip)

        if not hasattr(self, "_h321_introduce_b_phase"):
            self._h321_introduce_b_phase = "define_b"

        phase = self._h321_introduce_b_phase

        if phase == "define_b":
            # 学生答出焦点坐标 → 推进 yaxis_form
            if _looks_like_hyperbola_focus_coords_x(text):
                self._h321_introduce_b_phase = "yaxis_form"
                return LessonStep(
                    stage=self.stage.value,
                    message=H321_INTRODUCE_B_YAXIS_MSG,
                )
            # 学生说"已经写出 b²=c²-a²" → 推进
            if _looks_like_b_squared_c_minus_a(text):
                # 给提示去写焦点
                return LessonStep(
                    stage=self.stage.value,
                    message="✅ 对，$b^2=c^2-a^2$。\n\n那么焦点 $F_1, F_2$ 的坐标是？（提示：在 $x$ 轴上，到原点距离为 $c$）",
                )
            # v3.44 方案 B 协议（角色 3）
            protocol = self._llm_h321_introduce_b_action_protocol(
                text,
                context_note=(
                    "phase=define_b。学生应答出焦点坐标 $F_1(-c, 0), F_2(c, 0)$。"
                    "强调对比：双曲线 $b^2=c^2-a^2$ vs 椭圆 $b^2=a^2-c^2$。"
                    "**严禁**讨论 y 轴形式（下一 phase）或离心率/渐近线（属 3.2.2）。"
                )
            )
            if protocol is not None:
                socratic = (protocol.get("socratic_text") or "")[:500]
                if self._h321_proto_b_advance(protocol):
                    self._h321_introduce_b_phase = "yaxis_form"
                    return LessonStep(
                        stage=self.stage.value,
                        message=(socratic or "✅ 焦点对了。") + "\n\n" + H321_INTRODUCE_B_YAXIS_MSG,
                    )
                if socratic:
                    return LessonStep(stage=self.stage.value, message=socratic)
            # v3.44 deterministic fallback
            return LessonStep(
                stage=self.stage.value,
                message="提示：焦点在 $x$ 轴上，到原点距离 $c$，所以 $F_1, F_2$ 坐标是？",
            )

        if phase == "yaxis_form":
            if _looks_like_yaxis_hyperbola_eq(text):
                self.stage = LessonStage.H321_EXAMPLE_1
                viz = _STAGE_MANDATORY_VIZ.get(LessonStage.H321_EXAMPLE_1)
                return LessonStep(
                    stage=self.stage.value,
                    message="✅ 完全正确！焦点在 $y$ 轴时方程是 $\\dfrac{y^2}{a^2}-\\dfrac{x^2}{b^2}=1$。\n\n"
                            "至此双曲线的两种标准方程都掌握了。下面我们用 3 道题（例 1、例 2、探究）巩固。\n\n"
                            + H321_EXAMPLE_1_INTRO,
                    canvas_action=viz,
                )
            # v3.44 方案 B 协议（角色 3）
            protocol = self._llm_h321_introduce_b_action_protocol(
                text,
                context_note=(
                    "phase=yaxis_form。学生应类比椭圆 y 轴形式，写出双曲线 y 轴方程 "
                    "$\\dfrac{y^2}{a^2}-\\dfrac{x^2}{b^2}=1$（提示：把 x 与 y 互换）。"
                    "**严禁**讨论离心率/渐近线（属 3.2.2 下一节）。"
                )
            )
            if protocol is not None:
                socratic = (protocol.get("socratic_text") or "")[:500]
                if self._h321_proto_b_advance(protocol):
                    # 推进到 EXAMPLE_1
                    self.stage = LessonStage.H321_EXAMPLE_1
                    if hasattr(self, "_h321_introduce_b_phase"):
                        delattr(self, "_h321_introduce_b_phase")
                    viz = _STAGE_MANDATORY_VIZ.get(LessonStage.H321_EXAMPLE_1)
                    return LessonStep(
                        stage=self.stage.value,
                        message=(socratic or "✅ 完全正确！焦点在 $y$ 轴时方程是 $\\dfrac{y^2}{a^2}-\\dfrac{x^2}{b^2}=1$。")
                                + "\n\n至此双曲线的两种标准方程都掌握了。下面我们用 3 道题（例 1、例 2、探究）巩固。\n\n"
                                + H321_EXAMPLE_1_INTRO,
                        canvas_action=viz,
                    )
                if socratic:
                    return LessonStep(stage=self.stage.value, message=socratic)
            # v3.44 deterministic fallback
            return LessonStep(
                stage=self.stage.value,
                message="提示：把 $x$ 与 $y$ 在 $\\dfrac{x^2}{a^2}-\\dfrac{y^2}{b^2}=1$ 里互换试试。",
            )

        return LessonStep(stage=self.stage.value, message="（引入 $b$ 阶段已完成。）")

    def _handle_h321_example_1(self, text: str) -> LessonStep:
        """10. 🟡 例 1。"""
        return self._handle_h321_example_generic(text, 1)

    def _handle_h321_example_2(self, text: str) -> LessonStep:
        """11. 🟡 例 2。"""
        return self._handle_h321_example_generic(text, 2)

    def _handle_h321_exploration(self, text: str) -> LessonStep:
        """12. 🔍 探究（结构仿 311 例 3，路径 2 协议独立实现）。"""
        return self._handle_h321_example_generic(text, "exploration")

    def _handle_h321_summary(self, text: str) -> LessonStep:
        """13. 总结。v3.43 改 deterministic：杜绝 LLM 自由 ack。"""
        self.summary_turns += 1
        if _looks_like_lesson_end(text) or self.summary_turns >= 6:
            self.lesson_ended = True
            return LessonStep(
                stage=self.stage.value,
                message=(
                    "👏 恭喜完成 3.2.1 课程！\n\n"
                    "下次见 —— 我们将进入 3.2.2「双曲线的简单几何性质」，"
                    "看实轴/虚轴/渐近线/离心率（$e>1$，与椭圆 $0<e<1$ 互补）。\n\n"
                    "[LESSON_END]"
                ),
            )
        # 非结课轮次：保留协议兜底（学生可能继续问问题），但兜底失败用 deterministic
        protocol = self._llm_h321_protocol(text, "SUMMARY：学生在总结阶段闲聊或提问。简短回答后引导结课。")
        if protocol is not None:
            ack = (protocol.get("ack_text") or "")[:200]
            if ack:
                return LessonStep(stage=self.stage.value, message=ack)
        return LessonStep(
            stage=self.stage.value,
            message="还有什么问题想问？或者输入「结束」结课。",
        )

    # ================================================================
    # ---- 双曲线 3.2.2 课 handler（v3.46 新增，11 stage）----
    # 架构：5 LLM 角色混合谱（见 _STAGE_GOALS_H322 注释）
    # 阶段 stub 先建结构骨架，后续 Phase 2.5/2.6 填充协议与例题三层防御
    # ================================================================

    # ---- H322 工具：跨 stage 跳级到例题 ----
    def _looks_like_skip_to_example_322_local(self, text: str):
        return _looks_like_skip_to_example_322(text)

    def _handle_h322_intro(self, text: str) -> LessonStep:
        """1. 开场。学生回忆 3.1.2 椭圆几何性质 5 维（范围/对称/顶点/轴/离心率）任意 ≥2 个即推进 RANGE。"""
        # v3.51 同源修复：用 _h322_normalize_text 兜空格/全角/LaTeX
        t = self._h322_normalize_text(text)
        kws = ["范围", "对称", "顶点", "长轴", "短轴", "离心率", "e=c/a", "焦点", "性质"]
        hits = sum(1 for kw in kws if kw in t)
        if hits >= 2:
            self.stage = LessonStage.H322_RANGE
            viz = _STAGE_MANDATORY_VIZ.get(LessonStage.H322_RANGE)
            return LessonStep(
                stage=self.stage.value,
                message=(
                    "✅ 没错！3.1.2 我们研究了**范围、对称性、顶点、离心率**这些方面。\n\n"
                    "现在我们用**同样的方法**来研究双曲线 $\\dfrac{x^2}{a^2}-\\dfrac{y^2}{b^2}=1\\,(a>0, b>0)$。\n\n"
                    "**第一步 · 范围**：你能从方程出发，推一下 $x$ 和 $y$ 的取值范围吗？"
                ),
                canvas_action=viz,
            )
        # 不命中 → 提示
        return LessonStep(
            stage=self.stage.value,
            message=(
                "提示一下：3.1.2 椭圆几何性质我们研究了几个方面 —— 比如**范围**（x、y 的取值）、"
                "**对称性**、**顶点**、**离心率** 等。你还记得吗？"
            ),
        )

    def _handle_h322_range(self, text: str) -> LessonStep:
        """2. 范围阶段：v3.46 partial-aware 累积式推进。

        学生可分两次答（先 x 再 y / 先 y 再 x），任一命中累积对应 sub_flag，
        两个都齐才推进到 SYMMETRY。
        """
        t = self._h322_normalize_text(text)
        # 初始化 subflags
        if not hasattr(self, "_h322_range_subflags"):
            self._h322_range_subflags = set()
        subflags = self._h322_range_subflags

        has_x = any(kw in t for kw in [
            "|x|≥a", "|x|>=a", "x≥a", "x>=a", "x≤-a", "x<=-a", "x>a", "x<-a",
            "x大于等于a", "x大于等于α", "x小于等于-a", "x>=a或", "x≥a或", "x≥a或x≤-a", "x≤-a或x≥a",
        ])
        has_y = any(kw in t for kw in [
            "y∈R", "y∈ℝ", "y任意", "y所有", "y为任意", "y的范围是R",
            "y∈实数", "y属于R", "y属于实数", "无界", "无穷", "yR",
            "yIS R", "yisR", "y可以取任意", "y可以是任意",
            "y是任意", "y为实数", "y是实数", "y是任意实数", "y为任意实数",
        ])
        # 宽松回退：含 y + (任意/实数/全部/无限制) 任一搭配
        # v3.51 同源修复：用 t（已归一去空格）兜"任意 实数"等带空格写法
        if not has_y and ("y" in t.lower()):
            if any(kw in t for kw in ["任意实数", "全体实数", "所有实数", "任意的实数",
                                       "任意值", "没限制", "没有限制", "不受限", "无限制"]):
                has_y = True

        if has_x:
            subflags.add("x_done")
        if has_y:
            subflags.add("y_done")
        self._h322_range_subflags = subflags

        # 两个都齐 → 推进
        if "x_done" in subflags and "y_done" in subflags:
            # 重置，避免污染下一课
            self._h322_range_subflags = set()
            self.stage = LessonStage.H322_SYMMETRY
            viz = _STAGE_MANDATORY_VIZ.get(LessonStage.H322_SYMMETRY)
            return LessonStep(
                stage=self.stage.value,
                message=(
                    "✅ 完全正确！双曲线上 $|x|\\ge a$、$y\\in\\mathbb{R}$，所以双曲线**位于两条直线 $x=\\pm a$ 外侧**，向 y 方向无限延展。\n\n"
                    "**下一步 · 对称性**：把方程里的 $x$ 换成 $-x$，方程变不变？这说明双曲线关于什么对称？"
                ),
                canvas_action=viz,
            )

        # 只命中 x → 追问 y
        if "x_done" in subflags and "y_done" not in subflags:
            return LessonStep(
                stage=self.stage.value,
                message=(
                    "✅ $x$ 的范围对了：$x\\ge a$ 或 $x\\le -a$（即 $|x|\\ge a$）。\n\n"
                    "**还差 $y$ 的范围**：方程里 $y$ 有没有受限制？$y$ 的取值范围是？"
                ),
            )

        # 只命中 y → 追问 x
        if "y_done" in subflags and "x_done" not in subflags:
            return LessonStep(
                stage=self.stage.value,
                message=(
                    "✅ $y\\in\\mathbb{R}$ 对了。\n\n"
                    "**还差 $x$ 的范围**：由 $\\dfrac{x^2}{a^2}=1+\\dfrac{y^2}{b^2}\\ge 1$，可以推出 $x$ 的范围是什么？"
                ),
            )

        # 都没命中 → 通用提示
        return LessonStep(
            stage=self.stage.value,
            message=(
                "由方程 $\\dfrac{x^2}{a^2}-\\dfrac{y^2}{b^2}=1$ 移项：$\\dfrac{x^2}{a^2}=1+\\dfrac{y^2}{b^2}\\ge 1$，"
                "所以 $x^2\\ge a^2$，即 $|x|\\ge a$。你能从这个不等式说出 $x$ **和** $y$ 的范围吗？（两个都要说）"
            ),
        )

    def _handle_h322_symmetry(self, text: str) -> LessonStep:
        """3. 对称性阶段：v3.46 partial-aware 累积式 + v3.47 加 solved viz 过渡确认。

        学生分次答 y轴/x轴/原点，累积 ≥2 种 → 切 solved viz（4 镜像伙伴动画）+
        标记 awaiting_next 等学生说"好的"再进 VERTICES_AXES（与 e312 同模式）。
        """
        t = self._h322_normalize_text(text)
        if not hasattr(self, "_h322_sym_subflags"):
            self._h322_sym_subflags = set()
        subflags = self._h322_sym_subflags

        # awaiting_next 状态：已发 solved viz，等学生确认进 VERTICES_AXES
        if getattr(self, "_h322_sym_awaiting_next", False):
            t_ready = t
            is_ready = any(kw in t_ready for kw in [
                "好", "好的", "ok", "OK", "可以", "继续", "下一", "准备", "明白了", "懂了",
            ])
            if is_ready:
                self._h322_sym_awaiting_next = False
                self.stage = LessonStage.H322_VERTICES_AXES
                viz = _STAGE_MANDATORY_VIZ.get(LessonStage.H322_VERTICES_AXES)
                return LessonStep(
                    stage=self.stage.value,
                    message=(
                        "👀 **下一步 · 顶点**：右边沙盒里画了 8 个候选点，你**点出**所有在双曲线上的"
                        "「类似椭圆顶点」的特殊点。（提示：可能没你想的那么多！）"
                    ),
                    canvas_action=viz,
                )
            # 学生没说继续 → 让他先看 solved viz 中的 3 个对称伙伴
            return LessonStep(
                stage=self.stage.value,
                message=(
                    "👀 右边图里你可以**拖动点 P**，看 3 个对称伙伴（$P'_x$ 蓝、$P'_y$ 绿、$P'_O$ 紫）"
                    "同步联动 —— 这就是双曲线 3 重对称的可视化。\n\n"
                    "玩够了回个「**好的**」/「**继续**」，进入下一步 · 顶点探究 📍。"
                ),
            )

        if any(kw in t for kw in ["y轴", "Y轴", "纵轴"]):
            subflags.add("y_axis")
        if any(kw in t for kw in ["x轴", "X轴", "横轴"]):
            subflags.add("x_axis")
        if "原点" in t or "中心对称" in t:
            subflags.add("origin")
        self._h322_sym_subflags = subflags

        # 至少 2 种对称答出 → 先发 solved viz（4 镜像伙伴），等学生确认
        if len(subflags) >= 2:
            self._h322_sym_subflags = set()      # 重置 subflags
            self._h322_sym_awaiting_next = True  # 进入 awaiting_next 状态
            return LessonStep(
                stage=self.stage.value,         # 不切 stage，留在 SYMMETRY
                message=(
                    "✅ 没错。双曲线关于 **x 轴、y 轴、原点**都对称。\n"
                    "x 轴和 y 轴是**对称轴**，原点是**对称中心**（即双曲线的**中心**）。\n\n"
                    "👀 右边图切到了**对称伙伴**视图：拖动点 P，看 3 个伙伴（$P'_x, P'_y, P'_O$）同步联动。\n\n"
                    "玩够了回个「**好的**」/「**继续**」，进入下一步 · 顶点探究 📍。"
                ),
                canvas_action={"action": "show_h322_symmetry_solved"},
            )

        # 命中 1 个 → 追问其他
        if len(subflags) == 1:
            answered = next(iter(subflags))
            ack_map = {"y_axis": "y 轴", "x_axis": "x 轴", "origin": "原点"}
            remain = [n for k, n in ack_map.items() if k not in subflags]
            return LessonStep(
                stage=self.stage.value,
                message=(
                    f"✅ 双曲线关于 **{ack_map[answered]}** 对称（确实是这样）。\n\n"
                    f"**还能想到吗**？把 $x$ 换成 $-x$、把 $x, y$ 同时换成 $-x, -y$ 等，"
                    f"双曲线还可能关于 **{remain[0]}** 或 **{remain[1] if len(remain)>1 else ''}** 对称吗？"
                ),
            )

        # 都没命中
        return LessonStep(
            stage=self.stage.value,
            message=(
                "把 $x$ 换成 $-x$、$y$ 换成 $-y$、再两个都换，看看方程是否不变。"
                "由此说说双曲线关于哪些线 / 点对称？（提示：至少有 x 轴、y 轴、原点三个对称对象）"
            ),
        )

    def _handle_h322_vertices_axes(self, text: str) -> LessonStep:
        """4. 顶点+实/虚轴阶段：v3.46 phase 拆分 + 前端点击事件累积。

        phase: vertex_compute（前端 h322_vertex_clicked 事件累积驱动）→ axes_name（术语文本）
        """
        phase = getattr(self, "_h322_vertices_phase", "vertex_compute")
        t = text
        t_clean = t.replace(" ", "")

        # phase 1: vertex_compute —— 学生未点击/未答清
        if phase == "vertex_compute":
            # 文字答出关键内容 → 直接跳过点击进 axes_name
            said_two = any(kw in t_clean for kw in [
                "只有2个", "只有两个", "2个顶点", "两个顶点",
                "顶点只有2", "顶点只有两", "只2个", "仅2个"])
            said_coords = any(kw in t_clean for kw in [
                "A1(-a,0)", "A2(a,0)", "(-a,0)", "(a,0)", "(±a,0)", "A1A2"])
            if said_two or said_coords:
                self._h322_vertices_phase = "axes_name"
                return LessonStep(
                    stage=self.stage.value,
                    message=(
                        "✅ 没错！双曲线顶点**只有 2 个**：$A_1(-a, 0), A_2(a, 0)$"
                        "（令 $x=0$ 方程无实数解 → 与 y 轴无交点）。\n\n"
                        "**下一步 · 术语**：教材把线段 $A_1A_2$ 叫做**实轴**（长 $=2a$），"
                        "$B_1(0,-b), B_2(0,b)$ 连成的线段叫**虚轴**（长 $=2b$）。\n\n"
                        "请你**复述**一下：线段 $A_1A_2$ 叫什么？$B_1B_2$ 叫什么？"
                    ),
                    canvas_action={"action": "show_h322_vertices_solved"},
                )
            # 否则提示去右边沙盒点击
            hits = len(getattr(self, "_h322_vertices_correct_hits", set()))
            if hits == 0:
                return LessonStep(
                    stage=self.stage.value,
                    message=(
                        "👉 请到**右边沙盒**点击你认为是双曲线顶点的点（候选 8 个）。\n\n"
                        "提示：让 $y=0$ 代入方程，$x$ 取哪些值？再让 $x=0$，$y$ 有没有实数解？"
                    ),
                )
            if hits == 1:
                return LessonStep(
                    stage=self.stage.value,
                    message="你已经点中 **1 个**真顶点（绿色）。再找找看，**还有一个**真顶点在哪里？",
                )
            # hits 已 ≥2 但 phase 还没切（理论上不会发生，但保险）
            self._h322_vertices_phase = "axes_name"
            return LessonStep(
                stage=self.stage.value,
                message="✅ 你已经点中了两个真顶点。线段 $A_1A_2$ 叫什么？$B_1B_2$ 叫什么？",
                canvas_action={"action": "show_h322_vertices_solved_with_rect"},
            )

        # phase 2: axes_name —— 检查实/虚轴术语
        if phase == "axes_name":
            has_real = "实轴" in t
            has_imag = "虚轴" in t
            if has_real and has_imag:
                self._h322_vertices_phase = "vertex_compute"  # 重置
                self.stage = LessonStage.H322_ASYMPTOTE
                viz = _STAGE_MANDATORY_VIZ.get(LessonStage.H322_ASYMPTOTE)
                return LessonStep(
                    stage=self.stage.value,
                    message=(
                        "✅ 完全正确！\n\n"
                        "- 线段 $A_1A_2$ 叫**实轴**，长 $=2a$；$a$ 是**实半轴长**\n"
                        "- 线段 $B_1B_2$ 叫**虚轴**，长 $=2b$；$b$ 是**虚半轴长**\n"
                        "- 注意：$B_1, B_2$ **不在双曲线上**，但它们决定了虚轴\n\n"
                        "**下一步 · 渐近线 探究**（教材 p122 图 3.2-9）：\n\n"
                        "利用信息技术画出双曲线 $\\dfrac{x^2}{9}-\\dfrac{y^2}{4}=1$ 和两条直线 "
                        "$\\dfrac{x}{3}\\pm\\dfrac{y}{2}=0$。"
                        "在双曲线的**右支**上取一点 $M$，**测量** $M$ 的横坐标 $x_M$ 以及它到直线 "
                        "$\\dfrac{x}{3}-\\dfrac{y}{2}=0$ 的距离 $d$。\n\n"
                        "👉 **沿曲线向右上方拖动点 $M$**，观察 $x_M$ 与 $d$ 的大小关系，**你发现了什么？**"
                    ),
                    canvas_action=viz,
                )
            if has_real and not has_imag:
                return LessonStep(
                    stage=self.stage.value,
                    message="✅ $A_1A_2$ 叫**实轴**对了。还差 $B_1B_2$ 叫什么？（提示：与实相对的概念）",
                )
            if has_imag and not has_real:
                return LessonStep(
                    stage=self.stage.value,
                    message="✅ $B_1B_2$ 叫**虚轴**对了。还差 $A_1A_2$ 叫什么？（提示：与虚相对的概念）",
                )
            return LessonStep(
                stage=self.stage.value,
                message="教材里把 $A_1A_2$ 和 $B_1B_2$ 各起了一个名字 —— 一个叫**实**轴，一个叫**虚**轴。你能对应一下吗？",
            )

        return LessonStep(stage=self.stage.value, message="请继续。")

    def _handle_h322_asymptote(self, text: str) -> LessonStep:
        """5. 渐近线阶段：v3.47 按教材 p122-123 探究路径设计（2 phase）。

        教材路径：
          phase 1: explore_concrete —— 具体双曲线 x²/9-y²/4=1 拖点 M 感知 x_M↑→d↓ 但 d≠0
          phase 2: generalize_equation —— 推广 y=±(2/3)x 到一般 y=±(b/a)x + 命名渐近线

        架构：deterministic 关键词命中优先；不命中时尝试角色 3 方案 B 协议兜底（无 LLM 时降级）。
        """
        t = self._h322_normalize_text(text)
        if not hasattr(self, "_h322_asymptote_phase"):
            self._h322_asymptote_phase = "explore_concrete"
        phase = self._h322_asymptote_phase

        # ── phase 1: explore_concrete 拖点感知"接近不相交"（partial-aware 累积）──
        if phase == "explore_concrete":
            # 初始化 sub-flag 累积器
            if not hasattr(self, "_h322_asymptote_explore_subflags"):
                self._h322_asymptote_explore_subflags = set()
            sub = self._h322_asymptote_explore_subflags

            close_kw_hit = any(kw in t for kw in [
                "接近", "无限接近", "趋近", "越来越近", "越来越小", "d越来越小",
                "趋于0", "趋向0", "趋于零", "靠近", "贴近", "d越小",
            ])
            not_zero_kw_hit = any(kw in t for kw in [
                "不为0", "不等于0", "不会等于0", "不会为0", "不能等于0", "不到0",
                "永远不", "始终不", "不为零", "不等于零",
                "不相交", "不交", "不会碰", "碰不到", "不会相交", "d≠0",
            ])
            if close_kw_hit:
                sub.add("close_done")
            if not_zero_kw_hit:
                sub.add("not_zero_done")
            self._h322_asymptote_explore_subflags = sub

            has_close = "close_done" in sub
            has_not_zero = "not_zero_done" in sub
            if has_close and has_not_zero:
                # 重置 sub-flags
                self._h322_asymptote_explore_subflags = set()
                self._h322_asymptote_phase = "generalize_equation"
                return LessonStep(
                    stage=self.stage.value,
                    message=(
                        "✅ **完全正确**！这正是教材的发现 ——\n"
                        "「**$x_M$ 越大 → $d$ 越小，但 $d$ 始终 $\\ne 0$**」\n"
                        "也就是：双曲线**无限接近**两条直线，**但永远不相交**。\n\n"
                        "**phase 2 · 推广**：刚才的具体例子里两条直线是 $\\dfrac{x}{3}\\pm\\dfrac{y}{2}=0$，"
                        "也就是 $y=\\pm\\dfrac{2}{3}x$。\n"
                        "注意到 $a=3, b=2$，所以 $\\dfrac{2}{3}=\\dfrac{b}{a}$。\n\n"
                        "那对一般的双曲线 $\\dfrac{x^2}{a^2}-\\dfrac{y^2}{b^2}=1$，这两条「无限接近不相交」的直线方程是？"
                    ),
                    canvas_action={"action": "show_h322_asymptote_generalize"},
                )
            # 只命中 close 没 not_zero（学生只发现一半）
            if has_close and not has_not_zero:
                return LessonStep(
                    stage=self.stage.value,
                    message=(
                        "✅ 没错，$x_M$ 越大时 $d$ 越来越小。\n\n"
                        "**关键问题**：继续拖 M 往右上方，$d$ 会**等于 0** 吗？换句话说，双曲线和直线会**相交**吗？"
                    ),
                )
            if has_not_zero and not has_close:
                return LessonStep(
                    stage=self.stage.value,
                    message=(
                        "✅ 对，双曲线不会和直线相交。\n\n"
                        "**还有另一半**：$x_M$ 越大时，$d$ 是变大还是变小？继续拖 M 观察。"
                    ),
                )
            # 协议兜底（LLM 没 key 时返回 None）
            protocol = self._llm_h322_asymptote_action_protocol(text, "explore_concrete")
            if self._h322_proto_b_advance(protocol):
                self._h322_asymptote_phase = "generalize_equation"
                soc = (protocol.get("socratic_text") or "")[:400]
                return LessonStep(
                    stage=self.stage.value,
                    message=(soc + "\n\n" if soc else "") +
                            "**phase 2 · 推广**：具体的 $y=\\pm\\dfrac{2}{3}x$ 对一般 $a, b$ 该写成什么？",
                    canvas_action={"action": "show_h322_asymptote_generalize"},
                )
            soc = (protocol.get("socratic_text") or "")[:400] if protocol else ""
            return LessonStep(
                stage=self.stage.value,
                message=soc or (
                    "👉 请到**右边沙盒**拖动点 M（在双曲线右支上），看着上方实时显示的 $x_M$ 和 $d$：\n\n"
                    "  · $x_M$ 越来越大时，$d$ 是变大还是变小？\n"
                    "  · $d$ 最后会**等于 0** 吗？\n\n"
                    "用自己的话总结一下你的观察。"
                ),
            )

        # ── phase 2: generalize_equation 推广到一般式 ──
        if phase == "generalize_equation":
            has_general = (("b/a" in t and "y=" in t) or "y=bx/a" in t or "y=b/a*x" in t
                          or "(b/a)x" in t)
            has_double = ("±" in t) or ("正负" in t) or ("-b/a" in t and "b/a" in t)
            if has_general and has_double:
                # 完成 → 推进 EQUILATERAL
                self._h322_asymptote_phase = "explore_concrete"  # 重置
                self.stage = LessonStage.H322_EQUILATERAL
                viz = _STAGE_MANDATORY_VIZ.get(LessonStage.H322_EQUILATERAL)
                return LessonStep(
                    stage=self.stage.value,
                    message=(
                        "✅ **完全正确**！一般情形下，双曲线 $\\dfrac{x^2}{a^2}-\\dfrac{y^2}{b^2}=1$ 的两条「无限接近不相交」直线方程是\n\n"
                        "$$y=\\pm\\dfrac{b}{a}x$$\n\n"
                        "教材把这两条直线叫做双曲线的**渐近线**（asymptote）。\n\n"
                        "（推广路径：过 $A_1, A_2$ 作 $x=\\pm a$、过 $B_1, B_2$ 作 $y=\\pm b$，四线围成矩形，两条对角线方程正是 $y=\\pm\\dfrac{b}{a}x$。）\n\n"
                        "**下一步 · 等轴双曲线**：如果 $a=b$，方程变成什么？渐近线又变成什么？"
                    ),
                    canvas_action=viz,
                )
            # 学生答了具体 y=±(2/3)x 但没推广到一般式
            if "2/3" in t and "y=" in t:
                return LessonStep(
                    stage=self.stage.value,
                    message=(
                        "✅ 具体例子里确实是 $y=\\pm\\dfrac{2}{3}x$。\n\n"
                        "**再往前一步**：注意到 $a=3, b=2$，所以 $\\dfrac{2}{3}=\\dfrac{b}{a}$。\n"
                        "把这个比值换成一般的 $\\dfrac{b}{a}$，对任意双曲线，渐近线方程是？"
                    ),
                )
            # 协议兜底
            protocol = self._llm_h322_asymptote_action_protocol(text, "generalize_equation")
            if self._h322_proto_b_advance(protocol):
                self._h322_asymptote_phase = "explore_concrete"
                self.stage = LessonStage.H322_EQUILATERAL
                viz = _STAGE_MANDATORY_VIZ.get(LessonStage.H322_EQUILATERAL)
                soc = (protocol.get("socratic_text") or "")[:400]
                return LessonStep(
                    stage=self.stage.value,
                    message=(soc + "\n\n" if soc else "") +
                            "**下一步 · 等轴双曲线**：如果 $a=b$，方程变成什么？渐近线又变成什么？",
                    canvas_action=viz,
                )
            soc = (protocol.get("socratic_text") or "")[:400] if protocol else ""
            return LessonStep(
                stage=self.stage.value,
                message=soc or (
                    "刚才的具体例子里两条直线是 $y=\\pm\\dfrac{2}{3}x$（因为 $a=3, b=2$，$\\dfrac{2}{3}=\\dfrac{b}{a}$）。\n\n"
                    "**推广到一般情形**：对双曲线 $\\dfrac{x^2}{a^2}-\\dfrac{y^2}{b^2}=1$，这两条渐近线方程写成 $y=\\pm\\dfrac{?}{?}x$ ？"
                ),
            )

        return LessonStep(stage=self.stage.value, message="请继续。")

    def _handle_h322_equilateral(self, text: str) -> LessonStep:
        """6. 等轴双曲线阶段 stub。"""
        t = self._h322_normalize_text(text)
        has_eq = any(kw in t for kw in ["x²-y²=a²", "x^2-y^2=a^2", "x2-y2=a2"])
        has_asy = ("y=±x" in t or "y=x" in t or "y=-x" in t or "y=x和y=-x" in t)
        if has_eq or has_asy:
            self.stage = LessonStage.H322_ECCENTRICITY
            viz = _STAGE_MANDATORY_VIZ.get(LessonStage.H322_ECCENTRICITY)
            return LessonStep(
                stage=self.stage.value,
                message=(
                    "✅ 完全正确！$a=b$ 时方程变为 $x^2-y^2=a^2$，渐近线 $y=\\pm x$（**互相垂直**），"
                    "我们把它叫做**等轴双曲线**。\n\n"
                    "**下一步 · 离心率**：先回忆一下，**椭圆的离心率怎么定义**的？"
                ),
                canvas_action=viz,
            )
        return LessonStep(
            stage=self.stage.value,
            message=(
                "把 $b=a$ 代入双曲线方程 $\\dfrac{x^2}{a^2}-\\dfrac{y^2}{b^2}=1$ 试试 —— 方程化简成什么？"
                "再把 $b=a$ 代入渐近线 $y=\\pm\\dfrac{b}{a}x$，得到什么？"
            ),
        )

    @staticmethod
    def _h322_normalize_text(text: str) -> str:
        """**v3.48 双曲线 3.2.2 全 stage 通用文本归一化**（推荐 3.3+ 新课程一律复用此模式）。

        历史教训（详见 docs/322_normalize_design.md）：
          做 3.2.2 离心率时一开始我手写了 regex 单独处理 \\dfrac{X}{Y}，结果在
          学生用前端 ÷ 键盘输入 "e = c÷a" 时**没识别**——因为漏了 ÷/×/·/全角括号
          /Unicode 负号等一整套字符。3.1.1/3.1.2/3.2.1 之所以没踩此坑，是因为
          它们**全部走 math_normalizer.normalize() 的 _FULL_HALF 全局映射表**。

        本函数 = math_normalizer._FULL_HALF 全局表 + 322 特有补强：
          · ÷ → /,  ×·⋅∙ → *,  全角括号 → (),  Unicode 负号 → -,  全角斜杠 → /
            等共 21 种字符映射（来自 math_normalizer._FULL_HALF）
          · 反斜杠分数 c\\a → c/a（学生 Word 式分数）
          · LaTeX \\dfrac{X}{Y} / \\frac{X}{Y} → X/Y（KaTeX 前端键盘）
          · 裸大括号 {X}{Y} → X/Y（KaTeX 失内容时的退化形式）
          · $...$ LaTeX 边界 → 剥掉
          · 所有空白（含全角）去掉

        **下一节 3.3 抛物线开发务必复用此函数（不要再单独写 regex 归一）**。
        """
        import re
        from .math_normalizer import _FULL_HALF

        t = text
        # 1. 应用全局 _FULL_HALF 表（÷/×/·/全角括号/Unicode 负号等 21 种字符）
        t = t.translate(_FULL_HALF)
        # 2. 剥 LaTeX 边界 $
        t = t.replace("$", "")
        # 3. v3.52 一次性枚举所有 KaTeX 工具栏可能产生的 LaTeX 命令
        # 顺序：长名先（含子串的）→ 短名后；再做反斜杠分数兜底
        # 3a. \dfrac{X}{Y} / \frac{X}{Y} → X/Y（含任意空白）
        t = re.sub(r"\\d?frac\s*\{\s*([^{}\s]+)\s*\}\s*\{\s*([^{}\s]+)\s*\}", r"\1/\2", t)
        # 3b. \sqrt{X} → sqrt(X)；\sqrt N（数字 / 单字母）→ sqrt(N)
        t = re.sub(r"\\sqrt\s*\{\s*([^{}]+?)\s*\}", r"sqrt(\1)", t)
        t = re.sub(r"\\sqrt\s+(\d+(?:\.\d+)?|\w)", r"sqrt(\1)", t)
        # 注：v3.52 用否定前瞻 (?![a-zA-Z])，因 `\b` 在 `\pm\dfrac` 这种反斜杠紧贴位置不算边界
        # 3c. \pm / \mp → Unicode 符号
        t = re.sub(r"\\pm(?![a-zA-Z])", "±", t)
        t = re.sub(r"\\mp(?![a-zA-Z])", "∓", t)
        # 3d. \cdot / \times → * ；\div → /
        t = re.sub(r"\\(cdot|times)(?![a-zA-Z])", "*", t)
        t = re.sub(r"\\div(?![a-zA-Z])", "/", t)
        # 3e. 比较符
        t = re.sub(r"\\(leq|le)(?![a-zA-Z])", "≤", t)
        t = re.sub(r"\\(geq|ge)(?![a-zA-Z])", "≥", t)
        t = re.sub(r"\\(neq|ne)(?![a-zA-Z])", "≠", t)
        t = re.sub(r"\\approx(?![a-zA-Z])", "≈", t)
        # 3f. 箭头 / 无穷
        t = re.sub(r"\\(to|rightarrow)(?![a-zA-Z])", "→", t)
        t = re.sub(r"\\infty(?![a-zA-Z])", "∞", t)
        # 3g. 希腊字母
        t = re.sub(r"\\pi(?![a-zA-Z])", "π", t)
        t = re.sub(r"\\alpha(?![a-zA-Z])", "α", t)
        t = re.sub(r"\\beta(?![a-zA-Z])", "β", t)
        t = re.sub(r"\\theta(?![a-zA-Z])", "θ", t)
        t = re.sub(r"\\Delta(?![a-zA-Z])", "Δ", t)
        # 4. 裸 {X}{Y}（无 \frac 的退化情况）
        t = re.sub(r"\{\s*([a-zA-Z0-9]+)\s*\}\s*\{\s*([a-zA-Z0-9]+)\s*\}", r"\1/\2", t)
        # 5. 反斜杠分数兜底 c\a → c/a（Word 式；此时所有 \LaTeX 命令已转完）
        t = t.replace("\\", "/")
        # 6. 去所有空白
        t = re.sub(r"\s+", "", t)
        # 7. 去单字母外的多余括号 (a)/(b) → a/b
        t = re.sub(r"\(([a-zA-Z])\)", r"\1", t)
        return t

    @staticmethod
    def _h322_norm_ecc(text: str) -> str:
        """v3.48 兼容别名 → 委托给统一的 _h322_normalize_text。"""
        return LessonFlow._h322_normalize_text(text)

    @staticmethod
    def _p331_normalize_text(text: str) -> str:
        """v3.x 3.3.1 抛物线全 stage 通用文本归一化 → 复用 _h322_normalize_text。

        按 docs/3_3_parabola_dev_guidelines.md 1.3 节硬约束：
          『3.3 开发时直接搬一份重命名为 `_p331_normalize_text`，不要再单独写 regex』
        实现上直接委托 _h322_normalize_text（同一份完整 LaTeX + 全角 + 反斜杠分数归一），
        避免代码重复带来的归一漂移。
        """
        return LessonFlow._h322_normalize_text(text)

    def _handle_h322_eccentricity(self, text: str) -> LessonStep:
        """7. 离心率阶段：v3.46 5 phase + 协议兜底 + slider 体验。

        phases: recall_e → range_e → geometry → slider_experience → link_asymptote
        """
        t = self._h322_norm_ecc(text)
        if not hasattr(self, "_h322_ecc_phase"):
            self._h322_ecc_phase = "recall_e"
        if not hasattr(self, "_h322_ecc_geometry_misses"):
            self._h322_ecc_geometry_misses = 0
        phase = self._h322_ecc_phase

        # ── phase 1: recall_e ──
        if phase == "recall_e":
            # 兼容多种写法：e=c/a / c/a / \dfrac{c}{a} / \frac{c}{a} / 全角等号 / 中文斜杠
            if any(kw in t for kw in ["e=c/a", "c/a", "离心率=c/a", "离心率是c/a", "比值c/a"]):
                self._h322_ecc_phase = "range_e"
                return LessonStep(
                    stage=self.stage.value,
                    message=(
                        "✅ 椭圆离心率 $e=\\dfrac{c}{a}$。\n\n"
                        "**phase 2**：双曲线沿用同样的定义 $e=\\dfrac{c}{a}$。"
                        "在双曲线中 $c$ 和 $a$ 谁大？所以 $e$ 的**范围**是？"
                    ),
                )
            return LessonStep(
                stage=self.stage.value,
                message="先回忆一下：3.1.2 节我们把**椭圆的离心率**定义为什么？写出公式。",
            )

        # ── phase 2: range_e ──
        if phase == "range_e":
            if any(kw in t for kw in ["e>1", "e大于1", "大于1", "c>a"]):
                self._h322_ecc_phase = "geometry"
                return LessonStep(
                    stage=self.stage.value,
                    message=(
                        "✅ 因为 $c>a>0$，所以 $e=\\dfrac{c}{a}>1$（与椭圆 $0<e<1$ **互补**）。\n\n"
                        "**phase 3**：e 越大，双曲线的**形状**会怎样变？（用你自己的话描述）"
                    ),
                )
            return LessonStep(
                stage=self.stage.value,
                message="双曲线里 $c$ 和 $a$ 比较谁大？由此推出 $e=\\dfrac{c}{a}$ 的**范围**。",
            )

        # ── phase 3: geometry（口述张口大小）──
        if phase == "geometry":
            # v3.51 同源修复：用 t（_h322_normalize_text 后）兜空格
            has_open_word = any(kw in t for kw in ["越大", "越张", "张口", "开口", "越宽", "越张开"])
            if has_open_word:
                # 推进到 slider 体验 phase —— **此时才显式发 slider viz**（不再依赖入口 mandatory）
                self._h322_ecc_phase = "slider_experience"
                return LessonStep(
                    stage=self.stage.value,
                    message=(
                        "✅ 没错，e 越大开口越张。\n\n"
                        "**phase 4**：右边主板上有 e 的**滑块**（e 从 1 → ∞）。"
                        "拖一拖**亲自感受**：e=1.1 / 1.5 / 2 / 5 时形状的变化。\n\n"
                        "（拖完后，告诉我一句话感受。）"
                    ),
                    canvas_action={"action": "show_h322_e_slider"},
                )
            # 卡 ≥2 turn → 主动 fallback 到 slider 让学生体验
            self._h322_ecc_geometry_misses += 1
            if self._h322_ecc_geometry_misses >= 2:
                self._h322_ecc_phase = "slider_experience"
                return LessonStep(
                    stage=self.stage.value,
                    message=(
                        "没关系，我们换个方式看一看 🎚️\n\n"
                        "右边主板上有 e 的**滑块**。拖一拖，看 e=1.1 → 1.5 → 2 → 5 时双曲线开口的变化。"
                        "拖完后，**用你自己的话**告诉我观察到了什么。"
                    ),
                    canvas_action={"action": "show_h322_e_slider"},
                )
            return LessonStep(
                stage=self.stage.value,
                message="提示：固定 $a$，让 $c$ 变大（$e=\\dfrac{c}{a}$ 也变大），双曲线开口会越来越…？",
            )

        # ── phase 4: slider_experience（拖滑块 + 口头总结）──
        if phase == "slider_experience":
            # v3.51 同源修复：用 t（_h322_normalize_text 后）兜空格
            has_summary = any(kw in t for kw in ["越大", "越张", "越宽", "越接近1", "越窄", "开口"])
            if has_summary:
                self._h322_ecc_phase = "link_asymptote"
                return LessonStep(
                    stage=self.stage.value,
                    message=(
                        "✅ 总结到位。e 越大开口越张，e 越接近 1 双曲线越"
                        "「窄」（两支几乎贴着实轴方向）。\n\n"
                        "**phase 5**（教材思考栏）：由 $c^2=a^2+b^2$，"
                        "试着推一下 $\\dfrac{b}{a}$ 和 $e$ 的**关系**。"
                    ),
                )
            return LessonStep(
                stage=self.stage.value,
                message="**先拖一拖** e 的滑块（试 1.1 / 1.5 / 2 / 5），然后用一句话总结 e 与开口的关系。",
            )

        # ── phase 5: link_asymptote ──
        if phase == "link_asymptote":
            # t 已被 _h322_norm_ecc 归一化（去空格 / 全角等号 / LaTeX 分数）
            has_link = (
                "√(e²-1)" in t or "sqrt(e^2-1)" in t or "sqrt(e²-1)" in t
                or "b/a=" in t or "e^2-1" in t or "e²-1" in t
                or "\\sqrt{e^2-1}" in t or "\\sqrt(e^2-1)" in t
                or ("b/a" in t and ("sqrt" in t or "√" in t or "^2" in t))
            )
            if has_link:
                # 完成全 stage → 推进 EXAMPLE_1
                self._h322_ecc_phase = "recall_e"  # 重置
                self.stage = LessonStage.H322_EXAMPLE_1
                viz = _STAGE_MANDATORY_VIZ.get(LessonStage.H322_EXAMPLE_1)
                return LessonStep(
                    stage=self.stage.value,
                    message=(
                        "✅ 完美！由 $e^2=\\dfrac{c^2}{a^2}=\\dfrac{a^2+b^2}{a^2}=1+\\dfrac{b^2}{a^2}$，"
                        "推出 $\\dfrac{b}{a}=\\sqrt{e^2-1}$。\n\n"
                        "→ e 越大 → 渐近线斜率 $b/a$ 越大 → 开口越张。\n\n"
                        "现在我们做 3 道例题巩固一下。\n\n" + H322_EXAMPLE_1_INTRO
                    ),
                    canvas_action=viz,
                )
            return LessonStep(
                stage=self.stage.value,
                message=(
                    "提示：在双曲线中 $c^2=a^2+b^2$，两边都除以 $a^2$ → "
                    "$\\dfrac{c^2}{a^2}=1+\\dfrac{b^2}{a^2}$，左边是 $e^2$，所以 $\\dfrac{b^2}{a^2}=?$"
                ),
            )

        return LessonStep(stage=self.stage.value, message="请继续。")

    def _handle_h322_example(self, text: str, example_num: int) -> LessonStep:
        """8/9/10. 例题阶段：v3.46 311-style 三层防御。委托给 generic handler。"""
        return self._handle_h322_example_generic(text, example_key=example_num)

    def _handle_h322_summary(self, text: str) -> LessonStep:
        """11. 总结。deterministic 结课逻辑。"""
        self.summary_turns += 1
        if _looks_like_lesson_end(text) or self.summary_turns >= 6:
            self.lesson_ended = True
            return LessonStep(
                stage=self.stage.value,
                message=(
                    "👏 恭喜完成 3.2.2 课程！\n\n"
                    "椭圆与双曲线两章已学完。下一节（3.3）我们将进入**抛物线**——"
                    "圆锥曲线第三种、也是离心率 $e=1$ 的临界情形。\n\n"
                    "[LESSON_END]"
                ),
            )
        return LessonStep(
            stage=self.stage.value,
            message="还有什么问题想问？或者输入「结束」结课。",
        )

    # ================================================================
    # ---- 抛物线 3.3.1 课（v3.x 新增 12 stage）handler 集 ----
    # 仿 H321 (3.2.1) 模板：12 stage + 例题三层防御 + awaiting_next + partial 累积 + 跨 stage 跳级
    # 例题内部编号 1/2 对应教材 p132 例 1/2（双向题 + 卫星天线）
    # ================================================================

    # ---- 短答阶段苏格拉底提示协议（角色 3 风格，只给提示不改状态）----
    def _llm_p331_hint(self, student_text: str, sub_goal: str, stuck_level: int):
        """学生答错/卡住时生成**不重复的递进苏格拉底提示**（纯文本）。
        返回提示文本，或 None（LLM 不可用 → 由调用方退回罐头兜底）。
        不改状态、不剧透、不抢跑（由 prompt 铁律约束）。"""
        llm = self._get_llm()
        if llm is None:
            return None
        sys = (_P331_HINT_PROTOCOL_SYSTEM_PROMPT
               .replace("{sub_goal}", sub_goal)
               .replace("{level}", str(stuck_level)))
        try:
            raw = llm.complete(sys, student_text, max_tokens=400, temperature=0.3)
        except Exception as e:
            print(f"[P331 Hint] ❌ provider 全挂 ({type(e).__name__})")
            return None
        txt = (raw or "").strip()
        txt = re.sub(r"\[VIZ:[^\]]*\]", "", txt).strip()   # 剥可能误带的 [VIZ:] 标记
        return txt[:400] if txt else None

    def _p331_socratic(self, text: str, key: str, sub_goal: str, fallback: str) -> str:
        """统一的「答错/卡住」反馈：递进 LLM 提示（角色 3）+ 罐头兜底。
        key 标识当前设问；stuck 计数逐次加深；『不知道』直接跳深一级。"""
        if not hasattr(self, "_p331_stuck"):
            self._p331_stuck = {}
        self._p331_stuck[key] = self._p331_stuck.get(key, 0) + 1
        level = self._p331_stuck[key]
        if any(k in text for k in ["不知道", "不会", "没思路", "没头绪", "不懂", "不清楚"]):
            level = max(level, 2)
        level = min(level, 3)
        hint = self._llm_p331_hint(text, sub_goal, level)
        return hint if hint else fallback

    def _p331_clear_stuck(self, *keys) -> None:
        """推进过某设问后清零其 stuck 计数。"""
        if hasattr(self, "_p331_stuck"):
            for k in keys:
                self._p331_stuck.pop(k, None)

    # ---- 协议函数 ----
    def _llm_p331_derive_protocol(self, student_text: str, current_phase: str) -> Optional[dict]:
        """P331 DERIVE_AND_RESULT 角色 3 协议（仿 _llm_h321_example_protocol）。
        current_phase: write_distance / setup_equation / square_both_sides / final_form。
        """
        llm = self._get_llm()
        if llm is None:
            return None
        ph_ctx = _P331_DERIVE_PHASE_CONTEXT.get(current_phase, f"phase={current_phase}")
        system_prompt = _P331_DERIVE_PROTOCOL_SYSTEM_PROMPT.replace("{phase_context}", ph_ctx)
        try:
            raw = llm.complete(system_prompt, student_text, max_tokens=800, temperature=0.0)
        except Exception as e:
            print(f"[P331 DeriveProto] ❌ phase={current_phase}: provider 全挂 ({type(e).__name__})")
            return None
        parsed = self._parse_protocol_json(raw)
        if parsed is None:
            print(f"[P331 DeriveProto] ⚠️ phase={current_phase}: JSON parse 失败 raw={raw[:120]!r}")
            return None
        if "diagnosis" not in parsed or "advance" not in parsed:
            return None
        print(f"[P331 DeriveProto] ✅ phase={current_phase} diag={parsed.get('diagnosis')}, adv={parsed.get('advance')}")
        return parsed

    def _llm_p331_example_protocol(self, student_text: str, example_key, current_phase: str) -> Optional[dict]:
        """P331 例题路径 2 协议（角色 2）。"""
        llm = self._get_llm()
        if llm is None:
            return None
        ex_ctx = _EXAMPLE_CONTEXT_MAP_P331.get(example_key, "（无上下文）")
        ph_ctx = _EXAMPLE_PHASE_QUESTION_MAP_P331.get((example_key, current_phase), f"phase={current_phase}")
        system_prompt = (_P331_EXAMPLE_PROTOCOL_SYSTEM_PROMPT
                        .replace("{example_context}", ex_ctx)
                        .replace("{phase_context}", ph_ctx))
        try:
            raw = llm.complete(system_prompt, student_text, max_tokens=800, temperature=0.0)
        except Exception as e:
            print(f"[P331Protocol] ❌ ex{example_key}/{current_phase}: provider 全挂 ({type(e).__name__})")
            return None
        parsed = self._parse_protocol_json(raw)
        if parsed is None:
            print(f"[P331Protocol] ⚠️ ex{example_key}/{current_phase}: JSON parse 失败 raw={raw[:120]!r}")
            return None
        if "diagnosis" not in parsed or "advance" not in parsed:
            return None
        print(f"[P331Protocol] ✅ ex{example_key}/{current_phase}: diagnosis={parsed.get('diagnosis')}, advance={parsed.get('advance')}, hit_goal={parsed.get('hit_goal')}")
        return parsed

    # ---- 跳级 / 推进 ----
    def _jump_to_p331_example(self, target_key) -> LessonStep:
        """从任何 stage 跳到例 1 / 例 2。"""
        stage_map = {
            1: (LessonStage.P331_EXAMPLE_1, P331_EXAMPLE_1_INTRO),
            2: (LessonStage.P331_EXAMPLE_2, P331_EXAMPLE_2_INTRO),
        }
        if target_key not in stage_map:
            return LessonStep(stage=self.stage.value, message="抱歉，没找到对应的例题。")
        target_stage, intro = stage_map[target_key]
        self.stage = target_stage
        viz = _STAGE_MANDATORY_VIZ.get(target_stage)
        return LessonStep(
            stage=self.stage.value,
            message=f"好的，切到例 {target_key}（教材 3.3.1 节原题）：\n\n" + intro,
            canvas_action=viz,
        )

    def _p331_find_next_unanswered_phase(self, example_key, subflags: set) -> Optional[str]:
        """按 phase 顺序找第一个未答完的 phase。返回 phase 名或 None（全答完）。"""
        from .example_canonicals_p331 import EXAMPLE_CONFIGS_P331
        if example_key not in EXAMPLE_CONFIGS_P331:
            return None
        phases = EXAMPLE_CONFIGS_P331[example_key]["phases"]
        for phase in phases:
            required = _P331_PHASE_REQUIRED_FLAGS.get((example_key, phase), set())
            if not required.issubset(subflags):
                return phase
        return None

    def _advance_p331_example(self, example_key, ack: str = "") -> LessonStep:
        """例题通关 → 发 solved viz + awaiting_next。学生确认后才切下一题。"""
        solved_action = {"action": f"show_p331_example_{example_key}_solved"}
        actions: List[Dict[str, Any]] = [solved_action]
        # 例 2 通关后可追加 explore 互动（不强求）；当前不加
        self._p331_example_done_awaiting_next = example_key
        head = ack + "\n\n" if ack else ""
        if example_key == 2:
            tail = (
                "🎉 例 2 完成！右边是完整解答图。\n\n"
                "本节内容（例 1 + 例 2）全部做完。回个『好』/『继续』我们看本课总结 📒。"
            )
        else:
            tail = "🎉 例 1 完成！右边是完整解答图。回个『好』/『继续』我们看下一题。"
        return LessonStep(
            stage=self.stage.value,
            message=head + tail,
            canvas_action=actions if len(actions) > 1 else actions[0],
        )

    def _continue_to_next_p331_example(self, completed_key) -> LessonStep:
        """学生确认后真正切到下一例 / SUMMARY。"""
        if completed_key == 1:
            self.stage = LessonStage.P331_EXAMPLE_2
            next_msg = P331_EXAMPLE_2_INTRO
            viz = _STAGE_MANDATORY_VIZ.get(LessonStage.P331_EXAMPLE_2)
        else:  # 2 → SUMMARY
            self.stage = LessonStage.P331_SUMMARY
            next_msg = P331_SUMMARY_MSG
            viz = {"action": "show_p331_summary_compare"}
        return LessonStep(stage=self.stage.value, message=next_msg, canvas_action=viz)

    # ---- 例题通用 handler（仿 _handle_h321_example_generic）----
    def _handle_p331_example_generic(self, text: str, example_key) -> LessonStep:
        """v3.x: 例 1 / 例 2 共用 handler。三层判断 + partial 累积 + 教学节奏保留。

        Layer 1: example_diagnostician_p331（全 goal 扫描）
        Layer 2: 路径 2 协议（_llm_p331_example_protocol）
        Layer 3: deterministic 提示
        """
        from .example_canonicals_p331 import EXAMPLE_CONFIGS_P331
        from .example_diagnostician_p331 import diagnose_example_p331, ExampleDiagnosisP331

        if not hasattr(self, "_p331_example_phase_idx"):
            self._p331_example_phase_idx = {1: 0, 2: 0}
            self._p331_example_subflags = {1: set(), 2: set()}

        # awaiting_next 检查
        awaiting_key = getattr(self, "_p331_example_done_awaiting_next", None)
        if awaiting_key is not None:
            if _looks_like_ready_to_continue(text):
                delattr(self, "_p331_example_done_awaiting_next")
                return self._continue_to_next_p331_example(awaiting_key)
            return LessonStep(
                stage=self.stage.value,
                message=f"例 {awaiting_key} 已经完成 🎉 看完右边的图后回个『好』/『继续』就切到下一题；想再看图随便拖。",
            )

        # 跨例跳级
        skip = _looks_like_skip_to_example_331(text)
        if skip and skip != example_key:
            return self._jump_to_p331_example(skip)

        config = EXAMPLE_CONFIGS_P331[example_key]
        phases = config["phases"]
        idx = self._p331_example_phase_idx[example_key]
        current_phase = phases[idx] if idx < len(phases) else phases[-1]

        # Layer 1: 诊断器扫描所有 goal
        dx = diagnose_example_p331(text, example_key)

        # Layer 2: 协议兜底
        if dx is None:
            protocol = self._llm_p331_example_protocol(text, example_key, current_phase)
            if protocol is not None:
                diag = protocol.get("diagnosis", "off_topic")
                ack_text = (protocol.get("ack_text") or "请继续。")[:300]
                skip_n = protocol.get("skip_to_example")

                # (a) skip_request → 跳例
                if diag == "skip_request" and skip_n in (1, 2):
                    return self._jump_to_p331_example(skip_n)

                # (b) correct + advance → 模拟诊断器命中
                if diag == "correct" and protocol.get("advance") is True:
                    goal_name = protocol.get("hit_goal") or "equation"
                    flags = set(config["implies"].get(goal_name, set()))
                    if not flags:
                        flags = {f"{goal_name}_done"}
                    dx = ExampleDiagnosisP331(
                        hit_goal=goal_name, hit_goals=[goal_name],
                        implied_flags=flags,
                        label="完全正确（协议）", via="protocol",
                    )
                    # fall through

                elif diag in ("partial", "wrong", "off_topic"):
                    return LessonStep(stage=self.stage.value, message=ack_text)

        # Layer 3: 仍 None → deterministic 提示
        if dx is None:
            return LessonStep(
                stage=self.stage.value,
                message="再想想？或者把你的答案写完整些（坐标可以写成 (a, b)，方程写成 y²=2px 这样）。",
            )

        # 命中：累积 + 判定收尾或继续节奏
        self._p331_example_subflags[example_key] |= dx.implied_flags
        subflags = self._p331_example_subflags[example_key]

        done_fn = config["done_fn"]
        if done_fn(subflags):
            self._p331_example_phase_idx[example_key] = len(phases)
            return self._advance_p331_example(example_key, ack="✅ 完全正确！")

        # 部分命中：找下一未答完 phase（按教学节奏）
        next_phase = None
        next_missing: set = set()
        for ph in phases:
            required = _P331_PHASE_REQUIRED_FLAGS.get((example_key, ph), set())
            missing = required - subflags
            if missing:
                next_phase = ph
                next_missing = missing
                break
        if next_phase is None:
            return self._advance_p331_example(example_key, ack="✅ 完全正确！")

        self._p331_example_phase_idx[example_key] = phases.index(next_phase)

        # missing-aware prompt（多-flag phase 内部部分命中时）
        next_prompt = None
        next_required = _P331_PHASE_REQUIRED_FLAGS.get((example_key, next_phase), set())
        if len(next_missing) == 1 and len(next_required) >= 2:
            single_missing = next(iter(next_missing))
            next_prompt = _P331_PHASE_PROMPT_BY_MISSING.get(
                (example_key, next_phase, single_missing)
            )
        if next_prompt is None:
            # 学生可见提问（不含答案）；找不到再退回通用语
            next_prompt = _EXAMPLE_STUDENT_PROMPT_P331.get(
                (example_key, next_phase),
                "请继续。",
            )

        # 干净 ack（不暴露内部 goal 名）
        ack_msg = "✅ 收到。"
        # 例 2：建系（ask_setup）答完进入后续 phase 时，才发坐标系图（setup 图无坐标轴，不剧透建系）
        canvas = None
        if (example_key == 2 and next_phase in ("ask_p", "ask_conclude")
                and not getattr(self, "_p331_ex2_coords_shown", False)):
            self._p331_ex2_coords_shown = True
            canvas = {"action": "show_p331_example_2_coords"}
        return LessonStep(stage=self.stage.value, message=ack_msg + "\n\n" + next_prompt,
                          canvas_action=canvas)

    # ---- 12 个 stage handler ----

    def _p331_recall_accumulate(self, text: str) -> Optional[LessonStep]:
        """RECALL_CONIC partial 累积核心：检验椭圆 + 双曲线两条定义。

        返回：
          · LessonStep（已推进到 PROBE_EQUAL，或给出 partial / 重问 提示）
          · 学生答出椭圆+双曲线两定义 → 推进 PROBE_EQUAL
          · 只答一个 → 苏格拉底追问另一个（累积到 self._p331_recall_done）
        """
        if not hasattr(self, "_p331_recall_done"):
            self._p331_recall_done = set()
        # Layer 1：关键词识别
        if _looks_like_ellipse_recall_p331(text):
            self._p331_recall_done.add("ellipse_recall")
        if _looks_like_hyperbola_recall_p331(text):
            self._p331_recall_done.add("hyperbola_recall")
        hyp_missing_abs = _looks_like_hyperbola_diff_missing_abs(text)
        # Layer 2：角色 1 enum 兜底（捕捉关键词漏掉的口语，如『和是定值』；只分类不驱动状态）
        if not {"ellipse_recall", "hyperbola_recall"}.issubset(self._p331_recall_done):
            hit = self._resolve_phase_answer(text, "p331_recall_conic", lambda _t: None)[0]
            if hit == "ellipse":
                self._p331_recall_done.add("ellipse_recall")
            elif hit == "hyperbola":
                self._p331_recall_done.add("hyperbola_recall")
            elif hit == "both":
                self._p331_recall_done.update({"ellipse_recall", "hyperbola_recall"})
            elif hit == "hyperbola_no_abs":
                hyp_missing_abs = True
        done = self._p331_recall_done
        hyp_missing_abs = hyp_missing_abs and "hyperbola_recall" not in done
        # 两个都答出 → 推进（确定性转场）
        if {"ellipse_recall", "hyperbola_recall"}.issubset(done):
            self._p331_clear_stuck("recall")
            self.stage = LessonStage.P331_PROBE_EQUAL
            return LessonStep(stage=self.stage.value, message=P331_PROBE_EQUAL_MSG)
        # 只答椭圆 → 苏格拉底追问双曲线（角色 3 提示 + 罐头兜底）
        if "ellipse_recall" in done:
            if hyp_missing_abs:
                sub = ("学生已正确说出椭圆定义（距离之和为定值），现在要他说出**双曲线**定义；"
                       "他提到了『差』但漏了『绝对值』。引导他想到：到两焦点的距离之差的**绝对值**为定值"
                       "（只说差只能得一支）。不要直接给出完整定义。")
                fb = ("✅ 椭圆定义对了。双曲线你提到了『差』，但还差一个关键限定 —— "
                      "只说『距离之差为定值』只能得到一支。到两焦点的距离之差的**什么**为定值？")
            else:
                sub = ("学生已正确说出椭圆定义（距离之和为定值），现在引导他说出**双曲线**定义"
                       "（到两焦点的距离之差的绝对值为定值）。不要直接给出答案。")
                fb = "✅ 椭圆定义对了。那 **双曲线** 呢？到两个焦点的距离的**什么**为定值？"
            return LessonStep(stage=LessonStage.P331_RECALL_CONIC.value,
                              message=self._p331_socratic(text, "recall_hyp", sub, fb))
        # 只答双曲线 → 苏格拉底追问椭圆
        if "hyperbola_recall" in done:
            sub = ("学生已正确说出双曲线定义（距离之差的绝对值为定值），现在引导他说出**椭圆**定义"
                   "（到两焦点的距离之和为定值）。不要直接给出答案。")
            fb = "✅ 双曲线定义对了。那 **椭圆** 呢？到两个焦点的距离的**什么**为定值？"
            return LessonStep(stage=LessonStage.P331_RECALL_CONIC.value,
                              message=self._p331_socratic(text, "recall_ell", sub, fb))
        # 学生答了双曲线差但漏绝对值（椭圆也没答）→ 苏格拉底追问
        if hyp_missing_abs:
            sub = ("学生在回忆圆锥曲线定义，提到了双曲线的『差』但漏了『绝对值』，且椭圆定义也没说。"
                   "引导他：双曲线是距离之差的**绝对值**为定值；并提醒椭圆（距离之和）也要说。不要直接给答案。")
            fb = ("你提到了双曲线的『差』，但还差『绝对值』—— 只说差只能得一支。"
                  "到两焦点的距离之差的**什么**为定值？（椭圆那条也别忘了说）")
            return LessonStep(stage=LessonStage.P331_RECALL_CONIC.value,
                              message=self._p331_socratic(text, "recall_both", sub, fb))
        return None  # 一个都没命中，由调用方给重问提示

    def _handle_p331_intro(self, text: str) -> LessonStep:
        """1. 开场。学生第一句即对『回忆椭圆+双曲线定义』的作答 → 走 RECALL 累积逻辑。"""
        skip = _looks_like_skip_to_example_331(text)
        if skip:
            return self._jump_to_p331_example(skip)
        # 第一句答案直接进入 RECALL_CONIC 累积（真实检验两条定义）
        self.stage = LessonStage.P331_RECALL_CONIC
        step = self._p331_recall_accumulate(text)
        if step is not None:
            return step
        # 一个定义都没答出 → 角色 3 苏格拉底提示（罐头兜底）
        sub = ("学生要回忆椭圆和双曲线的定义，但还没答到点上。引导他：椭圆是到两焦点的**距离之和**为定值，"
               "双曲线是到两焦点的**距离之差的绝对值**为定值。不要直接报完整定义，启发他自己说。")
        return LessonStep(stage=self.stage.value,
                          message=self._p331_socratic(text, "recall_both", sub, P331_RECALL_CONIC_MSG))

    def _handle_p331_recall_conic(self, text: str) -> LessonStep:
        """2. 回忆椭圆 / 双曲线定义。确定性关键词推进 + 角色 1 enum 兜底 + partial 累积 + 角色 3 提示。"""
        skip = _looks_like_skip_to_example_331(text)
        if skip:
            return self._jump_to_p331_example(skip)
        step = self._p331_recall_accumulate(text)
        if step is not None:
            return step
        # 都没命中 → 角色 3 苏格拉底提示（罐头兜底）
        sub = ("学生要回忆椭圆和双曲线的定义，但还没答到点上。引导他：椭圆是到两焦点的**距离之和**为定值，"
               "双曲线是到两焦点的**距离之差的绝对值**为定值。不要直接报完整定义，启发他自己说。")
        fb = ("提示：椭圆是『到两个焦点距离**之和**为定值』；双曲线是『距离**之差的绝对值**为定值』。"
              "请把这两条都说一遍试试（可以分多次答）。")
        return LessonStep(stage=self.stage.value,
                          message=self._p331_socratic(text, "recall_both", sub, fb))

    def _handle_p331_probe_equal(self, text: str) -> LessonStep:
        """3. 思维实验：让学生大胆猜。无论答什么都推进到 EXPLORE_LOCUS（**此时发 locus viz**）。
        确定性 ack（仿 3.2.1 _handle_h321_probe_difference，不走角色 4 自由 ack）。"""
        skip = _looks_like_skip_to_example_331(text)
        if skip:
            return self._jump_to_p331_example(skip)
        if any(kw in text for kw in ["不知道", "不清楚", "没想法"]):
            ack = "没关系，动手画一画就清楚了。\n\n"
        elif any(kw in text for kw in ["抛物线", "parabola"]):
            ack = "👍 不错的猜想！我们去画布验证一下。\n\n"
        else:
            ack = "好，我们去画布上看看。\n\n"
        self.stage = LessonStage.P331_EXPLORE_LOCUS
        viz = _STAGE_MANDATORY_VIZ.get(LessonStage.P331_EXPLORE_LOCUS)
        return LessonStep(
            stage=self.stage.value,
            message=ack + P331_EXPLORE_LOCUS_MSG,
            canvas_action=viz,
            expect_event="trail_completed",
        )

    def _handle_p331_explore_locus(self, text: str) -> LessonStep:
        """4. 探究 1。前端 p331_trail_completed 触发推进；学生发关键词也可推进（确定性）。"""
        skip = _looks_like_skip_to_example_331(text)
        if skip:
            return self._jump_to_p331_example(skip)
        # 学生直接说"抛物线"：跳过 SHAPE_NAME 直接 DEFINITION（确定性转场）
        if _looks_like_parabola_name_p331(text):
            self.stage = LessonStage.P331_AWAIT_DEFINITION
            return LessonStep(stage=self.stage.value, message=P331_AWAIT_DEFINITION_MSG)
        # 学生命中 |MF|=|MH| 关键意思（宽松识别『相等』『一样』『MF=MH』等）（确定性转场）
        if _looks_like_mf_eq_mh_p331(text):
            self._p331_clear_stuck("explore")
            self.stage = LessonStage.P331_AWAIT_SHAPE_NAME
            return LessonStep(stage=self.stage.value, message=P331_AWAIT_SHAPE_NAME_MSG)
        # 卡住 → 角色 3 苏格拉底提示（罐头兜底）
        sub = ("学生在拖动点 M 观察 |MF|（到焦点距离）和 |MH|（到准线距离）的关系，还没看出关系。"
               "引导他注意左侧两个实时读数始终相等。不要直接说出『相等』，让他自己发现。")
        fb = "拖动橙点 $M$，看左边 $|MF|$ 和 $|MH|$ 两个实时数值 —— 它们是什么关系？看出来后告诉我（比如『相等』）。"
        return LessonStep(stage=self.stage.value,
                          message=self._p331_socratic(text, "explore", sub, fb))

    def _handle_p331_await_shape_name(self, text: str) -> LessonStep:
        """5. 等学生说『抛物线』。确定性关键词推进 + 角色 1 enum 兜底 + 角色 3 提示。"""
        skip = _looks_like_skip_to_example_331(text)
        if skip:
            return self._jump_to_p331_example(skip)
        # Layer 1 关键词 + Layer 2 enum 兜底
        hit_name = _looks_like_parabola_name_p331(text)
        if not hit_name:
            cls = self._resolve_phase_answer(text, "p331_shape_name", lambda _t: None)[0]
            hit_name = (cls == "parabola")
        if hit_name:
            self._p331_clear_stuck("shape")
            self.stage = LessonStage.P331_AWAIT_DEFINITION
            return LessonStep(stage=self.stage.value, message=P331_AWAIT_DEFINITION_MSG)
        # 卡住 → 角色 3 苏格拉底提示（罐头兜底）
        sub = ("学生画出了一条开放的 U 形曲线，要他说出名字『抛物线』。"
               "引导：物理课抛出去的小球做的就是这种运动，名字以『抛』开头。不要直接说出『抛物线』。")
        fb = "提示：这条开放曲线在物理课讲过 —— 抛出去的小球做的就是这种运动。你猜叫什么？"
        return LessonStep(stage=self.stage.value,
                          message=self._p331_socratic(text, "shape", sub, fb))

    def _handle_p331_await_definition(self, text: str) -> LessonStep:
        """6. 学生归纳定义。**partial 累积**：距离相等 + l 不过 F 两要素跨轮累积，
        两个都命中才推进；只命中一项给针对性追问另一项。"""
        skip = _looks_like_skip_to_example_331(text)
        if skip:
            return self._jump_to_p331_example(skip)
        if not hasattr(self, "_p331_def_done"):
            self._p331_def_done = set()
        # Layer 1：关键词
        if _looks_like_parabola_def_has_equal(text):
            self._p331_def_done.add("def_equal")
        if _looks_like_parabola_def_has_constraint(text):
            self._p331_def_done.add("def_constraint")
        # Layer 2：角色 1 enum 兜底（捕捉关键词漏掉的口语；只分类不驱动状态）
        if not {"def_equal", "def_constraint"}.issubset(self._p331_def_done):
            hit = self._resolve_phase_answer(text, "p331_await_definition", lambda _t: None)[0]
            if hit == "equal":
                self._p331_def_done.add("def_equal")
            elif hit == "constraint":
                self._p331_def_done.add("def_constraint")
            elif hit == "both":
                self._p331_def_done.update({"def_equal", "def_constraint"})
        done = self._p331_def_done
        # 两要素齐 → 推进 REFLECT_COORD（确定性转场）
        if {"def_equal", "def_constraint"}.issubset(done):
            self._p331_clear_stuck("def_equal", "def_constraint", "def_both")
            self.stage = LessonStage.P331_REFLECT_COORD
            return LessonStep(stage=self.stage.value, message=P331_REFLECT_COORD_MSG)
        # 只命中距离相等 → 角色 3 追问限制条件（罐头兜底）
        if "def_equal" in done:
            sub = ("学生已说出抛物线定义的『距离相等』要素（到定点=到定直线的距离），"
                   "还差**限制条件**：定直线 l **不经过**定点 F（否则轨迹退化）。引导他想这个限制，不要直接说出。")
            return LessonStep(stage=self.stage.value,
                              message=self._p331_socratic(text, "def_equal", sub, P331_AWAIT_DEF_EQUAL_NUDGE_MSG))
        # 只命中限制条件 → 角色 3 追问距离关系（罐头兜底）
        if "def_constraint" in done:
            sub = ("学生已说出『定直线不过定点』的限制，还差**核心距离关系**：到定点 F 的距离 = 到定直线 l 的距离。"
                   "引导他说出这个相等关系，不要直接给出。")
            return LessonStep(stage=self.stage.value,
                              message=self._p331_socratic(text, "def_constraint", sub, P331_AWAIT_DEF_LINE_NUDGE_MSG))
        # 一个都没命中 → 角色 3 提示（罐头兜底）
        sub = ("学生在归纳抛物线定义，还没答到点上。两要素：① 到定点和到定直线的**距离相等**；"
               "② 定直线**不经过**定点。引导他往这两点想，不要直接给出完整定义。")
        fb = "提示：抛物线定义两要素 ——（1）到**定点**和到**定直线**的距离是什么关系？（2）这条**定直线**对定点有什么要求？"
        return LessonStep(stage=self.stage.value,
                          message=self._p331_socratic(text, "def_both", sub, fb))

    def _handle_p331_reflect_coord(self, text: str) -> LessonStep:
        """7. 思考 1：建系（**两子阶段**）。
        子阶段 build：① x 轴 = 过 F 垂直准线；② 原点 = KF 中点 —— 两要素累积。
        子阶段 locate_focus：build 完成后右侧画出抛物线，引导学生写出
                             焦点 F(p/2,0) + 准线 x=-p/2；两个都对 → 推进 DERIVE。
        全程确定性 + 角色 1 enum 兜底（只分类不驱动状态）。
        """
        skip = _looks_like_skip_to_example_331(text)
        if skip:
            return self._jump_to_p331_example(skip)
        if not hasattr(self, "_p331_coord_subphase"):
            self._p331_coord_subphase = "build"

        # ───── 子阶段 2：locate_focus（焦点坐标 + 准线方程）─────
        if self._p331_coord_subphase == "locate_focus":
            if not hasattr(self, "_p331_focus_done"):
                self._p331_focus_done = set()
            # Layer 1 关键词
            if _looks_like_p331_focus_pq(text):
                self._p331_focus_done.add("focus")
            if _looks_like_p331_directrix_pq(text):
                self._p331_focus_done.add("directrix")
            # Layer 2 enum 兜底
            if not {"focus", "directrix"}.issubset(self._p331_focus_done):
                hit = self._resolve_phase_answer(text, "p331_locate_focus", lambda _t: None)[0]
                if hit == "focus":
                    self._p331_focus_done.add("focus")
                elif hit == "directrix":
                    self._p331_focus_done.add("directrix")
                elif hit == "both":
                    self._p331_focus_done.update({"focus", "directrix"})
            fdone = self._p331_focus_done
            # 两个都对 → 建系阶段完成，推进 DERIVE
            if {"focus", "directrix"}.issubset(fdone):
                self.stage = LessonStage.P331_DERIVE_AND_RESULT
                viz = _STAGE_MANDATORY_VIZ.get(LessonStage.P331_DERIVE_AND_RESULT)
                return LessonStep(
                    stage=self.stage.value,
                    message=P331_DERIVE_START_MSG,
                    canvas_action=viz,
                )
            # 只答对焦点 → 角色 3 追问准线（罐头兜底）
            if "focus" in fdone:
                sub = ("学生已写对焦点 $F(p/2,0)$，还差**准线方程**：$K$ 在 x 轴负半轴、$OK=p/2$，"
                       "准线是过 K 的竖直线，方程 $x=-p/2$。引导他自己写出，不要直接报答案。")
                fb = "✅ 焦点坐标对了。那 **准线 $l$ 的方程**呢？$K$ 在 x 轴负半轴、$OK=\\dfrac{p}{2}$，准线过 $K$ 竖直 —— 方程是？"
                return LessonStep(stage=self.stage.value,
                                  message=self._p331_socratic(text, "lf_focus", sub, fb))
            # 只答对准线 → 角色 3 追问焦点（罐头兜底）
            if "directrix" in fdone:
                sub = ("学生已写对准线 $x=-p/2$，还差**焦点坐标**：$F$ 在 x 轴正半轴、$OF=p/2$，"
                       "焦点 $(p/2,0)$。引导他自己写出，不要直接报答案。")
                fb = "✅ 准线方程对了。那 **焦点 $F$ 的坐标**呢？$F$ 在 x 轴正半轴、$OF=\\dfrac{p}{2}$ —— 坐标是？"
                return LessonStep(stage=self.stage.value,
                                  message=self._p331_socratic(text, "lf_dir", sub, fb))
            # 都没对 → 角色 3 提示（罐头兜底）
            sub = ("学生要由 $|KF|=p$、$O$ 是 KF 中点 写出焦点坐标和准线方程。$OF=OK=p/2$，"
                   "$F$ 在正半轴 → $(p/2,0)$；$K$ 在负半轴、准线过 K 竖直 → $x=-p/2$。引导他想，不要直接报答案。")
            fb = ("提示：$O$ 是 $KF$ 中点、$|KF|=p$，所以 $OF=OK=\\dfrac{p}{2}$。"
                  "$F$ 在正半轴 → 焦点坐标？准线过 $K$ 竖直 → 准线方程？（用 $p$ 表示）")
            return LessonStep(stage=self.stage.value,
                              message=self._p331_socratic(text, "lf_both", sub, fb))

        # ───── 子阶段 1：build（x 轴 + 原点）─────
        if not hasattr(self, "_p331_coord_done"):
            self._p331_coord_done = set()
        # Layer 1：关键词
        if _looks_like_p331_axis_correct(text):
            self._p331_coord_done.add("axis")
        if _looks_like_p331_origin_correct(text):
            self._p331_coord_done.add("origin")
        directrix_misuse = _looks_like_p331_directrix_as_axis(text)
        # Layer 2：角色 1 enum 兜底（只分类不驱动状态）
        if not {"axis", "origin"}.issubset(self._p331_coord_done):
            hit = self._resolve_phase_answer(text, "p331_reflect_coord", lambda _t: None)[0]
            if hit == "axis":
                self._p331_coord_done.add("axis")
            elif hit == "origin":
                self._p331_coord_done.add("origin")
            elif hit == "both":
                self._p331_coord_done.update({"axis", "origin"})
            elif hit == "directrix_as_axis":
                directrix_misuse = True
        done = self._p331_coord_done

        # build 两要素齐 → 进入 locate_focus 子阶段（右侧画出抛物线 + 引导求焦点/准线）
        if {"axis", "origin"}.issubset(done):
            self._p331_clear_stuck("coord_axis", "coord_origin", "coord_both")
            self._p331_coord_subphase = "locate_focus"
            self._p331_focus_done = set()
            return LessonStep(
                stage=self.stage.value,
                message=P331_LOCATE_FOCUS_MSG,
                canvas_action={"action": "show_p331_coord_solved"},
            )
        # 只答对 x 轴 → 角色 3 追问原点（罐头兜底）
        if "axis" in done:
            sub = ("学生已答对 x 轴（过焦点 F 垂直准线），还差**原点位置**：应取在焦点 F 和准线 l 之间的"
                   "**中点**（最对称）。引导他想原点取哪最对称，不要直接说出。")
            fb = "✅ $x$ 轴选得好。那 **原点** 该取在哪里最对称？想想焦点 $F$ 和准线 $l$ 之间，哪个位置左右对称？"
            return LessonStep(stage=self.stage.value,
                              message=self._p331_socratic(text, "coord_origin", sub, fb))
        # 只答对原点 → 角色 3 追问 x 轴（罐头兜底）
        if "origin" in done:
            sub = ("学生已答对原点（焦点和准线之间的中点），还差 **x 轴**：应取**过焦点 F 且垂直于准线 l** 的那条直线"
                   "（它是抛物线的对称轴）。引导他想 x 轴怎么取，不要直接说出。")
            fb = "✅ 原点位置想得对。那 **$x$ 轴** 该怎么取？提示：过焦点 $F$ 且和准线 $l$ 有什么位置关系的直线？"
            return LessonStep(stage=self.stage.value,
                              message=self._p331_socratic(text, "coord_axis", sub, fb))
        # 误区：把准线当坐标轴 → 角色 3 针对性纠正（罐头兜底）
        if directrix_misuse:
            sub = ("学生把准线 l 本身当成了坐标轴（误区）。纠正：准线本身不作坐标轴；"
                   "椭圆/双曲线用焦点连线作 x 轴，抛物线只有 1 个焦点，但**过 F 且垂直准线**的直线天然左右对称，"
                   "把它作 x 轴更合适。温和纠正后引导他重想 x 轴和原点。")
            fb = ("🤔 准线 $l$ 本身**不**作坐标轴哦。过 $F$ 且垂直于准线 $l$ 的那条直线天然左右对称 —— "
                  "把**它**作为 $x$ 轴更合适。你同意吗？那原点取在哪？")
            return LessonStep(stage=self.stage.value,
                              message=self._p331_socratic(text, "coord_both", sub, fb))
        # 一个都没答对 → 角色 3 提示（罐头兜底）
        sub = ("学生在想怎么给抛物线建系，还没答到点上。正确：x 轴 = 过焦点 F 垂直准线的直线；"
               "原点 = 焦点和准线之间的中点。引导他往这两点想，不要直接给出。")
        fb = ("提示：抛物线只有 1 个焦点 $F$ 和 1 条准线 $l$。**过 $F$ 且垂直 $l$** 的那条直线天然是对称轴 —— "
              "把它作为哪条轴？原点又该取在 $F$ 和 $l$ 之间的什么位置？")
        return LessonStep(stage=self.stage.value,
                          message=self._p331_socratic(text, "coord_both", sub, fb))

    def _handle_p331_derive_and_result(self, text: str) -> LessonStep:
        """8. 推导标准方程，角色 3 协议 4 子阶段链。
        子阶段顺序：write_distance → setup_equation → square_both_sides → final_form。
        （焦点坐标 / 准线方程 已在上一阶段 REFLECT_COORD 的 locate_focus 子阶段由学生导出。）
        """
        skip = _looks_like_skip_to_example_331(text)
        if skip:
            return self._jump_to_p331_example(skip)

        if not hasattr(self, "_p331_derive_phase"):
            self._p331_derive_phase = "write_distance"
        current_phase = self._p331_derive_phase

        derive_phases = ["write_distance", "setup_equation", "square_both_sides", "final_form"]

        # awaiting_next：推导完成等学生确认
        if getattr(self, "_p331_derive_awaiting_next", False):
            if _looks_like_ready_to_continue(text):
                self._p331_derive_awaiting_next = False
                self.stage = LessonStage.P331_FOUR_FORMS
                # 进入探究 2：一次一图，从开口向左开始
                first_dir = _P331_FORM_ORDER[0]
                return LessonStep(
                    stage=self.stage.value,
                    message=(
                        "🎉 推导完成 —— 标准方程 $y^2=2px$（$p>0$，开口向右）。\n\n"
                        "**接下来探究 2**（教材 p131）：换个方向建系，方程会怎么变？我们一种一种来。\n\n"
                        + _p331_form_prompt(first_dir)
                    ),
                    canvas_action={"action": f"show_p331_form_{first_dir}"},
                )
            return LessonStep(
                stage=self.stage.value,
                message="推导已经做完啦 🎉 回个『好』/『继续』我们进入 4 种开口方向的对照。",
            )

        # 学生直答最终方程 → 跳过所有子阶段直接收尾
        if _looks_like_p331_final_eq(text):
            self._p331_derive_awaiting_next = True
            return LessonStep(
                stage=self.stage.value,
                message="✅ 完全正确！你直接导出了标准方程 $y^2=2px$（$p>0$）。\n\n"
                        "回个『好』/『继续』，我们进入**探究 2**：看看换个方向建系，方程会怎么变 👉",
                canvas_action={"action": "show_p331_derive_solved"},
            )

        # ── 确定性逐步检测（主路径，不做小错诊断；多设问 write_distance 跨轮累积）──
        def _derive_advance(next_phase: str, msg: str, viz=None) -> LessonStep:
            self._p331_derive_phase = next_phase
            return LessonStep(stage=self.stage.value, message=msg, canvas_action=viz)

        if current_phase == "write_distance":
            if not hasattr(self, "_p331_wd_done"):
                self._p331_wd_done = set()
            if _looks_like_p331_mf_formula(text):
                self._p331_wd_done.add("mf")
            if _looks_like_p331_d_formula(text):
                self._p331_wd_done.add("d")
            wd = self._p331_wd_done
            if {"mf", "d"}.issubset(wd):
                return _derive_advance(
                    "setup_equation",
                    "✅ 两个距离都写对了！\n\n**下一步**：由抛物线定义『到焦点距离 = 到准线距离』，"
                    "即 $|MF|=d$，把这个等式写出来。",
                )
            if "mf" in wd:
                return LessonStep(
                    stage=self.stage.value,
                    message="✅ $|MF|$ 写对了！还差另一半 —— $M(x,y)$ 到准线 $x=-\\dfrac{p}{2}$ 的距离 $d$ 怎么表示？",
                )
            if "d" in wd:
                return LessonStep(
                    stage=self.stage.value,
                    message="✅ $d$ 写对了！还差另一半 —— $M(x,y)$ 到焦点 $F\\left(\\dfrac{p}{2},0\\right)$ "
                            "的距离 $|MF|$ 用两点间距离公式怎么写？",
                )
            # 本轮两者都没命中 → 落到协议兜底（给思路，不纠小错）

        elif current_phase == "setup_equation":
            if _looks_like_p331_setup_eq(text):
                return _derive_advance(
                    "square_both_sides",
                    "✅ 方程建立得对！\n\n**下一步**：等号两边都是非负量，**两边平方**化掉根号和绝对值，写写看？",
                )

        elif current_phase == "square_both_sides":
            if _looks_like_p331_squared(text):
                return _derive_advance(
                    "final_form",
                    "✅ 平方对了！\n\n**最后一步**：展开两边的完全平方式，相同项会消掉，化简成最简形式。",
                )

        elif current_phase == "final_form":
            if _looks_like_p331_final_eq(text):
                self._p331_derive_awaiting_next = True
                return LessonStep(
                    stage=self.stage.value,
                    message="✅ 完全正确！化简得到标准方程 **$y^2=2px$**（$p>0$）。\n\n"
                            "回个『好』/『继续』，我们进入**探究 2**：换个方向建系，方程会怎么变 👉",
                    canvas_action={"action": "show_p331_derive_solved"},
                )

        # ── 走协议兜底（确定性没命中时；只给思路，不纠书写小错）──
        protocol = self._llm_p331_derive_protocol(text, current_phase)
        if protocol is None:
            # 协议挂 → deterministic fallback
            return LessonStep(
                stage=self.stage.value,
                message=_P331_DERIVE_PHASE_CONTEXT.get(current_phase, "继续推导。"),
            )

        diag = protocol.get("diagnosis", "off_topic")
        ack_text = (protocol.get("ack_text") or "继续。")[:300]

        if diag == "skip_request":
            skip_n = protocol.get("skip_to_example")
            if skip_n in (1, 2):
                return self._jump_to_p331_example(skip_n)

        # correct + advance：推到下一子阶段
        if diag == "correct" and protocol.get("advance") is True:
            cur_idx = derive_phases.index(current_phase)
            if cur_idx + 1 < len(derive_phases):
                self._p331_derive_phase = derive_phases[cur_idx + 1]
                return LessonStep(
                    stage=self.stage.value,
                    message=ack_text,
                )
            else:
                # 已是最后一子阶段 → 整个推导完成
                self._p331_derive_awaiting_next = True
                return LessonStep(
                    stage=self.stage.value,
                    message=ack_text + "\n\n🎉 整个推导完成，标准方程 $y^2=2px$（$p>0$）。\n\n"
                            "回个『好』/『继续』，我们进入**探究 2**：换个方向建系，方程会怎么变 👉",
                    canvas_action={"action": "show_p331_derive_solved"},
                )

        # partial / wrong / off_topic：ack 但不推进
        return LessonStep(stage=self.stage.value, message=ack_text)

    def _handle_p331_four_forms(self, text: str) -> LessonStep:
        """9. 探究 2：4 种开口方向（**一次一图，逐方向探究**）。
        开口向右已在推导阶段导出；本阶段按对称变换依次探究 左 → 上 → 下 3 种。
        每个方向：学生输入 ① 标准方程 ② 焦点坐标 ③ 准线方程，三项累积齐 → 出下一幅图。
        确定性结构检测（不计书写格式），无角色 4 自由 ack。
        """
        skip = _looks_like_skip_to_example_331(text)
        if skip:
            return self._jump_to_p331_example(skip)

        # awaiting_next：3 个方向都探究完
        if getattr(self, "_p331_ff_awaiting_next", False):
            if _looks_like_ready_to_continue(text):
                self._p331_ff_awaiting_next = False
                self.stage = LessonStage.P331_EXAMPLE_1
                viz = _STAGE_MANDATORY_VIZ.get(LessonStage.P331_EXAMPLE_1)
                return LessonStep(
                    stage=self.stage.value,
                    message="✅ 4 种开口方向全部探究完成。接下来做 2 道例题巩固。\n\n" + P331_EXAMPLE_1_INTRO,
                    canvas_action=viz,
                )
            return LessonStep(
                stage=self.stage.value,
                message="4 种开口方向都探究完啦 🎉 回个『好』/『继续』我们做例 1。",
            )

        # 初始化逐方向状态
        if not hasattr(self, "_p331_ff_idx"):
            self._p331_ff_idx = 0
            self._p331_ff_done = {d: set() for d in _P331_FORM_ORDER}

        cur_dir = _P331_FORM_ORDER[self._p331_ff_idx]
        spec = _P331_FORM_SPEC[cur_dir]
        done = self._p331_ff_done[cur_dir]

        # 当前方向：检测 方程 / 焦点 / 准线（确定性结构匹配，跨轮累积）
        if _p331_form_item_hit(text, spec["eq_patterns"]):
            done.add("eq")
        if _p331_form_item_hit(text, spec["focus_patterns"]):
            done.add("focus")
        if _p331_form_item_hit(text, spec["dir_patterns"]):
            done.add("directrix")

        # 当前方向三项齐 → 下一方向 / 全部完成
        if {"eq", "focus", "directrix"}.issubset(done):
            self._p331_clear_stuck(f"ff_{cur_dir}")
            if self._p331_ff_idx + 1 < len(_P331_FORM_ORDER):
                self._p331_ff_idx += 1
                nxt = _P331_FORM_ORDER[self._p331_ff_idx]
                return LessonStep(
                    stage=self.stage.value,
                    message=f"🎉 **{spec['label']}** 全对了！进入下一种 👇\n\n" + _p331_form_prompt(nxt),
                    canvas_action={"action": f"show_p331_form_{nxt}"},
                )
            else:
                self._p331_ff_awaiting_next = True
                return LessonStep(
                    stage=self.stage.value,
                    message="🎉 **开口向下** 也对了！4 种开口方向全部探究完毕。\n\n"
                            "回个『好』/『继续』我们做例题。",
                    canvas_action={"action": "show_p331_four_forms_solved"},
                )

        # 部分命中 / 卡住 → 角色 3 苏格拉底提示（罐头兜底），按方向 + 缺项给递进引导
        item_names = {"eq": "标准方程", "focus": "焦点坐标", "directrix": "准线方程"}
        missing = [item_names[k] for k in ("eq", "focus", "directrix") if k not in done]
        got = [item_names[k] for k in ("eq", "focus", "directrix") if k in done]
        head = ("✅ " + "、".join(got) + " 收到。\n\n") if got else ""
        sub = (f"学生在探究**{spec['label']}**的抛物线（由 {spec['from']} {spec['transform']} 得到）。"
               f"已答对：{('、'.join(got)) if got else '无'}；还差：{', '.join(missing)}。"
               f"标准答案（仅供你判断，**不要直接报给学生**）：方程 {spec['eq_show']}、"
               f"焦点 {spec['focus_show']}、准线 {spec['dir_show']}。"
               f"用对称变换『{spec['transform']}』引导学生自己写出还差的项，都用 p 表示。")
        fb = (f"{head}**{spec['label']}** 还差：**{', '.join(missing)}**。"
              f"（提示：由 {spec['from']} {spec['transform']}，都用 $p$ 表示）")
        return LessonStep(stage=self.stage.value,
                          message=self._p331_socratic(text, f"ff_{cur_dir}", sub, fb))

    def _handle_p331_example_1(self, text: str) -> LessonStep:
        return self._handle_p331_example_generic(text, 1)

    def _handle_p331_example_2(self, text: str) -> LessonStep:
        return self._handle_p331_example_generic(text, 2)

    def _handle_p331_summary(self, text: str) -> LessonStep:
        """12. 总结。deterministic 结课。"""
        self.summary_turns += 1
        if _looks_like_lesson_end(text) or self.summary_turns >= 6:
            self.lesson_ended = True
            return LessonStep(
                stage=self.stage.value,
                message=(
                    "👏 恭喜完成 3.3.1 课程！\n\n"
                    "下一节 **3.3.2 抛物线的简单几何性质** 我们会研究范围、对称性、顶点、焦准距等性质。\n\n"
                    "[LESSON_END]"
                ),
            )
        # 未结课 → 确定性提示（不走角色 4 自由 ack）
        return LessonStep(
            stage=self.stage.value,
            message="还有什么问题想问？或者输入「结束」结课。",
        )

    # ================================================================
    # 抛物线 3.3.2 几何性质（P332）handler
    # 架构：性质短答 = 确定性关键词推进 + 角色1 enum 兜底 + 角色3 苏格拉底阶梯反馈；
    #       例题/思考 = 角色2 路径2 协议 + sympy 三层防御 + partial 累积 + awaiting_next。
    # ================================================================

    # ---- 角色 3：短答阶段苏格拉底递进提示（只给提示，不改状态）----
    def _llm_p332_hint(self, student_text: str, sub_goal: str, stuck_level: int):
        """学生答错/卡住时生成**不重复的递进苏格拉底提示**（纯文本）。
        返回提示文本，或 None（LLM 不可用 → 调用方退回罐头兜底）。"""
        llm = self._get_llm()
        if llm is None:
            return None
        sys = (_P332_HINT_PROTOCOL_SYSTEM_PROMPT
               .replace("{sub_goal}", sub_goal)
               .replace("{level}", str(stuck_level)))
        try:
            raw = llm.complete(sys, student_text, max_tokens=400, temperature=0.3)
        except Exception as e:
            print(f"[P332 Hint] ❌ provider 全挂 ({type(e).__name__})")
            return None
        txt = (raw or "").strip()
        txt = re.sub(r"\[VIZ:[^\]]*\]", "", txt).strip()
        return txt[:400] if txt else None

    def _p332_socratic(self, text: str, key: str, sub_goal: str, fallback: str) -> str:
        """统一「答错/卡住」反馈：递进 LLM 提示（角色 3）+ 罐头兜底。
        key 标识当前设问；stuck 计数逐次加深；『不知道』直接跳深一级。"""
        if not hasattr(self, "_p332_stuck"):
            self._p332_stuck = {}
        self._p332_stuck[key] = self._p332_stuck.get(key, 0) + 1
        level = self._p332_stuck[key]
        if any(k in text for k in ["不知道", "不会", "没思路", "没头绪", "不懂", "不清楚"]):
            level = max(level, 2)
        level = min(level, 3)
        hint = self._llm_p332_hint(text, sub_goal, level)
        return hint if hint else fallback

    def _p332_clear_stuck(self, *keys) -> None:
        """推进过某设问后清零其 stuck 计数。"""
        if hasattr(self, "_p332_stuck"):
            for k in keys:
                self._p332_stuck.pop(k, None)

    # ---- 角色 2：例题/思考路径 2 协议 ----
    def _llm_p332_example_protocol(self, student_text: str, example_key, current_phase: str) -> Optional[dict]:
        llm = self._get_llm()
        if llm is None:
            return None
        ex_ctx = _EXAMPLE_CONTEXT_MAP_332.get(example_key, "（无上下文）")
        ph_ctx = _EXAMPLE_PHASE_QUESTION_MAP_332.get((example_key, current_phase), f"phase={current_phase}")
        system_prompt = (_P332_EXAMPLE_PROTOCOL_SYSTEM_PROMPT
                         .replace("{example_context}", ex_ctx)
                         .replace("{phase_context}", ph_ctx))
        try:
            raw = llm.complete(system_prompt, student_text, max_tokens=800, temperature=0.0)
        except Exception as e:
            print(f"[P332Protocol] ❌ ex{example_key}/{current_phase}: provider 全挂 ({type(e).__name__})")
            return None
        parsed = self._parse_protocol_json(raw)
        if parsed is None:
            print(f"[P332Protocol] ⚠️ ex{example_key}/{current_phase}: JSON parse 失败 raw={raw[:120]!r}")
            return None
        if "diagnosis" not in parsed or "advance" not in parsed:
            return None
        return parsed

    # ---- 跳级 / 推进 ----
    def _jump_to_p332_example(self, target_key) -> LessonStep:
        """从任何性质 stage 跳到 例题1(1) / 思考(2) / 例题2(3)。"""
        stage_map = {
            1: (LessonStage.P332_EXAMPLE_1, P332_EXAMPLE_1_INTRO, "show_p332_example1_setup", "例题 1（教材例 3）"),
            2: (LessonStage.P332_THINK,     P332_THINK_INTRO,     "show_p332_think_setup",    "思考"),
            3: (LessonStage.P332_EXAMPLE_2, P332_EXAMPLE_2_INTRO, "show_p332_example2_setup", "例题 2（教材例 4）"),
        }
        if target_key not in stage_map:
            return LessonStep(stage=self.stage.value, message="抱歉，没找到对应的题目。")
        target_stage, intro, viz, label = stage_map[target_key]
        self.stage = target_stage
        if not hasattr(self, "_p332_example_subflags"):
            self._p332_example_subflags = {1: set(), 2: set(), 3: set()}
            self._p332_example_phase_idx = {1: 0, 2: 0, 3: 0}
        self._p332_example_subflags[target_key] = set()
        self._p332_example_phase_idx[target_key] = 0
        self._p332_example_done_awaiting_next = None
        return LessonStep(
            stage=self.stage.value,
            message=f"好的，切到{label}：\n\n" + intro,
            canvas_action={"action": viz},
        )

    def _p332_find_next_unanswered_phase(self, example_key, subflags: set) -> Optional[str]:
        from .example_canonicals_332 import EXAMPLE_CONFIGS_332
        if example_key not in EXAMPLE_CONFIGS_332:
            return None
        for phase in EXAMPLE_CONFIGS_332[example_key]["phases"]:
            required = _P332_PHASE_REQUIRED_FLAGS.get((example_key, phase), set())
            if not required.issubset(subflags):
                return phase
        return None

    def _advance_p332_example(self, example_key, ack: str = "") -> LessonStep:
        """例题/思考通关 → 发 solved viz + awaiting_next。学生确认后才切下一题。"""
        solved_map = {1: "show_p332_example1_solved", 2: "show_p332_think_solved", 3: "show_p332_example2_solved"}
        self._p332_example_done_awaiting_next = example_key
        head = ack + "\n\n" if ack else ""
        tail_map = {
            1: "🎉 例题 1 完成！右边是解答图。回个『好』/『继续』，我们看教材的**思考**题。",
            2: "🎉 思考完成！右边画出了两条抛物线。回个『好』/『继续』，我们做**例题 2**。",
            3: "🎉 例题 2 完成！本节例题 + 思考全部做完。回个『好』/『继续』我们看小结 📒。",
        }
        return LessonStep(
            stage=self.stage.value,
            message=head + tail_map[example_key],
            canvas_action={"action": solved_map[example_key]},
        )

    def _continue_to_next_p332_example(self, completed_key) -> LessonStep:
        """学生确认后真正切到下一题 / SUMMARY。"""
        if completed_key == 1:
            self.stage = LessonStage.P332_THINK
            return LessonStep(stage=self.stage.value, message=P332_THINK_INTRO,
                              canvas_action={"action": "show_p332_think_setup"})
        if completed_key == 2:
            self.stage = LessonStage.P332_EXAMPLE_2
            return LessonStep(stage=self.stage.value, message=P332_EXAMPLE_2_INTRO,
                              canvas_action={"action": "show_p332_example2_setup"})
        # 3 → SUMMARY
        self.stage = LessonStage.P332_SUMMARY
        return LessonStep(stage=self.stage.value, message=P332_SUMMARY_MSG,
                          canvas_action={"action": "show_p332_summary_compare"})

    # ---- 例题/思考通用 handler（仿 _handle_p331_example_generic）----
    def _handle_p332_example_generic(self, text: str, example_key) -> LessonStep:
        """例题1 / 思考 / 例题2 共用。三层判断 + partial 累积 + awaiting_next。"""
        from .example_canonicals_332 import EXAMPLE_CONFIGS_332
        from .example_diagnostician_332 import diagnose_example_332, ExampleDiagnosis332

        if not hasattr(self, "_p332_example_phase_idx"):
            self._p332_example_phase_idx = {1: 0, 2: 0, 3: 0}
            self._p332_example_subflags = {1: set(), 2: set(), 3: set()}

        # awaiting_next 检查
        awaiting_key = getattr(self, "_p332_example_done_awaiting_next", None)
        if awaiting_key is not None:
            if _looks_like_ready_to_continue(text):
                self._p332_example_done_awaiting_next = None
                return self._continue_to_next_p332_example(awaiting_key)
            label = {1: "例题 1", 2: "思考", 3: "例题 2"}[awaiting_key]
            return LessonStep(
                stage=self.stage.value,
                message=f"{label} 已经完成 🎉 看完右边的图后回个『好』/『继续』就切到下一个；想再看图随便拖。",
            )

        # 跨题跳级
        skip = _looks_like_skip_to_example_332(text)
        if skip and skip != example_key:
            return self._jump_to_p332_example(skip)

        config = EXAMPLE_CONFIGS_332[example_key]
        phases = config["phases"]
        idx = self._p332_example_phase_idx[example_key]
        current_phase = phases[idx] if idx < len(phases) else phases[-1]

        # Layer 1: 诊断器扫描所有 goal
        dx = diagnose_example_332(text, example_key)

        # Layer 2: 协议兜底
        if dx is None:
            protocol = self._llm_p332_example_protocol(text, example_key, current_phase)
            if protocol is not None:
                diag = protocol.get("diagnosis", "off_topic")
                ack_text = (protocol.get("ack_text") or "请继续。")[:300]
                skip_n = protocol.get("skip_to_example")

                if diag == "skip_request" and skip_n in (1, 2, 3):
                    return self._jump_to_p332_example(skip_n)

                if diag == "correct" and protocol.get("advance") is True:
                    goal_name = protocol.get("hit_goal")
                    flags = set(config["implies"].get(goal_name, set())) if goal_name else set()
                    if not flags:
                        flags = set(_P332_PHASE_REQUIRED_FLAGS.get((example_key, current_phase), set()))
                    if not flags and goal_name:
                        flags = {f"{goal_name}_done"}
                    dx = ExampleDiagnosis332(
                        hit_goal=goal_name or "", hit_goals=[goal_name] if goal_name else [],
                        implied_flags=flags, label="完全正确（协议）", via="protocol",
                    )
                    # fall through
                elif diag in ("partial", "wrong", "off_topic"):
                    return LessonStep(stage=self.stage.value, message=ack_text)

        # Layer 3: 仍 None → deterministic 提示
        if dx is None:
            return LessonStep(
                stage=self.stage.value,
                message="再想想？把你的答案写完整些（坐标写成 (a, b)，方程写成 y²=2px 这样）。",
            )

        # 命中：累积 + 判定收尾或继续节奏
        self._p332_example_subflags[example_key] |= dx.implied_flags
        subflags = self._p332_example_subflags[example_key]

        if config["done_fn"](subflags):
            self._p332_example_phase_idx[example_key] = len(phases)
            return self._advance_p332_example(example_key, ack="✅ 完全正确！")

        # 部分命中：找下一未答完 phase
        next_phase = None
        next_missing: set = set()
        for ph in phases:
            required = _P332_PHASE_REQUIRED_FLAGS.get((example_key, ph), set())
            missing = required - subflags
            if missing:
                next_phase = ph
                next_missing = missing
                break
        if next_phase is None:
            return self._advance_p332_example(example_key, ack="✅ 完全正确！")

        self._p332_example_phase_idx[example_key] = phases.index(next_phase)

        # missing-aware prompt（多-flag phase 内部部分命中 → 精准追问，坑10）
        next_prompt = None
        next_required = _P332_PHASE_REQUIRED_FLAGS.get((example_key, next_phase), set())
        if len(next_missing) == 1 and len(next_required) >= 2:
            single_missing = next(iter(next_missing))
            next_prompt = _P332_PHASE_PROMPT_BY_MISSING.get((example_key, next_phase, single_missing))
        if next_prompt is None:
            next_prompt = _EXAMPLE_STUDENT_PROMPT_332.get((example_key, next_phase), "请继续。")

        # 干净 ack（不暴露内部 goal 名，坑9）
        prefix = "" if next_prompt.startswith("✅") else "✅ 收到。\n\n"
        return LessonStep(stage=self.stage.value, message=prefix + next_prompt)

    def _handle_p332_example_1(self, text: str) -> LessonStep:
        return self._handle_p332_example_generic(text, 1)

    def _handle_p332_think(self, text: str) -> LessonStep:
        return self._handle_p332_example_generic(text, 2)

    def _handle_p332_example_2(self, text: str) -> LessonStep:
        return self._handle_p332_example_generic(text, 3)

    # ---- 性质短答 + 开场/总结 handler ----
    def _handle_p332_intro(self, text: str) -> LessonStep:
        """1. 开场：学生任意回应即推进 RANGE（确定性）。"""
        skip = _looks_like_skip_to_example_332(text)
        if skip:
            return self._jump_to_p332_example(skip)
        self.stage = LessonStage.P332_RANGE
        return LessonStep(stage=self.stage.value, message=P332_RANGE_MSG,
                          canvas_action={"action": "show_p332_range_setup"})

    def _handle_p332_range(self, text: str) -> LessonStep:
        """2. 范围：2 要素（x≥0 / y∈R）partial 累积。推进=确定性；反馈=角色3 阶梯。"""
        skip = _looks_like_skip_to_example_332(text)
        if skip:
            return self._jump_to_p332_example(skip)
        if not hasattr(self, "_p332_range_done"):
            self._p332_range_done = set()
        done = self._p332_range_done
        # Layer 1 关键词
        if _looks_like_p332_range_x(text):
            done.add("x")
        if _looks_like_p332_range_y(text):
            done.add("y")
        # Layer 2 角色 1 enum 兜底（只分类不驱动状态）
        if not {"x", "y"}.issubset(done):
            hit = self._resolve_phase_answer(text, "p332_range", lambda _t: None)[0]
            if hit == "x_range":
                done.add("x")
            elif hit == "y_range":
                done.add("y")
            elif hit == "both":
                done.update({"x", "y"})
        self._p332_range_done = done
        # 两要素齐 → 推进 SYMMETRY（确定性转场）
        if {"x", "y"}.issubset(done):
            self._p332_clear_stuck("range_x", "range_y", "range_both")
            self._p332_range_done = set()
            self.stage = LessonStage.P332_SYMMETRY
            return LessonStep(stage=self.stage.value, message=P332_RANGE_DONE_MSG,
                              canvas_action=[{"action": "show_p332_range_solved"},
                                             {"action": "show_p332_symmetry_setup"}])
        # 只答 x → 表扬 x、追问 y（坑10）
        if "x" in done:
            sub = ("学生已答对 x 的范围（x≥0），还差 **y 的范围**：方程 y²=2px 里 y² 可取任意非负值，"
                   "所以 y 取遍全体实数 y∈R。引导他想 y 有没有限制，不要直接给出。")
            fb = "✅ $x$ 的范围对了（$x\\ge 0$）。那 **$y$ 的范围**呢？方程里 $y$ 受不受限制？"
            return LessonStep(stage=self.stage.value, message=self._p332_socratic(text, "range_y", sub, fb))
        # 只答 y → 表扬 y、追问 x（坑10）
        if "y" in done:
            sub = ("学生已答对 y 的范围（y∈R），还差 **x 的范围**：由 y²=2px≥0、p>0 得 x≥0。"
                   "引导他从 y²≥0 推 x，不要直接给出。")
            fb = "✅ $y\\in\\mathbb{R}$ 对了。那 **$x$ 的范围**呢？由 $y^2=2px\\ge 0$、$p>0$ 能推出 $x$ 满足什么？"
            return LessonStep(stage=self.stage.value, message=self._p332_socratic(text, "range_x", sub, fb))
        # 都没答 → 角色3 提示
        sub = ("学生在想抛物线 y²=2px(p>0) 的范围（x、y 各自取值）。正确：由 y²≥0、p>0 得 x≥0；y 取遍全体实数。"
               "引导他往这两点想，不要直接给出。")
        fb = ("提示：抛物线 $y^2=2px\\,(p>0)$。因为 $y^2\\ge 0$，由方程能推出 $x$ 的范围；"
              "而 $y$ 有没有限制？（$x$、$y$ 两个都要说）")
        return LessonStep(stage=self.stage.value, message=self._p332_socratic(text, "range_both", sub, fb))

    def _handle_p332_symmetry(self, text: str) -> LessonStep:
        """3. 对称性：仅 x 轴；纠正「有对称中心」误区。推进=确定性；反馈=角色3。"""
        skip = _looks_like_skip_to_example_332(text)
        if skip:
            return self._jump_to_p332_example(skip)
        has_xaxis = _looks_like_p332_sym_xaxis(text)
        misconception = _looks_like_p332_sym_center_misconception(text)
        # Layer 2 enum 兜底
        if not has_xaxis:
            hit = self._resolve_phase_answer(text, "p332_symmetry", lambda _t: None)[0]
            if hit == "x_axis":
                has_xaxis = True
            elif hit == "center_misconception":
                misconception = True
        # 答对 x 轴 → 推进（若兼有对称中心误区，转场里温和纠正）
        if has_xaxis:
            self._p332_clear_stuck("sym")
            self.stage = LessonStage.P332_VERTEX
            if misconception:
                msg = ("✅ 关于 $x$ 轴对称这点对了。不过纠正一下：抛物线**没有对称中心**，"
                       "它只关于 $x$ 轴（轴）对称——这和椭圆/双曲线不同。\n\n" + P332_SYMMETRY_VERTEX_Q)
            else:
                msg = P332_SYMMETRY_DONE_MSG
            return LessonStep(stage=self.stage.value, message=msg,
                              canvas_action=[{"action": "show_p332_symmetry_solved"},
                                             {"action": "show_p332_vertex_setup"}])
        # 误区：以为有对称中心 → 角色3 纠正（不推进）
        if misconception:
            sub = ("学生以为抛物线像椭圆/双曲线那样有对称中心或关于 y 轴对称。纠正：以 -x 代 x 方程会变（开口反向），"
                   "故抛物线**不**关于 y 轴、也**没有**对称中心；只有以 -y 代 y 不变，故只关于 x 轴对称。温和纠正并引导重答。")
            fb = ("🤔 抛物线其实**没有**对称中心哦。试试：把方程里的 $x$ 换成 $-x$，方程变不变？"
                  "再把 $y$ 换成 $-y$ 呢？由此抛物线只关于哪条线对称？")
            return LessonStep(stage=self.stage.value, message=self._p332_socratic(text, "sym", sub, fb))
        # 没答到 → 角色3 提示
        sub = ("学生在判断抛物线 y²=2px 的对称性。正确：以 -y 代 y 方程不变 → 关于 x 轴对称；"
               "以 -x 代 x 方程改变 → 不关于 y 轴、无对称中心。引导他用代换法想，不要直接给出。")
        fb = "提示：把方程 $y^2=2px$ 里的 $y$ 换成 $-y$，方程变不变？变不变说明它关于哪条线对称？"
        return LessonStep(stage=self.stage.value, message=self._p332_socratic(text, "sym", sub, fb))

    def _handle_p332_vertex(self, text: str) -> LessonStep:
        """4. 顶点：唯一=原点。推进=确定性；反馈=角色3。"""
        skip = _looks_like_skip_to_example_332(text)
        if skip:
            return self._jump_to_p332_example(skip)
        has_origin = _looks_like_p332_vertex_origin(text)
        if not has_origin:
            hit = self._resolve_phase_answer(text, "p332_vertex", lambda _t: None)[0]
            if hit == "origin":
                has_origin = True
        if has_origin:
            self._p332_clear_stuck("vertex")
            self.stage = LessonStage.P332_ECCENTRICITY
            return LessonStep(stage=self.stage.value, message=P332_VERTEX_DONE_MSG,
                              canvas_action=[{"action": "show_p332_vertex_solved"},
                                             {"action": "show_p332_ecc_setup"}])
        sub = ("学生在找抛物线 y²=2px 的顶点。正确：顶点 = 抛物线与轴(x轴)的交点；令 x=0 得 y=0，"
               "故顶点是原点 (0,0)，只有 1 个。引导他令 x=0 想，不要直接给出。")
        fb = "提示：顶点是抛物线与它的轴（$x$ 轴）的交点。在 $y^2=2px$ 中令 $x=0$ 得什么点？这样的顶点有几个？"
        return LessonStep(stage=self.stage.value, message=self._p332_socratic(text, "vertex", sub, fb))

    def _handle_p332_eccentricity(self, text: str) -> LessonStep:
        """5. 离心率：e=1。推进=确定性；反馈=角色3。答对后进入例题 1。"""
        skip = _looks_like_skip_to_example_332(text)
        if skip:
            return self._jump_to_p332_example(skip)
        has_e1 = _looks_like_p332_ecc_1(text)
        if not has_e1:
            hit = self._resolve_phase_answer(text, "p332_eccentricity", lambda _t: None)[0]
            if hit == "e_equals_1":
                has_e1 = True
        if has_e1:
            self._p332_clear_stuck("ecc")
            self.stage = LessonStage.P332_EXAMPLE_1
            if not hasattr(self, "_p332_example_phase_idx"):
                self._p332_example_phase_idx = {1: 0, 2: 0, 3: 0}
                self._p332_example_subflags = {1: set(), 2: set(), 3: set()}
            return LessonStep(stage=self.stage.value,
                              message=P332_ECC_DONE_MSG + "\n\n" + P332_EXAMPLE_1_INTRO,
                              canvas_action=[{"action": "show_p332_ecc_solved"},
                                             {"action": "show_p332_example1_setup"}])
        sub = ("学生在求抛物线的离心率。正确：由抛物线定义，动点到焦点距离 |MF| = 到准线距离 d，"
               "所以 e=|MF|/d=1。引导他回忆定义里 |MF| 和 d 的关系，不要直接报 1。")
        fb = ("提示：离心率 $e=\\dfrac{|MF|}{d}$。回忆抛物线的**定义**——点到焦点的距离 $|MF|$ "
              "和到准线的距离 $d$ 是什么关系？所以 $e=?$")
        return LessonStep(stage=self.stage.value, message=self._p332_socratic(text, "ecc", sub, fb))

    def _handle_p332_summary(self, text: str) -> LessonStep:
        """9. 总结。deterministic 结课。"""
        self.summary_turns += 1
        if _looks_like_lesson_end(text) or self.summary_turns >= 6:
            self.lesson_ended = True
            return LessonStep(
                stage=self.stage.value,
                message=(
                    "👏 恭喜完成 3.3.2 课程！\n\n"
                    "你已掌握抛物线的 4 条几何性质（范围、对称性、顶点、离心率），"
                    "以及三曲线离心率的统一（$e<1$ 椭圆 / $e=1$ 抛物线 / $e>1$ 双曲线）。\n\n"
                    "[LESSON_END]"
                ),
            )
        return LessonStep(
            stage=self.stage.value,
            message="还有什么问题想问？或者输入「结束」结课。",
        )

    # ================================================================

    def _log(self, role: str, content: str) -> None:
        self.history.append({"role": role, "content": content})
